window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-neurologia-neu-unico"]={"block":"medcurso:medcurso-neurologia-neu-unico","label":"Medcurso · NEU UNICO","count":413,"questions":[{"id":"medcurso-neurologia-neu-unico-345436","number":"345436","sourceNumber":"345436","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A cefaleia é um dos sintomas mais frequentes atendidos pelas equipes da atenção\nprimária. Dentro do universo das cefaleias, a causa mais comum nesse nível de atenção é a:","options":{"A":"Cefaleia tensional.","B":"Cefaleia tipo migrânea (enxaqueca).","C":"Cefaleia causada por infecções sistêmicas agudas.","D":"Cefaleia associada a doenças intracranianas graves como tumores ou infecções cerebrais."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-345440","number":"345440","sourceNumber":"345440","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa que apresenta CORRETAMENTE uma característica de\ngravidade ou sinal de alerta (red flag) durante um episódio de cefaléia:","options":{"A":"Presença de aura.","B":"Associação com náuseas e vômitos.","C":"Início súbito, atingindo intensidade máxima em até um minuto.","D":"Cefaleia bilateral em aperto associada à dor à palpação do trapézio."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-345446","number":"345446","sourceNumber":"345446","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O exame cuidadoso dos olhos é de extrema utilidade na avaliação clínica do paciente\ncomatoso. O achado de pupilas simétricas e muito pequenas é sugestivo de:","options":{"A":"Lesão pontina.","B":"Hérnia de uncus.","C":"Síndrome seratoninérgica.","D":"Compressão do terceiro par craniano."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-345448","number":"345448","sourceNumber":"345448","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 32 anos apresenta episódio súbito de cefaleia intensa e evolui com redução\ndo nível de consciência em poucas horas. No\nexame físico apresenta sinais de irritação meníngea e\nparalisia do terceiro par craniano à esquerda com midríase e perda do reflexo fotomotor ipsilateral.\nO médico que o atende solicita tomografia computadorizada do crânio na suspeita clínica de se\ntratar de hemorragia subaracnóidea a partir da artéria.","options":{"A":"Cerebral anterior.","B":"Cerebral média.","C":"Carótida posterior.","D":"Comunicante anterior."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-343777","number":"343777","sourceNumber":"343777","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A crise convulsiva febril corresponde a um dos problemas neurológicos mais frequentes\nobservados na população pediátrica e\nocorre em sua maioria em associação a infecções virais. A\nrespeito da classificação das crises convulsivas febris, marque a opção correta.","options":{"A":"Crise febril simples é aquela que se apresenta como uma crise tônico-clônica generalizada com\nduração inferior a 30 minutos, que não há recorrência nas próximas 24 horas e a recuperação é\nespontânea e completa.","B":"A crise febril complexa é definida por uma ou mais das seguintes características: crises focais;\ncrises seguidas de alterações neurológicas\npós-ictais, como a Paralisia de Todd; duração superior a\n30 minutos; e, recorrência em menos de 24 horas.","C":"O estado de mal epiléptico febril é uma crise febril com duração acima de 30 minutos, podendo\ncaracterizar-se por uma única crise prolongada, ou, então, crises subentrantes, ou seja, crises\nrecorrentes entre as quais não há recuperação completa do nível de consciência.","D":"Crise febril complexa é aquela que se apresenta como uma crise tônico-clônica generalizada\ncom duração inferior a 15 minutos, que não há\nrecorrência nas próximas 24 horas."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-343779","number":"343779","sourceNumber":"343779","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Adolescente procura atendimento em Unidade de Pronto Atendimento com queixa de\ncefaleia hemicraniana esquerda, de característica pulsátil, de forte intensidade, com duração média\nde 48 horas, precedida por alteração da visão. Relata não ser o primeiro episódio. O exame físico\nnão apresenta alterações e a pressão arterial está normal. Apresenta antecedentes de migrânea na\nfamília. Qual das opções abaixo pode ser o tratamento sintomático para essa condição clínica?","options":{"A":"Dipirona, Flunarizina, Amitriptilina.","B":"Gabapentina, Paracetamol, Dipirona.","C":"Propanolol, Ibuprofeno, Gabapentina.","D":"Dipirona, Ibuprofeno, Naproxeno."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-345459","number":"345459","sourceNumber":"345459","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Demência é um quadro clínico em que ocorre perturbação de múltiplas funções\ncognitivas e se faz presente na vida de\nmuitos idosos. Sobre esse tema, assinale a alternativa\nCORRETA:","options":{"A":"A Doença de Pick tem início pré-senil (a partir dos 45 anos).","B":"Hemorragias não se configuram como uma etiologia das Demências Vasculares.","C":"Os principais tipos de Demências Vasculares é Demência de Lewy.","D":"Infecções pelo HIV e sífilis são causas irreversíveis de demência."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-345497","number":"345497","sourceNumber":"345497","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente pré-escolar, com diagnóstico prévio de epilepsia, chega à emergência em\ncrise convulsiva, iniciada ainda em casa. O tempo de chegada ao hospital foi de 15 minutos e o\npaciente está em avaliação há 5 minutos, foi medicado e está entrando no período pós-ictal.\n\nNota-se febre, leve desidratação e diarreia iniciada há 2 dias. Sobre o caso, assinale a alternativa\nCORRETA:","options":{"A":"A causa mais provável da descompensação desse paciente é o esquecimento das doses de\nmanutenção, mesmo em casos de boa aderência e mesmo que a família negue esquecimentos.","B":"Trata-se de uma crise convulsiva febril simples, de caráter benigno, cujo tratamento deve ser\ndirecionado para o controle rigoroso da febre e identificação do foco.","C":"O paciente apresentou estado de mal epilético de causa sintomática aguda.","D":"O paciente não pode ser classificado como crise convulsiva febril, por apresentar critérios de\nexclusão."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281089","number":"281089","sourceNumber":"281089","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um determinado paciente com deficit motor focal, que se instalou há uma hora, foi\nsubmetido a uma modalidade específica de RNM encefálica onde foi observado presença de\n\"mismatch\". Isto significa:","options":{"A":"Que o AVE é isquêmico, e que há alto risco para transformação hemorrágica.","B":"Que o AVE é isquêmico, e que há área de penumbra viável.","C":"Que o AVE é hemorrágico.","D":"Que não há lesão vascular isquêmica ou hemorrágica.","E":"Que há sinais de envelhecimento encefálico desproporcional à faixa etária do paciente."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283272","number":"283272","sourceNumber":"283272","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 25 anos, sexo feminino, em uso de contraceptivo oral comparece em\npronto atendimento referindo cefaleia\nholocraniana, de forte intensidade, em aperto, associada a\nnáuseas e vômitos, confusão mental com alteração do nível de consciência. Nega crises\nconvulsivas prévias e quaisquer outras doenças. Assinale a alternativa correta quanto ao\ndiagnóstico provável.","options":{"A":"Migrânea.","B":"Cefaleia em salvas.","C":"Arterite temporal.","D":"Trombose do seio cavernoso."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281093","number":"281093","sourceNumber":"281093","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 52 anos, hipertenso e diabético apresenta dois dias de evolução de\nvertigem de início súbito sem relação com mobilização, associada à diplopia. Foi realizada a\nmanobra de Dix-Halpike que evidenciou nistagmo sem latência e não fatigável. Considerando a\nhipótese diagnóstica principal, o exame complementar mais indicado é:","options":{"A":"Teste terapêutico com meclizina.","B":"Ressonância magnética do encéfalo.","C":"Tomografia computadorizada do encéfalo.","D":"Eletronistagmografia","E":"Audiometria."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281097","number":"281097","sourceNumber":"281097","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 20 anos, informa que nos últimos 3 anos, vem apresentando quadros\ncaracterizados por: zumbido, tinitus,\nvertigem e hipoacusia. Minutos após, paciente apresenta\ndificuldade para articular a palavra e formigamento do pescoço para baixo, queixas que duram 50\nmin. Esse quadro é seguido por dor pulsátil em região occipital bilateral que se inicia da fraca\nintensidade em que se observa mudança de quadro para forte intensidade com fonofobia e náusea.\nA dor dura por 3 dias e a determinada situação, repete-se de 4 a 5x/mês. Qual poderia ser o\npossível diagnóstico?","options":{"A":"Migrânea sem aura.","B":"Migrânea com aura.","C":"Hemivrania paroxística.","D":"Migrânea basilar.","E":"Migrânea hipoestésica familiar."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283279","number":"283279","sourceNumber":"283279","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Existe uma reação muito incômoda causada por medicações dopaminérgicas (inclui\nalgumas outras medicações como a metoclopramida). É uma reação idiossincrática que pode\nacontecer a qualquer momento do uso da medicação, inclusive na primeira dose. Caracteriza-se\npor uma sensação interna de inquietação, \"agonia\" e vontade de se mexer para aliviar essa\nsensação. Algumas pessoas sentem como dores ou parestesias. Que condição é essa?","options":{"A":"Parkinsonismo.","B":"Discinesia tardia.","C":"Distonia refratária.","D":"Acatisia."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283282","number":"283282","sourceNumber":"283282","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Das abaixo, a melhor terapêutica abortiva para cefaleia em salvas é:","options":{"A":"Acupuntura.","B":"Haloperidol.","C":"Inalação máscara de oxigênio.","D":"Gababentina."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283285","number":"283285","sourceNumber":"283285","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O protocolo SPIKES é utilizado na prática médica para:","options":{"A":"Estabelecer prognostico em paciente oncológico.","B":"Acompanhamento clínico de pacientes com leucemias agudas.","C":"Escore prognostico em UTls.","D":"Comunicação de más notícias."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281107","number":"281107","sourceNumber":"281107","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 68 anos, diabética e hipertensa, em uso de metformina e enalapril dá\nentrada no pronto socorro por 5 horas de\nevolução de hemiparesia à direita, associada a afasia.\nTomografia de crânio normal na admissão. Assinale a assertiva que contém o território vascular e\nconduta inicial corretos.","options":{"A":"Artéria cerebral média esquerda, trombólise.","B":"Artéria cerebral média esquerda, ácido acetil salicílico 300mg.","C":"Artéria cerebral anterior esquerda, trombólise.","D":"Artéria cerebral anterior esquerdaa, ácido acetil salicílico 300mg.","E":"Artéria basilar, anticoagulação com varfarina."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281111","number":"281111","sourceNumber":"281111","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma preocupação a se ter com a população com idade acima de 65 anos é o maior\nnúmero de ocorrências de efeitos adversos com eventuais drogas em uso. Isso se deve a um\nconjunto de fatores causais. Com base nessas informações, assinale a alternativa que apresenta\num fator causal.","options":{"A":"Elevada incidência de tumores.","B":"Doses maiores, que sempre devem ser usadas, para surtir o efeito desejado.","C":"Infecções de repetição muito comum.","D":"Inapetência, que ocorre em 90% desses indivíduos.","E":"Metabolismo das drogas alterado com a idade."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283294","number":"283294","sourceNumber":"283294","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O Transtorno do Espectro Autista (TEA) ainda não tem uma etiologia devidamente\nesclarecida, sendo sinais de alerta observados em crianças, os descritos abaixo, EXCETO:","options":{"A":"Dificuldades em contatos visuais.","B":"Alteração de comportamento somente com estranhos.","C":"Resposta anormais as sensações, como ao barulho de motores.","D":"Tendência a brincar sozinho."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281122","number":"281122","sourceNumber":"281122","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 23 anos de idade, relata episódios de lapsos breves e súbitos de\nconsciência, sem perda postural, com duração\nde segundos, sem confusão pós-ictal. Realizou EEG\nque apresentou descargas em ponta-onda generalizada simétrica de 3 Hz. Das drogas listadas\nabaixo, assinale a menos indicada para o caso.","options":{"A":"Ácido valpróico.","B":"Etossuximida.","C":"Gabapentina.","D":"Clonazepam.","E":"Lamotrigina."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281151","number":"281151","sourceNumber":"281151","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de 10 anos apresenta o diagnóstico de síndrome de Tourette. Em relação a\nessa conduta, assinale a alternativa correta.","options":{"A":"O tratamento medicamentoso é mandatório nos pacientes com tiques vocais.","B":"Consiste em critério clínico para esse diagnóstico a presença de tiques motores nos últimos 6\nmeses.","C":"Para que esse diagnóstico seja considerado, o início dos tiques deve ser precoce, antes dos 12\nanos.","D":"O eletroencefalograma mostra anormalidades epileptiformes, presentes em até 80% dos\npacientes.","E":"Para esse diagnóstico, considera-se que tiques vocais únicos ou múltiplos devam estar\npresentes em algum momento da vida do paciente."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-281168","number":"281168","sourceNumber":"281168","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os pacientes portadores de doença arterial carotídea podem apresentar manifestações\nclínicas com graus variados, exceto:","options":{"A":"placas de Hollenhorst.","B":"isquemia cerebral ipsilateral.","C":"ataque isquêmico transitório.","D":"afasia quando ocorre no lado esquerdo.","E":"hematoma cerebral intra parenquimatoso."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283361","number":"283361","sourceNumber":"283361","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No ambulatório de atendimento à Saúde do Idoso realizar a AGA - Avaliação Geral\nAmpla constitui a base de um bom atendimento geriátrico. Várias escalas são usadas nesse\natendimento, visando à caracterização de problemas cognitivos, função, humor, marcha e\ngraduação de quadros de demências. Sobre essas escalas assinale a alternativa correta:","options":{"A":"O mini exame do estado mental (MEEM) é um instrumento extremamente útil na triagem\ncognitiva por ser simples e de fácil avaliação\nneste exame avaliamos os atributos psíquicos de\nOrientação, Memória, Evocação, Linguagem e Humor.","B":"O instrumento APGAR de FAMÍLIA é uma escala que serve para refletir a experiência do idoso\ncom seus relacionamentos mais próximos. Quando temos um resultado menor que três pontos\ncaracterizamos uma deficiência acentuada desse suporte familiar para o paciente geriátrico.","C":"A escala de Katz é uma das mais utilizadas na geriatria e avalia a independência em atividades\ninstrumentais de vida diária.","D":"Teste do relógio é um teste de rastreio que avalia as funções executivas e habilidade\nvisuoespacial e com pontuação de 0 a 10 pontos."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-247142","number":"247142","sourceNumber":"247142","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Chega ao pronto-socorro um paciente de 52 anos de idade, apresentando crise\nconvulsiva. Realizado o atendimento inicial e\napós o período ictal, o paciente informa ser o primeiro\nepisódio de crise convulsiva. Refere cefaleia há um ano com piora progressiva nos dois últimos\nmeses, intensificado há uma semana. Antecedente pessoal: hipertensão arterial em tratamento com\ndiurético e captopril. Ao exame físico: PA=160x95 mmHg, frequência cardíaca de 68 bpm, sem\noutras alterações clínicas. Ao exame neurológico: hemiparesia direita de predomínio braquial grau\nIV, liberação piramidal à direita, fundo de olho com edema de papila à direita e atrofia de papila à\nesquerda e déficit de olfato e gustação. A hipótese diagnóstica é:","options":{"A":"Hipertensão arterial intracraniana por hemorragia subaracnóidea.","B":"Hipertensão intracraniana por tumor cerebral.","C":"Esclerose múltipla.","D":"Esclerose lateral amiotrófica.","E":"Doença desminilizante."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-247143","number":"247143","sourceNumber":"247143","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Aneurisma de artéria cerebral comunicante posterior, quando expande ou sangra,\ncostuma comprimir o:","options":{"A":"V nervo craniano.","B":"IV nervo craniano.","C":"III nervo craniano.","D":"VI nervo craniano.","E":"VII nervo craniano."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-247150","number":"247150","sourceNumber":"247150","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No atendimento de um paciente com acidente vascular cerebral isquêmico na fase\naguda, pode-se afirmar que:","options":{"A":"A hipotensão arterial é rara, porém deve ser prontamente revertida.","B":"A antibioticoprofilaxia é recomendada devido ao risco de aspiração pulmonar.","C":"A temperatura corporal elevada não é um fator relacionado com pior prognóstico.","D":"O decúbito do paciente deve ser mantido a 90 graus para reduzir as chances de edema cerebral\nprecoce.","E":"As soluções glicosadas devem ser usadas de rotina a fim de evitar hipoglicemia."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-247153","number":"247153","sourceNumber":"247153","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher queixa-se de incomodo nas pernas que a obriga a movê-las vigorosamente ao\nandar, o que rapidamente alicia os sintomas. Esse incômodo inicia-se à noite quando se senta para\ndescansar, mas é muito pior ao se deitar, impedindo-a de dormir. Qual o diagnóstico?","options":{"A":"Polineuropatia periférica.","B":"Movimento periódico dos membros.","C":"Síndrome das pernas inquietas.","D":"Varizes de membros inferiores.","E":"Ansiedade generalizada."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-247162","number":"247162","sourceNumber":"247162","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, etilista (1 litro de destilado ao dia) há 5 anos.\nRefere que há uma semana iniciou com\nparestesias nos pés, que progrediram de maneira\nascendente. Há dois dias evoluiu com redução progressiva de força em MMII e há um dia não\nconsegue mais deambular. O exame neurológico evidencia força grau I e ausência de reflexos em\nMMII, força grau V em MMSS com reflexos preservados. As sensibilidades dolorosa e vibratória\nestão preservadas; não foi evidenciado nível sensitivo. O hemograma demonstra anemia\nmacrocítica. A radiografia de coluna lombossacral é normal. O exame do liquor revela: celularidade\n\n= 4 células/mm³, glicose= 70mg/dL; proteína= 210 mg/dL. Assinale a alternativa CORRETA, que\napresenta o diagnóstico mais provável.","options":{"A":"Deficiência de vitamina B12.","B":"Polineuropatia alcoólica.","C":"Síndrome de Guillain-Barré.","D":"Mielite transversa.","E":"Neurossífilis."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-247163","number":"247163","sourceNumber":"247163","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Paciente do\nsexo feminino, 60 anos, iniciou com cefaleia\nsúbita e intensa acompanhada de hemiparesia\nesquerda com predomínio braquial. Chega ao hospital consciente, atendendo a comandos, com\npontuação na Escala de coma de Glasgow de 15. PA= 150/90 mmHg; FC= 68 bpm; FR= 15 rpm,\npadrão respiratório normal, pupilas isocóricas e fotorreagentes. Está aguardando a realização de\numa tomografia de crânio quando evolui com torpor, midríase fixa à direita e piora do déficit motor\nà\nesquerda. A pontuação na Escala de Coma de Glasgow cai para 7. Qual a causa mais provável do\nrebaixamento de nível de consciência e qual a conduta imediata a ser tomada?","options":{"A":"Hidrocefalia aguda - Derivação ventricular externa","B":"Hipertensão intracraniana - Tomografia de crânio de urgência","C":"Crise convulsiva generalizada - Hidantalização.","D":"Hérnia transtentorial central - Manitol em bolus.","E":"Hérnia do uncus - Incubação orotraqueal."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-251907","number":"251907","sourceNumber":"251907","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente ASM, analfabeta, 80 anos, avaliada na UBS do Universitário no dia de\natendimento da Saúde do Idoso pela\npreceptora da unidade relata antecedentes de DM, HAS,\nOsteoporose e Osteoartrose de joelhos. - Inventário medicamentoso: omeprazol em jejum,\nIbuprofeno 8/8 h se dor, Hidroclorotiazida 25 mg/dia, atenolol 50 mg/dia, Glibenclamida 5 mg 3 x dia\nMetformina 850mg 3x dia, AAS 100mg/dia, Clonazepam 0,5mg a noite e Amitriptilina 25 mg a noite,\nsinvastatina20 mg, ômega 3 e , alendronato de sódio 70 mg, cálcio e vitamina D. - Queixa Principal:\ndor nos joelhos e dificuldade para deambulação há aproximadamente 2 anos. Interrogatório\nSintomatológico: fadiga, astenia, urgência miccional, dor no corpo tudo, rigidez articular matinal,\ndesmotivação, insônia, diminuição de memória recente e tonturas diárias. Realizado AGA\n(avaliação geriátrica ampla/Funcional - Global) encontrando: Miniavaliação do estado mental\n(MEEM): 9 pontos. Escala geriátrica de depressão (EGD) 11 pontos, AIVD: 14/27 precisa de ajuda\npara uso de telefone, gerenciar medicamentos, finanças, preparar refeições e transporte. AVD: 2/6:\n\n+ continência e alimentação. Get up and GO: 33 segundos. Deambula com dispositivoauxiliar da\nmarcha IMC: 23Kg/m2 CP(circunferência da panturrilha)= 33 cm; Segundo o resultado da\nAvalização Funcional da paciente, que lista de problemas e ou Síndromes Geriátricas estão\npresente nesta paciente no momento da avaliação, exceto:","options":{"A":"Depressão, Insuficiência Cognitiva.","B":"Dependência, Risco de quedas.","C":"Polifarmácia, Medicamentos inapropriados.","D":"Desnutrição, Imobilidade, delirium."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-251917","number":"251917","sourceNumber":"251917","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre enxaqueca, assinale a alternativa INCORRETA:","options":{"A":"Existem pontos de gatilho que desencadeiam a dor, como: odores fortes, tensão, ingesta de\ngorduras. Os anticonvulsivantes estão incluídos no arsenal terapêutico.","B":"Existem duas formas de enxaqueca: com áurea e sem áurea, sendo esta última, a forma mais\ncomum. Os benzodiazepínicos podem ser prescritos.","C":"É uma doença Crônica comum, considerada pela OMS (Organização Mundial da Saúde) como\numa das quatro doenças mais incapacitantes,\ninclusive, pode ser tratada com antidepressivos.","D":"É uma afecção que pode ser prevenida e tratada. Dentre as classes medicamentosas, os\nbetabloqueadores podem ser usados no tratamento."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-217644","number":"217644","sourceNumber":"217644","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O diagnóstico de hidrocefalia de pressão normal é improvável quando o paciente\napresenta:","options":{"A":"Papiledema.","B":"Apraxia.","C":"Incontinência urinária.","D":"Demência."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-217702","number":"217702","sourceNumber":"217702","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As convulsões são um dos problemas neurológicos mais frequentes da febre. Com\nrelação à crise convulsiva febril na infância qual das alternativas abaixo está CORRETA?","options":{"A":"A faixa etária na qual a crise convulsiva febril ocorre é entre os 6 meses e 6 anos de idade.","B":"As crises convulsivas febris não podem ser classificadas em complexas, tendo como\napresentação única a crise convulsiva do tipo simples.","C":"Atraso no desenvolvimento neuropsicomotor não é considerado fator de risco importante para\nprimeira crise convulsiva febril.","D":"Após o primeiro episódio de crise convulsiva febril simples é necessário iniciar tratamento\nprofilático."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-217647","number":"217647","sourceNumber":"217647","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, de 28 anos, mudou-se para área de abrangência da USF do\nMocinha Magalhães e procura o acolhimento da unidade com queixa de cefaleia há 8 horas, de\nmoderada intensidade, hemicraniana à direita, acompanhada de fotofobia, fonofobia, náuseas e\nvômitos. Tem crises semelhantes, 1 a 2 vezes por semana (exceto no período perimenstrual,\nquando tem crises diárias), desde os 15 anos de idade. Não fuma, não bebe e não usa drogas.\n\nMora com os pais e com um irmão de 20 anos. Refere que sua mãe tem o mesmo quadro e ambas\nprocuram atendimento médico apenas nos momentos da crise, geralmente no pronto-socorro da\ncidade onde moravam. O exame clínico é normal. Qual diagnóstico é compatível com o quadro\nclínico da paciente?","options":{"A":"Cefaleia tensional.","B":"Enxaqueca sem aura.","C":"Cefaleia em salvas.","D":"Cefaleia secundária."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-217650","number":"217650","sourceNumber":"217650","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 92 anos portadora de doença de Parkinson, com múltiplas contraturas,\nafasia, quadro demencial, má conservação de\ndentes e incontinência urinária e fecal, foi internada\npara tratamento de úlcera por pressão com infecção secundária, submetida a debridamento\ncirúrgico. Essas condições permitem afirmar que a paciente apresenta:","options":{"A":"Síndrome de fragilidade.","B":"Síndrome de imobilidade.","C":"Demência por corpúsculos de Lewy.","D":"Hidrocefaleia de pressão normal."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-217654","number":"217654","sourceNumber":"217654","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente idosa de 87 anos foi trazida pela filha ao posto de saúde do Universitário após\nter sofrido duas quedas sem maiores\nconsequências traumáticas, enquanto andava no período\ndiurno dentro de sua residência. Apresentou IMC = 19, critérios para a síndrome de fragilidade e\nfazia uso de rivastigmina, memantina, losartana, vitamina D e aspirina. Segundo a filha, o\napartamento havia sido adaptado para a maior segurança e conforto da idosa, com colocação de\nbarras de apoio no banheiro e corrimão no corredor. Visando estabelecer estratégias para a\nredução de riscos relacionados à futuras quedas, a intervenção mais efetiva a ser indicada é:","options":{"A":"Retirar os tapetes da casa e evitar o uso de cera nos pisos para reduzir os fatores de risco\nextrínsecos para queda.","B":"Suspender por tempo indeterminado o uso da aspirina para evitar os riscos de um possível\nsangramento após trauma.","C":"Iniciar um programa regular e orientado de exercícios físicos, visando à redução dos fatores de\nrisco intrínsecos para queda.","D":"Monitorar e anotar diariamente os níveis de pressão arterial na intenção de minimizar a\npredisposição para hipotensão."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-217701","number":"217701","sourceNumber":"217701","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente, 24 anos, com lombalgia aguda de início súbito após esforço muscular\n(levantamento de uma caixa pesada). Nega dor\nirradiada ou sinais de alerta (red flags). Ao exame,\napresenta dor miofascial paravertebral e diminuição do arco de movimento. Exame neurológico\nnormal. Além de medidas analgésicas, qual a conduta?","options":{"A":"Ressonância magnética.","B":"Tomografia computadorizada.","C":"Radiografias.","D":"Apenas repouso e orientações."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183171","number":"183171","sourceNumber":"183171","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 20 anos, relata que, nos últimos 3 anos, vem apresentando\nquadros caracterizados por: zumbido, tinnitus,\nvertigem e hipoacusia, e alguns minutos após,\ndificuldade para articular a palavra e formigamento do pescoço para baixo, queixas que duram 60\nmin. Esse quadro é seguido por dor pulsátil em região occipital bilateral que se inicia de fraca\nintensidade e evolui para forte intensidade com fonofobia/fotofobia e náusea. A dor dura 3 dias e\ntal\nepisódio tem se repetido 4 a 5x mês. Qual é a sua hipótese diagnóstica?","options":{"A":"Migrânea basilar.","B":"Migrânea com aura.","C":"Migrânea sem aura.","D":"Migrânea hipoestésica familiar.","E":"Hemicrania paroxística."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183169","number":"183169","sourceNumber":"183169","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 7 meses de idade atendido no ambulatório, sexo feminino, não apresenta\nsustento completo da cabeça, não rola e\napresenta irritabilidade diária. Ao exame neurológico,\napresenta PC - 38 cm, fontanela anterior não palpável, hipotonia de tronco, hipertonia da\nmusculatura posterior do tronco, mãos fechadas. Rigidez dos membros inferiores, que dificulta a\nposição sentada. É correto afirmar:","options":{"A":"Apresenta Atraso do DMP, provável causa genética que não necessita investigação.","B":"O Atraso é discreto e poderá fazer nova avaliação clínica daqui a 2 meses.","C":"É portadora de sinais compatíveis com anormalidade do desenvolvimento, deverá ser\nimediatamente investigada e encaminada à reabilitação em fisioterapia.","D":"Nesse caso, trata-se de paciente portador de Paralisia cerebral, de causa a esclarecer, e a\nreabilitação deverá iniciar após 2 meses e já deverá ser prescrito baclofen.","E":"O quadro clínico é compatível com hipotonia global inespecifica."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-182661","number":"182661","sourceNumber":"182661","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na vigência de uma primeira crise epiléptica febril, a conduta mais adequada?","options":{"A":"Vai depender do tipo de crise.","B":"Não iniciar tratamento com drogas antiepilépticas.","C":"Iniciar tratamento com drogas antiepilépticas em baixas doses.","D":"Aguardar o resultado da avaliação eletroencefalográfica para determinar a conduta."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-182689","number":"182689","sourceNumber":"182689","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Todos abaixo são fatores de risco modificáveis para demência e comprometimento\ncognitivo leve, EXCETO:","options":{"A":"Hipertensão ou diabetes.","B":"Síndrome metabólica ou dislipidemia.","C":"Obesidade e sedentarismo a partir da meia-idade.","D":"Tabagismo e histórico familiar."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183216","number":"183216","sourceNumber":"183216","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação a um achado de hemianopsia homônima diante da avaliação subjetiva do\ncampo de visão, ou seja, o exame do campo\nvisual que justifica o diagnóstico de lesão,\ncaracteriza-se como:","options":{"A":"Quiasma óptico.","B":"Radiações ópticas.","C":"Nervo oculomotor.","D":"Nervo zigomático facial.","E":"Segundo nervo craniano."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-159053","number":"159053","sourceNumber":"159053","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino de 40 anos, pedreiro, vem à consulta com queixa de dor lombar\niniciada há cinco dias, contínua, \"em pontada\", que piora no trabalho. Nega história de trauma ou\nexistência de outros sintomas. No exame, observa-se espasmo da musculatura paravertebral\nlombar; exame neurológico normal. A conduta mais adequada nesse caso é:","options":{"A":"Solicitar exame da proteína C reativa e radiografia simples da coluna lombar, associados à\nprescrição de analgésicos.","B":"Recomendar repouso no leito e compressas quentes, associados à prescrição de analgésicos.","C":"Prescrever associação de anti-inflamatórios e relaxantes musculares e encaminhar para um\nortopedista.","D":"Recomendar retorno gradual às atividades normais e prescrever analgésicos."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-108822","number":"108822","sourceNumber":"108822","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre as etiologias das DEMÊNCIAS, pode-se afirmar que:","options":{"A":"Pode definir a possibilidade de tratamento, e em alguns casos, a reversão dos sintomas.","B":"Não é importante, já que os processos demenciais são inexoráveis e progressivos.","C":"Geralmente a etiologia pode ser definida com anamnese e exame físico cuidadoso.","D":"Só pode ser realizada por neurologista especializado em demências."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-84487","number":"84487","sourceNumber":"84487","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação à estenose de artéria carótida, quando temos contraindicação absoluta do\ntratamento cirúrgico:","options":{"A":"Estenose de 65%, paciente sintomático.","B":"Estenose de 75%, paciente sintomático.","C":"Estenose de 85%, paciente sintomático.","D":"Estenose de 95%, paciente sintomático.","E":"Estenose de 100%, paciente assintomático."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-66948","number":"66948","sourceNumber":"66948","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente com abertura dos olhos à dor, confuso e localiza a dor. Na escala de coma de\nGlasgow tem:","options":{"A":"3 pontos.","B":"6 pontos.","C":"11 pontos.","D":"13 pontos."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-66974","number":"66974","sourceNumber":"66974","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre propedêutica neurológica armada (exames imagem), correlacione as colunas\ncom as características de cada exame: 1.\nTomografia computadorizada; 2. Angiografia\nconvencional; 3. Ressonância magnética; 4. Tomografia por Emissão de Pósitrons (PET). A.\nMelhor modalidade para avaliação por imagem de aneurismas. B. Não invasiva, sem radiação,\nmultiplanar, sensível e agente de contraste seguro. C. Rápida, melhor teste para hemorragia aguda\ne excelente para ossos. D. Útil no diagnóstico de doença de Alzheimer e epilepsia.","options":{"A":"1.A; 2.B; 3.C; 4.D.","B":"1.C; 2.A; 3.B; 4.D.","C":"1.B; 2.C; 3.A; 4.D.","D":"1.D; 2.A; 3.B; 4.C."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-372080","number":"372080","sourceNumber":"372080","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A degeneração neuronal da Atrofia Muscular Espinhal 5q tipos 1 e 2, evolui e:","options":{"A":"Resulta em fraqueza, hiporreflexia e atrofia simétrica progressiva com predomínio dos músculos\nvoluntários proximais de membros inferiores, superiores, e, durante a progressão da doença, pode\nafetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar falha respiratória\ne\nmorte.","B":"Resulta em fraqueza, hiporreflexia e atrofia assimétrica progressiva com predomínio dos\nmúsculos voluntários proximais de membros\nsuperiores apenas, durante a progressão da doença,\npode afetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar falha\nrespiratória e morte.","C":"Não resulta em fraqueza, e sim hiperreflexia sem atrofia simétrica progressiva com predomínio\ndos músculos voluntários proximais de membros\ninferiores, superiores, e, durante a progressão da\ndoença, pode afetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar\nfalha respiratória e morte.","D":"Resulta em fraqueza, hiporreflexia e atrofia simétrica progressiva com predomínio dos músculos\nvoluntários proximais de membros inferiores, superiores, e, durante a progressão da doença, pode\nafetar os músculos axiais, da respiração e bulbares que, por sua vez, pode gerar falha respiratória,\nmas não a morte."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-341035","number":"341035","sourceNumber":"341035","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Diante do caso clínico, com relação ao diagnóstico mais provável, pode-se\nafirmar:","options":{"A":"Durante ou após uma crise, pode ocorrer morte súbita inesperada decorrente de apneia ou\narritmia.","B":"As crises sempre ocorrem após um fator desencadeante, como a estimulação luminosa\nintermitente.","C":"Apesar de haver interferência na qualidade de vida a mortalidade é equiparável à da população\ngeral.","D":"As crises geralmente deixam sequelas neurológicas, levando a déficit cognitivo."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-341036","number":"341036","sourceNumber":"341036","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Com base no quadro descrito, indique o exame complementar mais\nadequado neste momento:","options":{"A":"Ressonância nuclear magnética de crânio.","B":"Eletroencefalograma.","C":"Angiotomografia computadorizada de crânio.","D":"Exame de líquor."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-341037","number":"341037","sourceNumber":"341037","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 20 anos de idade, dá entrada na Unidade de Pronto Atendimento duas horas\napós episódio de crise tônico-clônica\ngeneralizada. Refere ser o segundo episódio, tendo o primeiro\nocorrido há dois meses. Nega comorbidades, trauma, uso de álcool, tabaco ou drogas ilícitas. Faz\nuso apenas de contraceptivo oral. Ao exame, apresenta-se em bom estado geral, sinais vitais\nestáveis. Exame segmentar e neurológico sem achados. Realizada tomografia computadorizada de\ncrânio sem alterações. Indique a melhor conduta terapêutica a ser realizada, neste momento, na\npaciente:","options":{"A":"Aguardar a realização do exame complementar para prescrição de fármaco.","B":"Expectante, sendo prescindível o início de medicação anticonvulsivante.","C":"Prescrever diazepam 10mg, via intravenosa, como primeira escolha medicamentosa.","D":"Iniciar anticonvulsivante, considerando o uso do contraceptivo oral na escolha do fármaco."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-341085","number":"341085","sourceNumber":"341085","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O Brasil envelhece de forma rápida e intensa. Segundo o Censo IBGE de 2010, a\npopulação idosa brasileira é composta por 23\nmilhões de pessoas, totalizando 11,8% da população\ntotal do País. A expectativa de vida para a população brasileira aumentou para 74 anos, sendo 77,7\nanos para a mulher e 70,6 anos para o homem. Considerando os conceitos necessários para a\nformulação das metas das políticas de saúde para a terceira idade, pode-se dizer que:","options":{"A":"A longevidade está diretamente relacionada à qualidade de vida.","B":"Envelhecimento Ativo envolve os mesmos conceitos de Envelhecimento Saudável.","C":"Autonomia do idoso refere-se, principalmente, à capacidade de executar os atos da vida diária.","D":"Autonomia e Independência são conceitos correlatos mas diferentes em Gerontologia."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-315206","number":"315206","sourceNumber":"315206","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um infarto da artéria cerebelar posteroinferior tem como sintomas principais:","options":{"A":"Paralisia hemicorporal.","B":"Monoplegia.","C":"Vertigem e desequilíbrio.","D":"Afasia.","E":"Hipertonia."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-279023","number":"279023","sourceNumber":"279023","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As cefaleias primárias são doenças com episódios recorrentes de dor de cabeça, sendo\ncorreto que","options":{"A":"Migrânea (enxaqueca) caracteriza-se por crises não recorrentes constituídas por até cinco fases\n(nem sempre estão presentes todas elas).","B":"Migrânea (enxaqueca) caracteriza-se por crises recorrentes constituídas por até dez fases (nem\nsempre estão presentes todas elas).","C":"Migrânea (enxaqueca) caracteriza-se por crises recorrentes constituídas por até cinco fases\n(sempre estão presentes todas elas).","D":"Migrânea (enxaqueca) caracteriza-se por crises recorrentes constituídas por até cinco fases\n(nem sempre estão presentes todas elas)."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-278604","number":"278604","sourceNumber":"278604","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na Cefaleia do tipo tensional episódica, ocorre cefaleia em pressão, holocraniana de\nleve a moderada intensidade, podendo beneficiar-se com atividade física. Aparece geralmente no\nfim do dia, durando de 30 minutos a sete dias. Está correto que","options":{"A":"Não pode haver foto e/ou fonofobia, náuseas e vômitos estão ausentes. O exame neurológico é\nnormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes.","B":"Pode haver foto e/ou fonofobia, mas náuseas e vômitos estão ausentes. O exame neurológico é\nanormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes.","C":"Pode haver foto e/ou fonofobia, mas náuseas e vômitos estão presentes. O exame neurológico é\nnormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes.","D":"Pode haver foto e/ou fonofobia, mas náuseas e vômitos estão ausentes. O exame neurológico é\nnormal, hipertonia e hiperestesia da musculatura pericraniana podem estar presentes."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-279025","number":"279025","sourceNumber":"279025","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"São considerados sinais de alerta para cefaleias secundárias os listados corretamente\nno item.","options":{"A":"Presença de déficits neurológicos focais, edema de papila, convulsão.","B":"O (Older) Cefaleia que iniciou após os 20 anos.","C":"O (Onset) Cefaleia de início súbito, nunca a primeira cefaleia.","D":"P (Pattern) Manutenção de padrão da cefaleia prévia ou cefaleia progressiva (intensidade,\nfrequência ou duração) ou cefaleia refratária."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-278606","number":"278606","sourceNumber":"278606","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A fraqueza da Esclerose Lateral Amiotrófica leva a uma respiração cada vez mais\nsuperficial e rápida com sintomas crônicos\nde hipoventilação alveolar. Os sinais de hipoventilação\nocorrem durante o sono REM e, em uma fase mais avançada da doença, manifestam-se no período\ndiurno. Sendo CORRETO que:","options":{"A":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse, mas não limpeza de vias aéreas, alterando a resistência das vias\naéreas e aumentando o risco de desenvolvimento de atelectasias e pneumonia.","B":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse e limpeza de vias aéreas, alterando a resistência das vias aéreas e\nredução do risco de desenvolvimento de atelectasias e pneumonia.","C":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse e limpeza de\nvias aéreas, não alterando a resistência das vias aéreas e\nreduzindo o risco de desenvolvimento de atelectasias e pneumonia.","D":"A fraqueza da musculatura expiratória combinada com inadequadas insuflações dos pulmões\nimpede a eficácia da tosse e limpeza de vias aéreas, alterando a resistência das vias aéreas e\naumentando o risco de desenvolvimento de atelectasias e pneumonia."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-279029","number":"279029","sourceNumber":"279029","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Nos casos de cefaleia do tipo tensional episódica , o Médico da unidade de urgência\norienta paciente e familiares quanto à baixa\ngravidade do quadro e de não haver necessidade de\nencaminhá-lo a um especialista ou realização de exames complementares. Sendo adequado o\nitem.","options":{"A":"Orientação de medidas educativas como: sono regular, evitar bebidas alcoólicas, controle de\nestresse (técnicas de relaxamento, atividade física leve), lazer.","B":"Orientação de medidas educativas como: sono irregular, evitar bebidas alcoólicas, controle de\nestresse (técnicas de relaxamento, atividade física leve) não ao lazer.","C":"Orientação de medidas educativas como: sono regular, evitar bebidas alcoólicas, controle de\nestresse sem uso de técnicas de relaxamento, atividade física leve.","D":"Nunca orientação de medidas educativas como: sono regular, evitar bebidas alcoólicas, controle\nde estresse (técnicas de relaxamento, atividade\nfísica leve), lazer."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-275974","number":"275974","sourceNumber":"275974","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A doença de Parkinson se caracteriza por se tratar de distúrbio neurológico\nestigmatizado predominantemente pela presença de tremor\ninvoluntário de difícil controle. Que\nparte do cérebro e qual o neurotransmissor envolvido na patologia?","options":{"A":"Hipocampo e noradrenalina.","B":"Amigdala e serotonina.","C":"Substância negra e dopamina.","D":"Córtex cerebral e acetilcolina.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-278620","number":"278620","sourceNumber":"278620","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação ao uso de probióticos em pacientes com autismo, assinale a alternativa\nincorreta.","options":{"A":"As crianças com transtorno do espectro autista têm quatro vezes mais chances de apresentar\nsintomas gastrointestinais do que as crianças sem autismo.","B":"Já existem cepas indicadas para tratamento de pacientes com transtorno do espectro autista.","C":"Há evidências que sugerem que as alterações na microflora intestinal estão correlacionadas\ncoma gravidade dos sintomas gastrointestinais e\nautismo.","D":"Há evidencias promissoras para sugerir que a terapia probiótica pode melhorar a disfunção\ngastrointestinal, alterar beneficamente a microbiota fecal e reduzir a gravidade dos sintomas em\ncrianças com transtorno do espectro autista."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-280417","number":"280417","sourceNumber":"280417","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa incorreta em relação aos sinais e sintomas que sugerem o\ndiagnóstico de Síndrome de Guillain Barré.","options":{"A":"Sintomas sensoriais leves, especialmente dor em crianças menores.","B":"Disfunção autonômica, em qualquer modalidade.","C":"Assimetria marcante.","D":"Envolvimento de nervos cranianos."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-278100","number":"278100","sourceNumber":"278100","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa correta em relação ao uso de escalas para manejo da dor em\npediatria.","options":{"A":"Ainda não há, na literatura, um consenso quanto ao uso rotineiro de escalas para avaliação da\ndor nas UTIs pediátricas.","B":"É possível utilizar com crianças as mesmas escalas intuídas para adultos, pois todas são\nvalidadas para todas as faixas etárias.","C":"O autorrelato e as escalas numéricas e de faces são muito úteis para manejo e avaliação da dor.","D":"As escalas de faces são consideradas padrão ouro para a avaliação da dor, uma vez que são\nmuito uteis e de fácil entendimento na faixa etária pediátrica."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-278633","number":"278633","sourceNumber":"278633","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As anormalidades na substância branca subcortical, o envolvimento do tálamo, dos\ngânglios da base e do tronco cerebral encontrada na RNM são características de qual forma de\nencefalite?","options":{"A":"ADEM.","B":"Herpes vírus.","C":"Enterovírus.","D":"Anti-NMDA."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-280431","number":"280431","sourceNumber":"280431","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na semiologia da Síndrome do Desfiladeiro Torácico pede-se para paciente inspirar\nmaximamente e manter sua respiração enquanto o pescoço é estendido e a cabeça é girada para o\nlado afetado. Esta manobra estreita o espaço entre os músculos escalenos anterior e médio,\nresultando em compressão da artéria subclávia e do plexo braquial. Diminuição ou perda do pulso\nradial ipsilateral sugere compressão. Trata-se do teste de:","options":{"A":"Teste de Adson.","B":"Teste de Allen.","C":"Teste de Halsted.","D":"Teste de Roos."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252882","number":"252882","sourceNumber":"252882","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 32 anos de idade, procura atendimento na UPA por quadro de cefaleia intensa\nem pontada, unilateral, em região\nperiorbitária a esquerda, há 30 minutos, associada a fotofobia e\nnáuseas. Nega comorbidades. Ao exame, paciente bastante ansioso, com fácies de dor. Nota-se\nlacrimejamento e hiperemia conjuntival em olho esquerdo. De acordo com o quadro descrito,\nindique o diagnóstico mais provável.","options":{"A":"Migrânea com aura.","B":"Neuralgia do trigêmeo.","C":"Cefaleia em salvas.","D":"Cefaleia em trovoada."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252883","number":"252883","sourceNumber":"252883","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 32 anos de idade, procura atendimento na UPA por quadro de cefaleia intensa\nem pontada, unilateral, em região\nperiorbitária a esquerda, há 30 minutos, associada a fotofobia e\nnáuseas. Nega comorbidades. Ao exame, paciente bastante ansioso, com fácies de dor. Nota-se\nlacrimejamento e hiperemia conjuntival em olho esquerdo. Considerando o caso, indique a conduta\nterapêutica mais efetiva nesse momento.","options":{"A":"Oxigenoterapia sob máscara.","B":"Dexametasona intravenosa.","C":"Tramadol intravenoso.","D":"Naproxeno via oral."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252884","number":"252884","sourceNumber":"252884","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 32 anos de idade, procura atendimento na UPA por quadro de cefaleia intensa\nem pontada, unilateral, em região\nperiorbitária a esquerda, há 30 minutos, associada a fotofobia e\nnáuseas. Nega comorbidades. Ao exame, paciente bastante ansioso, com fácies de dor. Nota-se\nlacrimejamento e hiperemia conjuntival em olho esquerdo. Cite o fármaco mais adequado para\nprofilaxia de novos quadros semelhantes.","options":{"A":"Propranolol.","B":"Verapamil.","C":"Indometacina.","D":"Amitriptilina."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-249410","number":"249410","sourceNumber":"249410","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A endarterectomia de carótida é uma cirurgia consagrada no tratamento da isquemia\ncerebral de origem extracraniana. Sobre suas complicações, é correto afirmar:","options":{"A":"A lesão intra-operatória do nervo vago causa alteração motora de metade da língua.","B":"A lesão do nervo hipoglosso pode levar a regurgitações alimentares, com broncoaspiração e\npneumonia de repetição.","C":"O ramo mandibular do nervo facial quando lesado leva a dificuldade em emitir notas de timbre\nagudo e resulta em fatigabilidade da voz.","D":"A microembolização cerebral pode levar a acidente vascular encefálico isquêmico."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-249419","number":"249419","sourceNumber":"249419","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre isquemia cerebral de origem extracraniana, marque a correta:","options":{"A":"A arterite de Takayasu pode levar a isquemia cerebral extracraniana, sendo mais comum em\nhomens a partir da sexta década de vida.","B":"A aterosclerose não é causa comum de ataque isquêmico transitório e de acidente vascular\ncerebral.","C":"Na displasia fibromuscular a cirurgia de endarterectomia de carótidas é sempre o melhor\ntratamento.","D":"A displasia fibromuscular ocorre mais frequentemente em pacientes do sexo feminino."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252945","number":"252945","sourceNumber":"252945","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No momento atual da evolução da ciência médica regenerativa há a possibilidade de\nutilizar de doador vivo, tecidos, córneas, medula óssea, um dos órgãos duplos (ex.: rim) e parte do\nfígado e do pulmão. De pessoa morta ou com diagnóstico de morte encefálica (ME), pulmões,\ncoração, fígado, pâncreas, intestino, rins, córnea, pele, veias, válvulas cardíacas, ossos e\ntendões.\nO Conselho Federal de Medicina é o único órgão que possui atribuições para a rigorosa\ndeterminação científica da morte encefálica (Resolução CFM n. 2.173/2017). POLICASTRO, Decio.\nSobre doações e transplantes de órgãos. Publicado online em http://www.abto.org.br, em\n18/06/2018. Acesso em: dez 2019. Pela legislação brasileira, ficam impedidos de doar órgãos em\nvida","options":{"A":"indivíduos com mais de 50 anos de idade.","B":"incapazes, mesmo com consentimento do tutor legal.","C":"indivíduos sem parentesco biológico com os receptores.","D":"estrangeiros não naturalizados no país."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-249267","number":"249267","sourceNumber":"249267","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Algumas vacinas de vírus vivos atenuados ou mortos podem anteceder a síndrome de\nGuillain-Barré (SGB), que se manifesta clinicamente como polirradiculoneurite inflamatória com\nlesão de desmielinização, parestesias e deficit motor ascendente de intensidade variável. Somente\nmostra erro:","options":{"A":"Geralmente, os sintomas aparecem entre 7 e 21 dias, no máximo até 42 dias (6 semanas) após\na exposição ao possível agente desencadeante.","B":"Até o momento, há poucas evidências se a vacina influenza pode aumentar o risco de\nrecorrência da SGB em indivíduos com história pregressa desta patologia.","C":"Recomenda-se precaução na vacinação dos indivíduos com história pregressa da SGB, mesmo\nsabendo ser bastante rara.","D":"Reações anafiláticas graves relacionadas a doses anteriores, mas não contraindicam doses\nsubsequentes."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-215498","number":"215498","sourceNumber":"215498","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Dos exames citados a seguir, qual é o que NÃO está incluído no protocolo de morte\nencefálica?","options":{"A":"Reflexo córneo palpebral.","B":"Teste da apneia.","C":"Reflexo de tosse.","D":"Reflexo de preensão palmar e plantar."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-212167","number":"212167","sourceNumber":"212167","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente A.B.S., 75 anos, sexo feminino, foi à consulta médica acompanhada da filha\nprimogênita, que relata que a mãe iniciou quadro de esquecimento há 2 anos, principalmente para\nacontecimentos recentes. O quadro foi piorando de forma progressiva e, no momento, apresenta\nincapacidade de executar as atividades diárias, realizadas previamente. Após avaliação clínica, o\nmédico suspeitou de um quadro de demência. Dadas as afirmativas em relação ao diagnóstico\ndiferencial das demências: I. A hidrocefalia comunicante normobárica é uma causa de demência\nnão tratável. II. A principal hipótese diagnóstica para o quadro clínico descrito acima é a doença\nde\nPick. III. A doença de Alzheimer é a causa mais comum de demência e ocorre em mais de 50% dos\ncasos. IV. Deve ser solicitado inicialmente TSH, T4L, VDRL, dosagem sérica de vitamina B12 e TC\nde crânio, para exclusão de causas tratáveis. Verifica-se que está(ão) CORRETA(S):","options":{"A":"III, apenas.","B":"I e II, apenas.","C":"III e IV, apenas.","D":"I, II e IV, apenas.","E":"I, II, III e IV."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-219868","number":"219868","sourceNumber":"219868","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de 3 anos foi levada a consulta com história de cefaleia iniciada há 20 dias,\nholocraniana, de forte intensidade, incapacitante ( 'para de brincar e não quer se mexer'). Mãe\nrelata que criança apresenta cefaleia diária, mais matutina e já despertou durante o sono com\nqueixa de dor, Refere melhora da cefaleia após vômitos, mas resposta parcial ao uso de dipirona,\nTia paterna tem diagnóstico de enxaqueca. Pais estão em processo de divórcio. Diante desta\nhistória clínica, a conduta CORRETA deve ser:","options":{"A":"Descartar causas orgânicas de cefaleia na infância e solicitar tomografia de encéfalo na\nurgência.","B":"Encaminhar a criança para acompanhamento psicológico e agendar retorno em um mês.","C":"Prescrever uso de analgésicos mais potentes nas crises de dor e retornar em um mês com\nagenda de dor.","D":"Tranquilizar a criança e a família sobre a benignidade do quadro e realizar alta médica"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-201765","number":"201765","sourceNumber":"201765","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 78 anos chega à emergência com paralisia em dimídio esquerdo e disfasia.\nEncontra-se lúcido, PA = 240 x 135 mmHg; FC = 98 bpm e SatO2 = 96%. Qual a conduta mais\napropriada para o controle da pressão arterial?","options":{"A":"Metropolol em bolus e nitroprussiato de sódio em bomba de infusão, mantendo PA em 170 x 110\nmmHg.","B":"Captopril SL e Furosemida EV para queda imediata da PA.","C":"Reduzir imediatamente a PA para níveis abaixo de 140 x 90 mmHg com a medicação que\nestiver ao alcance.","D":"Nitroprussiato de sódio em bomba de infusão para manter a PA < ou = a 120 x 80 mmHg.","E":"Fazer medicação oral, observando o que já toma em casa e aguardar o resultado da tomografia."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-219883","number":"219883","sourceNumber":"219883","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em plantão no pronto atendimento você avalia pré-escolar do sexo feminino, de 2 anos\nde idade, previamente hígida, com dor em\nregião lombar esquerda há 3 semanas, fraqueza em\nmembros inferiores e dificuldade para iniciar micção há 4 dias. Nega pródromos virais ou outros\nsintomas associados. Ao exame, observa-se perda do reflexo patelar e hipoestesia à esquerda.\n\nCom bases nestes achados, hipótese diagnóstica MAIS PROVAVÉL e a conduta inicial MAIS\nADEQUADA são:","options":{"A":"Compreensão medular espinhal, solicitar ressonância magnética de coluna.","B":"Litíase renal, solicitar exame de urina e ultrassonografia de rins e vias urinárias","C":"Mielite transversa; realizar punção liquórica.","D":"Síndrome de Guillain-Barret; realizar punção liquórica."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-215219","number":"215219","sourceNumber":"215219","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação às medidas que podem ser utilizadas\npara o tratamento da hipertensão intracraniana.","options":{"A":"Na emergência, a administração de solução salina hipertônica a 3% é feita em bolo de 6 a 10\nml/kg.","B":"A hipotermia moderada (32 a 33 graus celsius) tem seu uso ainda controverso para a população\ninfantil; no entanto, pode ser considerada\nnas primeiras 8 horas e mantida por até 48 horas\nposteriormente ao trauma.","C":"O manitol apresenta evidência que indica seu uso em crianças, com dose variável de 1 a 3 g/kg.","D":"A monitorização da Pressão Intracraniana (PIC) está indicada em crianças com traumatismo\ncranioencefálico grave."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-216230","number":"216230","sourceNumber":"216230","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Estão presentes na síndrome de Cushing da hipertensão intracraniana.","options":{"A":"Taquidispneia e hipotensão arterial.","B":"Taquicardia e hipertensão arterial.","C":"Bradicardia e hipertensão arterial.","D":"Bradipneia e hipotensão arterial."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-219856","number":"219856","sourceNumber":"219856","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Com relação à síndrome de Guillain-Barré é INCORRETO afirmar:","options":{"A":"A fraqueza muscular geralmente se inicia nos membros inferiores, mas em uma minoria dos\ncasos pode se iniciar nos membros superiores ou\nmúsculos faciais","B":"Parestesias nas mãos e pés frequentemente acompanham a fraqueza muscular, mas alterações\nsensitivas ao exame são comumente discretas","C":"Nos membros acometidos, observa-se inicialmente hiperatividade dos reflexos tendinosos\nprofundos que evolui para hiporreflexia ou arreflexia com a progressão da doença","D":"Síndrome de secreção inapropriada de hormônio anti-diurético, que pode ser devida a\nacometimento autonômico, é complicação possível da síndrome de Guillain-Barré"},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-212179","number":"212179","sourceNumber":"212179","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Flávia, 1 ano e 5 meses, começou a apresentar febre (38,5 ºC) há 12 horas, bem como\ncoriza hialina e tosse seca. Sua genitora refere que, apesar da administração do antitérmico,\nrapidamente houve ascensão de sua temperatura, evoluindo com crise convulsiva (primeiro\nepisódio), com duração de cerca de 5 minutos. Procurou imediatamente atendimento em serviço de\nemergência, porém já sem sinais de crise e sem comprometimento neurológico pós-ictal na\nadmissão. Qual a melhor medida a ser tomada neste momento?","options":{"A":"Realizar eletroencefalograma para confirmar o diagnóstico e instituir terapêutica\nanticonvulsivante.","B":"Iniciar uso de anticonvulsivante profilático, pela alta probabilidade de recorrência do quadro.","C":"Realizar obrigatoriamente tomografia computadorizada de crânio para confirmar diagnóstico e\ninstituir terapêutica anticonvulsivante.","D":"Coletar imediatamente líquido cefalorraquidiano,\n\nindependentemente da ocorrência de outros sintomas de comprometimento do Sistema Nervoso\nCentral.","E":"Realizar anamnese detalhada, bem como exame físico minucioso. Afastar intoxicações\nexógenas, trauma, focos infecciosos, avaliar as\ncaracterísticas da crise e a história familiar."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183628","number":"183628","sourceNumber":"183628","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No tocante aos inibidores da monoaminoxidase (IMAO), as interações medicamentosas\ne alimentares determinadas por este grupo de\ndrogas desaconselham seu uso em profilaxia de\nmigrânea, estando INCORRETO que:","options":{"A":"Os antidepressivos tricíclicos não têm eficácia comprovada por vários estudos em profilaxia de\nmigrânea.","B":"Admite-se antidepressivos tricíclicos que ajam por inibir a receptação da serotonina.","C":"Admite-se antidepressivos tricíclicos que ajam por inibir a receptação da noradrenalina.","D":"Os antidepressivos tricíclicos têm sua ação antimigranosa independe da ação antidepressiva."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183643","number":"183643","sourceNumber":"183643","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O tratamento profilático da migrânea menstrual, não deve apenas considerar como\nCORRETO o seguinte:","options":{"A":"Antes de iniciar o tratamento é fundamental estabelecer os períodos em que as crises ocorrem\ncom maior frequência através do preenchimento\nde um diário de dor pelo paciente.","B":"O tratamento profilático da migrânea menstrual deve ter caráter temporário, iniciando-se em\nintervalo de 1 a 14 dias antes do dia em que, usualmente, a cefaleia se inicia, sempre obedecendo\nao padrão estabelecido pelo diário.","C":"Se na terapia com anti-inflamatório não-esteroides (AINEs), derivados da ergotamina ou\ntriptanos controlam adequadamente a migrânea\nmenstrual, deve ser considerada a possibilidade de\nterapia hormonal.","D":"Essa terapia pode ser realizada através da utilização do estrógeno em combinação com a\nprogesterona."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-181409","number":"181409","sourceNumber":"181409","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Dadas as afirmativas quanto aos sintomas musculares relacionados às estatinas\n(SMRE): I. Fluoxetina está relacionada à\nocorrência da SMRE; II. Consumo de cocaína, etilismo,\ndisfunção renal, baixo IMC ehipotireoidismo constituem fatores de risco para SMRE; III. Durante a\nterapia com estatinas, elevações transitórias de creatinoquinase podem ocorrer, mesmo em\npacientes assintomáticos, mas sem significado clínico; IV. Caracteriza-se com dor e fraqueza\nsimétrica e distal que afeta pequenos grupos musculares. Habitualmente, ocorre de 4 a 12\nsemanas após início do uso das estatinas. Verifica-se que está(ão) correta(s) apenas:","options":{"A":"II.","B":"I e III.","C":"I e IV.","D":"I, II e III.","E":"II, III e IV."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-181424","number":"181424","sourceNumber":"181424","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O perfil demográfico modificou-se nas últimas décadas, principalmente em decorrência\ndo aumento da longevidade e da redução das taxas\nde mortalidade. Segundo o último censo\ndemográfico do IBGE, a quantidade de pessoas com idade acima de 60 anos no Brasil é de mais\nde 20 milhões (10,8% da população). Assinale a alternativa CORRETA sobre o idoso:","options":{"A":"A pele do idoso tem mais elasticidade e menos flexibilidade.","B":"Há aumento da sensibilidade respiratória à hipóxia e hipercapnia.","C":"Há aumento da complacência da parede torácica e redução da complacência pulmonar.","D":"Testes de função hepática normais significam\nnecessariamente metabolismo normal das drogas.","E":"O clearance de creatinina diminui com a idade. A creatinina não aumenta, uma vez que o\nmetabolismo muscular também está reduzido."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-182756","number":"182756","sourceNumber":"182756","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os sítios primários mais comuns dos tumores cerebrais metastáticos são, EXCETO","options":{"A":"câncer de pulmão.","B":"câncer de pâncreas.","C":"câncer de mama.","D":"melanoma."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183117","number":"183117","sourceNumber":"183117","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Qual é a situação em que o corticoesteroide tem efeito benéfico para o tratamento da\nhipertensão intracraniana?","options":{"A":"Hematoma Subdural.","B":"Hemorragia intraparenquimatosa.","C":"Hemorragia Subaracnoidea.","D":"Meningioma."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-181396","number":"181396","sourceNumber":"181396","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 72 anos comparece à consulta com perda de memória progressiva e\ndificuldade para encontrar as palavras, há cerca de um ano de evolução. Qual é a exploração mais\nútil para\n\ncaracterizar o tipo de déficit cognitivo que apresenta?","options":{"A":"Ressonância nuclear magnética cerebral.","B":"Tomografia computadorizada do crânio.","C":"Avaliação neuropsicológica.","D":"Eletroencefalograma.","E":"Biópsia cerebral."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-187852","number":"187852","sourceNumber":"187852","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Leia o texto a seguir e assinale a alternativa CORRETA, identificando o diagnóstico da\ndoença retratada. \"O sinal inicial\ncaracterístico desta doença consiste em fraqueza muscular, que\nocorre em aproximadamente 60% dos pacientes. O aparecimento e a natureza dos sinais e\nsintomas é muito variável, mas como se trata de doença dos neurônios motores superior e inferior,\no tato, a audição, o paladar, o olfato e a visão não são comprometidos. Embora a terapia consiga\nalentecer a evolução da doença em alguns casos, à medida que a doença evolui, a fraqueza\nmuscular e a paralisia se propagam para os músculos do tronco, da fala, da deglutição, da\nmastigação e da respiração. Os pacientes acabam precisando de suporte ventilatório para\nsobreviverem.\"","options":{"A":"Acidente vascular encefálico","B":"Doença de Parkinson","C":"Doença de Wilson","D":"Esclerose lateral amiotrófica"},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-187857","number":"187857","sourceNumber":"187857","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente com 60 anos, sexo feminino, apresenta dor na cabeça com localização\nholocraniana, de forte intensidade, que se inicia\napós início do sono. A paciente refere que a dor\nmelhora ou desaparece quando ela desperta. Assinale a alternativa CORRETA quanto ao\ndiagnóstico MAIS PROVÁVEL desse caso:","options":{"A":"Cefaleia tensional.","B":"Cefaleia em salvas.","C":"Cefaleia hípnica.","D":"Enxaqueca."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-181431","number":"181431","sourceNumber":"181431","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As crises epilépticas constituem um dos problemas neurológicos mais comuns da\ninfância. Em relação à crise febril:","options":{"A":"O diagnóstico é essencialmente clínico e o exame do liquor somente deve ser realizado se for\nobservada alguma alteração no exame neurológico da criança.","B":"Ocorre geralmente nas horas seguintes ao processo infeccioso agudo.","C":"Ocorre geralmente depois dos três anos de idade, associada à febre.","D":"Está sempre associada a temperaturas próximas aos 40°C.","E":"Manifesta-se em crianças com crises afebris prévias."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-161283","number":"161283","sourceNumber":"161283","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente deu entrada na sala de emergência com dificuldade respiratória e rebaixada.\nApresentava perda motora e incoordenação dos movimentos. Apresenta PA de 200 x 110 mmHg. A\nhipótese diagnóstica inicial foi a de AVC. Diante de tal quadro, assinale a alternativa contendo a\nconduta inicial MAIS adequada.","options":{"A":"Iniciar atendimento com ABCDE.","B":"Caso menor que 4 horas propor trombólise.","C":"Para pacientes com PAS entre 150 e 220 mmHg e sem contraindicação para o tratamento, a\nredução aguda da PAS para 140 mmHg é segura e pode ser eficaz para melhorar o desfecho\nfuncional.","D":"Inicialmente solicitar Tomografia de Crânio antes de qualquer conduta inicial."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-161271","number":"161271","sourceNumber":"161271","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente hipertenso mal controlado, rebelde ao uso de medicação diária que é\nPropranolol, foi trazido ao hospital com intensa cefaleia e perda motora do lado direito do corpo.\nSua pressão era de 210 x 120 mmHg. Foi realizado Tomografia de Crânio que demonstrava\nsangramento. Diante de tal situação, marque a opção INCORRETA.","options":{"A":"Para pacientes com PAS entre 150 e 220 mmHg e sem contraindicação para o tratamento, a\nredução aguda da PAS para 140 mmHg é segura.","B":"Para pacientes com PAS entre 150 e 220 mmHg, a redução aguda da PAS pode ser eficaz para\nmelhorar o desfecho funcional.","C":"Para pacientes com PAS entre 150 e 220 mmHg, a redução aguda da PAS em 1 hora com\ninfusão IV de anti-hipertensivos é benéfica.","D":"Para pacientes com PAS entre 150 e 220 mmHg, a redução da PAS necessita de monitorização\nda PA horária."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-161381","number":"161381","sourceNumber":"161381","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Adulto jovem, masculino, procurou o hospital com intensa cefaleia, descrevendo como\na pior da vida, de forte intensidade,\nacompanhada de desorientação e perdas motoras. Foi\ninicialmente suspeitado de cefaleia secundária, sendo então decidido por realização de tomografia\nde crânio com contraste. Mas essa tomografia não foi inicialmente autorizada para o paciente,\njustificada ADEQUADAMENTE assim:","options":{"A":"Melhor ressonância.","B":"Melhor punção lombar inicial por ser mais sensível.","C":"Necessidade inicial de tomografia comum, sem contraste, pois caso ocorra sangramento,\no potencial extravasamento de contraste piora a\nlesão.","D":"Não é possível o diagnóstico com tomografia."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-158748","number":"158748","sourceNumber":"158748","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"JLS, masculino, 32 anos, foi atendido na Unidade Básica de Saúde com queixa de dor,\nparesetesias e impotência funcional que atingiam primordialmente a face palmar dos 1°, 2°, e 3°\ndedos da região tenar, principalmente do oponente do polegar e da borda radial do 4° dedo. Ao\nexame físico, o teste de Tinnel e a manobra de Phalen são positivos. Pelo relato, qual o diagnóstico\nmais provável para JLS?","options":{"A":"Dedo em gatilho.","B":"Contratura de Dupuytren.","C":"Síndrome do túnel do carpo.","D":"Síndrome do canal de Guyon.","E":"Síndrome do pronador redondo."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-161386","number":"161386","sourceNumber":"161386","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação às especialidades dos médicos que assinam o termo de declaração de\nmorte encefálica, assinale a alternativa INCORRETA:","options":{"A":"Um poderá ser intensivista e o outro neurologista.","B":"Ambos podem ser neurologistas.","C":"Um pode ser intensivista ou neurologista e o outro deve pertencer à equipe de captação de\nórgãos.","D":"Ambos podem ser intensivistas."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-161147","number":"161147","sourceNumber":"161147","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Marque a opção que NÃO é considerada um fator de risco para Acidente Vascular\nEncefálico em pediatria.","options":{"A":"Doenças hematológicas, como anemia falciforme, leucemias ou linfomas.","B":"Anomalias vasculares, como aneurismas e doença de moyamoya.","C":"Doenças cardíacas congênitas ou adquiridas.","D":"Doenças endocrinológicas, como diabetes mellitus tipo 1 e diabetes insípidus."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-161150","number":"161150","sourceNumber":"161150","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Aponte a opção que apresenta o exame diagnóstico padrão ouro na investigação do\nAcidente Vascular Encefálico.","options":{"A":"Angiografia convencional.","B":"Angiografia por ressonância magnética.","C":"Ultrassonografia de crânio.","D":"Tomografia computadorizada de crânio."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134802","number":"134802","sourceNumber":"134802","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente deu entrada com queixa de cefaleia súbita seguida de perda motora e\ndisartria. Foi, então, solicitada Tomografia de\nCrânio que não demonstrou achados de imagem. A\nseguir, foi colhido liquor que também se mostrou inespecífico. Nesse caso, podemos afirmar que","options":{"A":"A Tomografia mostrava-se essencial para afastar sangramentos.","B":"O liquor mostrou-se mal indicado, pois se não ocorrem achados na Tomografia o mesmo\nmostra-se desnecessário.","C":"A abordagem inicial deveria considerar RNM e não Tomografia.","D":"O liquor é mais sensível que a Tomografia para diversos diagnósticos."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134094","number":"134094","sourceNumber":"134094","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Quando abordamos emergências hipertensivas relacionadas ao sistema nervoso\ncentral, podemos afirmar que apresentam correlação\nde lesão de órgão alvo e hipertensão os\nseguintes quadros clínicos, EXCETO o contido em uma das alternativas. Aponte-a.","options":{"A":"Edema de papila de nervo óptico.","B":"Edema cerebral visível na tomografia.","C":"Cluster.","D":"Sangramento cerebral."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134856","number":"134856","sourceNumber":"134856","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Quando abordamos quadro de hipertensão intracraniana, utilizamos, a fim de controlar\na mesma, algumas condutas, entre elas as\nlistadas abaixo, EXCETO:","options":{"A":"Cabeceira a 30°.","B":"Controle da PCO2, indicado capnografia.","C":"Uso de pressão arterial média.","D":"Controle da PO2 a fim de provocar hiperóxia."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134103","number":"134103","sourceNumber":"134103","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Idoso, 68 anos de idade, deu entrada no hospital com rebaixamento do nível de\nconsciência, Glasgow de 11, perda motora no lado esquerdo de início súbito. Sua tomografia de\ncrânio mostra-se dentro da normalidade para a idade. Podemos, assim, considerar que sua\npressão de 190 x 110 mmHg deve nortear a seguinte conduta. Assinale-a:","options":{"A":"Deve ser abaixada toda vez que ultrapassar 180 x 110 mmHg.","B":"Deve ser tolerada até 210 x 120 mmHg.","C":"Depende se a proposta de tratamento é de trombólise ou não.","D":"Independentemente do que ocorrer, irá normalizar em três dias."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134833","number":"134833","sourceNumber":"134833","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente hipertenso crônico, com elevação dos valores de ureia e creatinina fora\ndiabetes mal controlado, evolui com\nrebaixamento do nível de consciência e dificuldade\nrespiratória. Sua pressão arterial está extremamente elevada com PA 230 x 130 mmHg.\nSeus exames demonstram glicemia de 120, valores de ureia e creatinina ainda não indicam\nhemodiálise. Tomografia demonstra intenso edema cerebral. Qual das alternativas abaixo MELHOR\nexplica o caso?","options":{"A":"Provável distúrbio metabólico com acidose lática.","B":"Vasodilatação por pressão, hiperemia cerebral e encefalopatia.","C":"Hemorragia cerebral.","D":"Provável AVC isquêmico."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-140180","number":"140180","sourceNumber":"140180","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 79 anos de idade, sem comorbidades prévias conhecidas, iniciou\nsubitamente com hemiplegia direita. É trazido\nà emergência por familiares em 30 minutos do início\ndo quadro neurológico. O paciente encontra-se consciente, a pressão arterial é de 175 x 100\nmmHg, apresenta hemiplegia direita e afasia de expressão. É realizada uma tomografia de crânio\nsem contraste que não mostra alterações. Assinale a alternativa que apresenta a conduta\nterapêutica MAIS ADEQUADA:","options":{"A":"Monitorização invasiva da pressão arterial e início de anti-hipertensivo endovenoso.","B":"Controle rigoroso da pressão arterial com medicação endovenosa e heparinização plena.","C":"Repouso e monitorização neurológica intensiva apenas.","D":"Início imediato de anti-hipertensivo e do AAS após 48 horas."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134123","number":"134123","sourceNumber":"134123","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente com midríase unilateral, fotorreatividade pupilar com reação cruzada (Sinal de\nMarcus Gunn) apresenta lesão do nervo:","options":{"A":"Facial.","B":"Auricular.","C":"Oculomotor.","D":"Óptico."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-131335","number":"131335","sourceNumber":"131335","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O acidente vascular cerebral que cursa com rigidez de nuca é:","options":{"A":"Isquêmico.","B":"Hemorrágico.","C":"De tronco cerebral.","D":"Intracavitário.","E":"NDA."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-109725","number":"109725","sourceNumber":"109725","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo masculino, 27 anos, refere coriza hialina, tosse produtiva e mialgia de\ninício há três semanas com melhora espontânea após quatro dias. No entanto, após alguns dias,\npassou a apresentar fraqueza em membros inferiores, com dificuldade para deambular, que\nprogrediu para discreta redução da força muscular em membros superiores. Ao exame físico,\napresenta força muscular grau III em membros inferiores e grau IV em membros superiores.\n\nReflexos osteotendíneos normais, ausência de sinais de liberação piramidal, sensibilidade normal.\nAssinale abaixo a hipótese diagnóstica mais provável e o exame a ser solicitado para sua\nconfirmação, RESPECTIVAMENTE.","options":{"A":"Acidente vascular medular cervical / Ressonância magnética.","B":"Encefalopatia de Wernicke / Dosagem de tiamina.","C":"Síndrome de Guillain-Barré / Coleta de liquor.","D":"Esclerose lateral amiotrófica / Eletroneuromiografia."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-110062","number":"110062","sourceNumber":"110062","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale abaixo a conduta apropriada em paciente com Acidente Vascular Cerebral\nIsquêmico Cerebelar que evolui com hidrocefalia e rebaixamento do nível de consciência.","options":{"A":"Derivação ventricular externa.","B":"Solução salina hipertônica.","C":"Nimodipina endovenosa.","D":"Medidas de suporte clínico."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-110015","number":"110015","sourceNumber":"110015","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As causas etiológicas que podem levar a espasmos infantis incluem:","options":{"A":"Idiopática.","B":"Genética e metabólica.","C":"Malformações cerebrais focais.","D":"Todas as alternativas acima."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-110019","number":"110019","sourceNumber":"110019","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Erupção cutânea é uma preocupação importante em qual das seguintes medicações?","options":{"A":"Topiramato.","B":"Gabapentina.","C":"Lamotrigina.","D":"Oxcarbamazepina."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-110020","number":"110020","sourceNumber":"110020","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Qual das seguintes características clínicas NÃO faz parte do espectro de enxaqueca\nem criança?","options":{"A":"Cefaleia.","B":"Perda visual temporária.","C":"Dor abdominal, cólicas e vômitos.","D":"Alucinações olfatórias."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-110002","number":"110002","sourceNumber":"110002","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Quais os parâmetros avaliados na Avaliação Geriátrica Ampla (AGA)? I. O diagnóstico\nde síndrome demencial é eminentemente clínico,\nbaseado em avaliação objetiva do desempenho\ncognitivo e funcional; II. Entre os diversos testes de rastreio para o diagnóstico de síndrome\ndemencial, a escala de Yesavage é, certamente, a mais empregada; III. O exame do liquor é\nindicado para todos os pacientes com demência. É CORRETO o que se afirma em:","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e II, apenas.","D":"I, II e III."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-86668","number":"86668","sourceNumber":"86668","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A conduta a seguir faz parte do manejo da fase aguda: Cuidados gerais de manter as\nvias aéreas, respiração e condições circulatórias, anticonvulsivantes, nimodipina, repouso absoluto\nno leito, ansiolíticos, controle da glicemia. I ? Acidente vascular isquêmico. II ? Acidente\nvascular\nisquêmico transitório. III ? Hemorragia subaracnoide.","options":{"A":"Apenas afirmativas I, II estão corretas.","B":"Apenas afirmativa I está correta.","C":"Apenas afirmativa II está correta.","D":"Apenas afirmativas I e III estão corretas.","E":"Apenas afirmativa III está correta."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-86877","number":"86877","sourceNumber":"86877","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente 20 anos, mulher, teve exposição à brusca variação de temperatura ambiente,\nverificou que sua comissura labial estava desviada para a direita. Concomitante, notou a\nimpossibilidade de fechar a pálpebra esquerda e hipostesia em hemiface esquerda. Nenhuma\noutra alteração no exame neurológico. Esse diagnóstico de paralisia facial é do tipo:","options":{"A":"Periférica esquerda;","B":"Periférica direita;","C":"Central esquerda;","D":"Central direita;","E":"Complexa."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-86798","number":"86798","sourceNumber":"86798","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Albina é uma senhora de 82 anos hipertensa e diabética, viúva há 5 anos. Vem à\nconsulta trazida por sua filha, que relata que\na mãe vem apresentando há 3 anos quadro\nprogressivo de perda de memória e agressividade com os filhos. Até 1 mês atrás, morava sozinha\nem outra cidade, mas teve que se mudar para a casa da filha após quase ter incendiado a casa ao\ndeixar a panela no fogo e ter ido dormir. Em relação a esse caso clínico, assinale a alternativa\ncorreta.","options":{"A":"O diagnóstico de depressão é improvável, pois geralmente não cursa com perda de memória;","B":"A possibilidade de demência vascular deve\n\nser considerada mesmo na ausência de história de acidente vascular cerebral;","C":"O miniexame do estado mental, o teste do relógio e testes de fluência verbal são úteis para\nrastreamento, mas têm valor limitado na avaliação e no acompanhamento clínico de pacientes\ncom demência;","D":"Benzodiazepínicos devem ser usados para conter a agressividade, de preferência o diazepam;","E":"O diagnóstico de delirium deve ser fortemente considerado devido ao curso progressivo do\nquadro."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-86835","number":"86835","sourceNumber":"86835","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Geralda, paciente já conhecida por você, 45 anos de idade, chega à unidade de saúde,\nsem consulta agendada por apresentar ?crise\nde dor de cabeça?. Ela refere que no último trimestre\napresentou, em média, 4 crises por mês que responderam pobremente ao esquema que você havia\nprescrito anteriormente. Ela esta preocupada por ter ganho peso no ultimo mês e apresenta\nsonolência diurna. Qual das medicações abaixo constitui a melhor escolha para a profilaxia da\nenxaqueca de Geralda?","options":{"A":"Amitriptilina;","B":"Ácido Valproico;","C":"Propanolol;","D":"Flunarizina;","E":"Nortriptilina."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-158416","number":"158416","sourceNumber":"158416","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino, 74 anos, portador de hipertensão arterial, em uso de losartan 50\nmg/dia, relata episódio de tontura ao levantar o tronco após amarrar os sapatos. O sintoma durou\nmenos de 1 minuto. Refere episódios prévios semelhantes. Dê a principal hipótese diagnóstica e\nconduta:","options":{"A":"Hipotensão ortostática ? reduzir anti-hipertensivos.","B":"Vertigem paroxística posicional benigna ? reabilitação vestibular.","C":"Síndrome de Meniere ? gentamicina intratimpânica.","D":"Neurite Vestibular ? betaistina.","E":"Neurinoma do acústico ? ressecção tumoral."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-158427","number":"158427","sourceNumber":"158427","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente do sexo feminino, com 8 anos de idade, apresenta história clínica de\nperda progressiva de força muscular simétrica e arreflexia; a avaliação complementar evidencia\nliquor com dissociação albumino-citológica. Assinale a alternativa CORRETA, quanto ao\ndiagnóstico mais provável.","options":{"A":"Poliomielite.","B":"Meningite viral.","C":"Abscesso paravertebral.","D":"Síndrome de Guillain-Barrè.","E":"Tumor de fossa posterior."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-158432","number":"158432","sourceNumber":"158432","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma criança de 1 ano de idade dá entrada no Pronto Socorro, com história de várias\ncrises convulsivas nas últimas horas. Já recebeu\n1 dose de diazepam de 0,5 mg/kg e gardenal IM\n(5mg/kg) há menos de meia hora. Nunca havia convulsionado antes. Encontra-se em mau estado\ngeral, cianótica, pálida, com os olhos encovados e com pulsos finos; apresenta movimentos\ntônico-clônicos em membros. Assinale a alternativa correta quanto à conduta mais indicada neste\ncaso.","options":{"A":"Instalar acesso vascular, administrar duas doses de diazepam de 1 mg/kg EV, imediatamente.","B":"Oxigenar, completar a dose de gardenal IM para 10 mg/kg, imediatamente.","C":"Administrar três doses de diazepam 0,3 mg/kg EV, a cada 5 minutos e, por fim, tiopental EV.","D":"Desobstruir vias aéreas, oxigenar, acesso vascular, administrar diazepam 0,3 mg/kg EV SF0,9%\n20ml/kg EV, e fazer glicoteste.","E":"Observar a crise até que haja resolução espontânea da mesma, estando o paciente\ndevidamente oxigenado e após dar glicose hipertônica."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-362484","number":"362484","sourceNumber":"362484","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher de 29 anos apresenta-se com episódios recorrentes de cefaleia que duram\nde 4 a 72 horas quando não tratados. As\ndores de cabeça são frequentemente unilaterais,\npulsáteis, de intensidade moderada a severa, e agravadas pela atividade física rotineira. Ela\ntambém relata náuseas e fotofobia durante os episódios. Qual é o tratamento abortivo mais\napropriado para os episódios de cefaleia desta paciente?","options":{"A":"Triptanos.","B":"Amitriptilina.","C":"Topiramato.","D":"Profilaxia com beta-bloqueadores."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-362483","number":"362483","sourceNumber":"362483","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 37 anos de idade engenheiro bem- sucedido, casado, com epilepsia\nbem controlada por medicamentos, apresenta-se ao\npronto-socorro após uma convulsão\n\ntônico-clônica generalizada que durou 5 minutos. Ele relata que esqueceu de tomar sua medicação\nantiepiléptica nos últimos dois dias. Qual é a conduta mais apropriada?","options":{"A":"Iniciar um novo medicamento antiepiléptico.","B":"Internar para avaliação de \"\"status epilepticus\"\".","C":"Realizar uma tomografia computadorizada de emergência de crânio.","D":"Administrar uma dose de resgate do medicamento antiepiléptico atual."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-362482","number":"362482","sourceNumber":"362482","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma estudante de 20 anos apresenta ptose palpebral, diplopia e fraqueza muscular\nque piora com o esforço e melhora com o\nrepouso. A eletroneuromiografia mostra uma diminuição\nda amplitude do potencial de ação muscular com estimulação repetitiva. Qual é o diagnóstico mais\nprovável?","options":{"A":"Miastenia gravis.","B":"Síndrome de Lambert-Eaton.","C":"Esclerose lateral amiotrófica (ELA).","D":"Distrofia muscular facioescapuloumeral."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-327225","number":"327225","sourceNumber":"327225","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um adolescente compareceu ao ambulatório de neurologia acompanhado de sua mãe.\nO motivo da consulta foi estar apresentando\nvários episódios de \"desligamentos\" que duram\naproximadamente de 5 a 10 segundos, o paciente fica com o olhar fixo, perde contato com o meio\npor alguns segundos e muitas vezes não é percebida pelo paciente e sim pelos familiares e/ou\nprofessores. Geralmente são precipitadas por hiperventilação durante aula de artes marciais. Qual\no diagnóstico clínico mais provável para o paciente?","options":{"A":"Crises focais disperceptivas não motora.","B":"Crises focais perceptivas não motora.","C":"Crises generalizadas não motoras.","D":"Crise focal evoluindo para tônico-clônica bilateral."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-327226","number":"327226","sourceNumber":"327226","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um motorista de Uber 68 anos de idade, começou a apresentar sinais e sintomas\nneurológicos de caráter progressivo início do\nquadro há 18 meses. O que mais chamou sua\natenção foram diminuição das forças principalmente em membros superiores com músculos tensos\ne rígidos, atrofia em mãos, contrações musculares nos braços e língua, dificuldade para deglutição\ne fala anasalada. Qual o diagnóstico provável?","options":{"A":"Esclerose múltipla","B":"Esclerose lateral amiotrófica (ELA)","C":"Encefalomielite disseminada aguda (ADEM)","D":"Miastenia gravis"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-327297","number":"327297","sourceNumber":"327297","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Pré escolar de dois anos é levado a consulta por seus pais, por apresentar atraso de\nlinguagem; perda do uso da fala, uso de palavras isoladas, reação ausente ou tardia quando\nchamam seu nome, ausência de interesse social, brinca fazendo movimentos estereotipados, evita\ncontatos físicos e visuais. Nasceu de parto prematuro 32 semanas, permaneceu UTI neonatal por 6\nsemanas, devido sepse tardia, sem necessidade de ventilação mecânica. Exame físico normal,\nhipótese diagnostica provável é:","options":{"A":"Carência Afetiva","B":"Autismo","C":"Esquizofrenia","D":"Surdez sensório neural"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-298197","number":"298197","sourceNumber":"298197","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um motorista de ônibus de 35 anos iniciou quadro agudo de fraqueza muscular\ngeneralizada necessitando de internação hospitalar.\nRelata dormência nas mãos e formigamento\ndos dedos dos pés até um pouco acima dos joelhos. O exame neurológico mostrou função mental\npreservada, diparesia facial, fraqueza distal mais que proximal nas extremidades inferiores e\nfraqueza sutil nas mãos, os reflexos profundos estavam ausentes, sensibilidade superficial e\nprofunda preservadas. Ele se lembra de ter uma doença viral há uma semana. Qual o diagnóstico\nprovável?","options":{"A":"Mielite transversa.","B":"Esclerose múltipla.","C":"Síndrome de Guillain-Barré.","D":"Miastenia gravis."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-298198","number":"298198","sourceNumber":"298198","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma professora de 57 anos de idade, tabagista, em uso de losartana 50mg ao dia, sem\nantecedencia de diabetes, apresentou quadro súbito de acidente vascular cerebral isquêmico\nevoluindo com afasia e hemiplegia direita de predomínio braquial. A causa mais frequente de\ncardiopatia embolica é:","options":{"A":"Miocardiopatia","B":"Fibrilação atrial","C":"Cardiopatia reumática","D":"Endocardite"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-286713","number":"286713","sourceNumber":"286713","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um homem de 17 anos apresenta 10 dias de parestesias progressivas nos pés com\nacometimento ascendente atingindo as mãos e fraqueza nas pernas duas noites antes da\ninternação. Tem história de quadro diarreico 2 semanas antes das queixas neurológicas. No exame\nneurológico, apresenta paraparesia flácida arreflexa. Função respiratória ainda normal. O estado\nmental é normal. Os achados mais prováveis na análise do liquor são:","options":{"A":"Nível elevado de proteína.","B":"Contagem elevada de leucócitos.","C":"Pressão de abertura elevada.","D":"Bandas oligoclonais."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-256577","number":"256577","sourceNumber":"256577","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 60 anos de idade, agricultor, apresentando tetraparesia com sinais de\ncomprometimento do neurônio motor superior e do neurônio motor inferior. Progressão da doença,\ndentro de uma região ou para outras regiões e ausência de comprometimento sensitivo. O quadro\nclínico é característico de:","options":{"A":"Esclerose lateral amiotrófica","B":"Esclerose múltipla","C":"Síndrome de Guillain-Barré","D":"Neuropatia motora multifocal"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252216","number":"252216","sourceNumber":"252216","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 56 anos de idade com antecedência de hipertensão arterial sistêmica,\ndislipidemia e diabetes, apresentou acidente vascular encefálico agudo. Ao exame clínico\nneurológico, foi observado ptose palpebral e midríase, ambas à esquerda com acuidade visual\npreservada, e hemiparesia incompleta e proporcionada à direita. Este paciente apresenta lesão\nno(a):","options":{"A":"Ponte.","B":"Mesencéfalo.","C":"Bulbo.","D":"Lobo frontal esquerdo."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252217","number":"252217","sourceNumber":"252217","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma médica residente foi diagnosticada como Migrânea na emergência clínica. Qual\nalternativa abaixo preenchem os Critérios diagnósticos da migrânea sem aura?","options":{"A":"Cefaleia durando de 4 a 72 horas; localização unilateral; caráter pulsátil; intensidade moderada\nou forte; exacerbada por ou levando o indivíduo\na evitar atividades físicas rotineiras. Durante a\ncefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos; fotofobia e\nfonofobia.","B":"Cefaleia durando de 30 minutos a 7 dias; localização unilateral; caráter pulsátil; intensidade\nmoderada ou forte; exacerbada por ou levando o indivíduo a evitar atividades físicas rotineiras.\nDurante a cefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos;\nfotofobia e fonofobia.","C":"Cefaleia durando de 4 a 72 horas; localização unilateral; caráter pulsátil; intensidade leve ou\nmoderada; exacerbada por ou levando o indivíduo a evitar atividades físicas rotineiras. Durante a\ncefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos; fotofobia e\nfonofobia.","D":"Cefaleia durando de 30 minutos a 7 dias; localização unilateral; caráter pulsátil; intensidade\nleve\nou moderada; exacerbada por ou levando o indivíduo a evitar atividades físicas rotineiras. Durante\na cefaleia, apresenta pelo menos um dos seguintes sintomas: náuseas e/ou vômitos; fotofobia e\nfonofobia."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252226","number":"252226","sourceNumber":"252226","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação ao atendimento inicial do paciente em suspeita de morte encefálica,\nassinale a alternativa CORRETA:","options":{"A":"Paciente admitido em coma aperceptivo, com pupilas midriáticas e sem reflexo corneano deve\nter protocolo de morte encefálico nas primeiras\nhoras.","B":"Paciente com história de parada cardíaca, revertida no pré-hospitalar, admitido em Glasgow 3 e\nsem drive respiratório. Deve-se descartar síndrome coronariana aguda com eletrocardiograma em\n10 min, e logo iniciar protocolo de morte encefálica.","C":"Paciente em coma aperceptivo, com causa de coma definido por Hemorragia Subaracnoide\nFisher IV, após 6 horas de atendimento, deve ter\nprotocolo de morte encefálica iniciado.","D":"Paciente em coma aperceptivo, com causa de coma definido por sangramento e edema cerebral\ndifusos após trauma cranioencefálico grave, deve ter os cuidados estabelecidos nas primeiras\nhoras, com abordagem e preparo da família sobre doação de órgãos."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-256592","number":"256592","sourceNumber":"256592","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente com quadro agudo de AVC secundário a trombose, a artéria cerebral\nmédia à esquerda, segmento M1, apresentará qual exame neurológico mais provável?","options":{"A":"Hemiplegia e hipotonia à direita, associada a afasia.","B":"Hiperreflexia e hipertonia à direita.","C":"Paralisia facial esquerda acometendo o terço inferior da face e hemianestesia à direita.","D":"Hemiplegia direita e anosognosia esquerda."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-252305","number":"252305","sourceNumber":"252305","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Marília, 54 anos, vem à Unidade de Saúde referindo que há 3 meses apresenta alguns\nepisódios de vertigem rotatória, com duração de alguns minutos, associada a náuseas. Geralmente,\naparece após mudança de decúbito. Durante o exame físico, observa-se nistagmo horizontal, mais\nrápido para o lado esquerdo da paciente. É feito o diagnóstico de vertigem posicional paroxística\nbenigna onde o tratamento pode ser realizado através da manobra de reposicionamento otolítico,\nchamada manobra de Epley. Assinale a alternativa que traz os passos corretos desta manobra:","options":{"A":"1. pessoa sentada com membros inferiores dentro da maca; 2. rotação da cabeça para o lado\nafetado; 3. decúbito dorsal, com a cabeça para baixo ainda em rotação; 4. rotação para o lado\noposto; 5. decúbito lateral desse lado e 6. sentado com membros inferiores pendentes.","B":"1. pessoa sentada com membros inferiores pendentes na maca; 2. rotação da cabeça para o\nlado afetado; 3. movimento rápido do corpo encostando a face na maca; 4. movimento rápido do\ncorpo para o lado oposto, com a face para cima e 5. sentado com membros inferiores pendentes.","C":"1. pessoa sentada com membros inferiores pendentes; 2. movimento rápido do corpo para o\nlado afetado, encostando a orelha na maca; 3. movimento rápido do corpo para o lado oposto,\nencostando a outra orelha na maca e 4. Sentado com membros inferiores pendentes.","D":"1. pessoa sentada com membros inferiores dentro da maca; 2. rotação da cabeça para o lado\nnão afetado; 3. decúbito dorsal, com a pessoa olhando para cima; 4. sentado com membros\ninferiores dentro da maca; 5. rotação da cabeça para o lado afetado; 6. decúbito dorsal, com a\npessoa olhando para cima e 7. sentado com membros inferiores dentro da maca."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-208346","number":"208346","sourceNumber":"208346","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma criança de 8 anos de idade, foi avaliada com queixas de baixo rendimento escolar.\nA professora relatou que o aluno apresentava\nparada súbita e transitória da atividade, com duração\nde poucos segundos, acompanhada de episódios de automatismos orais e piscamento, sem\napresentar quedas. O Eletroencefalograma (EEG) mostrou complexos de espículas-onda\ngeneralizados a 3 Hz, com duração maior ou igual a 3 segundos. É característico de:","options":{"A":"Crises mioclônica-atônicas.","B":"Crises mioclônicas.","C":"Crises de ausência típica.","D":"Parada comportamental."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-208380","number":"208380","sourceNumber":"208380","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente foi diagnosticado como tendo síndrome do primeiro neurônio motor ou\npiramidal. Qual das alternativas abaixo traduz esta síndrome:","options":{"A":"Diminuição da força muscular, hipotrofia tardia, hipotonia, hiporreflexia profunda, sinal de\nBabinski, clônus, Hoffmann.","B":"Diminuição da força muscular, hipertonia, hipotrofia precoce, fasciculações, hiperreflexia\nprofunda.","C":"Diminuição da força muscular, hipotonia, hipotrofia precoce, fasciculações, hiporreflexia\nprofunda.","D":"Diminuição da força muscular, hipotrofia tardia, hipertonia, espasticidade, hiperreflexia\nprofunda,\nsinal de Babinski, clônus."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-208338","number":"208338","sourceNumber":"208338","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Pré-escolar de 3 anos, sexo masculino, é levado para consulta pediátrica pois sua\ngenitora observou que ele tem apresentado\ndesordem no desenvolvimento da linguagem,\ndificuldade nas relações sociais recíprocas, limitação na capacidade de desenvolver brincadeiras\nfuncionais simbólicas ou de faz de conta e necessidade obsessiva de uniformidade e resistência a\nmudanças. A principal hipótese diagnóstica é:","options":{"A":"Esquizofrenia.","B":"Surdez sensorial.","C":"Transtorno oposicional desafiante.","D":"Autismo infantil."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-176008","number":"176008","sourceNumber":"176008","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 34 anos de idade apresentando cefaleia recorrente foi diagnosticado\ncom cefaleia em salvas ou ?cluster headache?.\nQuais os sinais e sintomas são os mais prováveis\npara este diagnóstico?","options":{"A":"Cefaleia geralmente de moderada ou forte intensidade, pulsátil, unilateral com náuseas e/ou\nfotofobia, persistindo por 4?72 horas.","B":"Cefaleia geralmente de leve ou moderada intensidade, sensação difusa e dolorosa ou em\ncompressão em torno da cabeça, dor em couro cabeludo, persistindo por 30 minutos a 7 dias.","C":"Cefaleia geralmente intensa, excruciante, com congestão ocular, obstrução nasal, sudorese da\nfronte e da face ipsilateral, durando de 15?80 minutos.","D":"Ataques recorrentes de dor lancinante e súbita, descrita como um choque doloroso intenso e\nincapacitante. A dor pode ser desencadeada por falar, escovar os dentes, mastigar ou tocar\nlevemente no rosto."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-176012","number":"176012","sourceNumber":"176012","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Estudos de genética molecular permitiram identificar os genes consistentemente\nassociados com o maior risco de desenvolvimento\nda doença de Alzheimer. Qual das alternativas\nabaixo não está relacionada à doença de Alzheimer?","options":{"A":"Alterações nos genes da alfa-sinucleinas (SNCA).","B":"Proteína precursora do amiloide (APP).","C":"Apolipoproteína E (APOE).","D":"Presenilina 2 (PSEN2)."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-176016","number":"176016","sourceNumber":"176016","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 30 anos de idade apresentando ptose palpebral e diplopia flutuante\ndurante o dia recebeu o diagnóstico de\nmiastenia gravis. Qual o neurotransmissor envolvido na sua\nfisiopatologia?","options":{"A":"Dopamina.","B":"Acetilcolina.","C":"Serotonina.","D":"Glutamato"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-151858","number":"151858","sourceNumber":"151858","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 70 anos, com síndrome demencial, após avaliação neurológica\nexaustiva foi diagnosticado como doença de\nAlzheimer. Qual é o achado predominante na doença\nde Alzheimer?","options":{"A":"Desmielinização.","B":"Atrofia dos ganglios da base.","C":"Perda neuronal no córtex cerebral.","D":"Perda das células pigmentadas na substância negra."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-151862","number":"151862","sourceNumber":"151862","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 26 anos, com diagnóstico de miastenia grave, foi internado com\ninsuficiência respiratória aguda, sendo submetido a\ntratamento com plasmaférese. Em relação à\nmiastenia grave, marque a alternativa CORRETA:","options":{"A":"Ocorre um distúrbio pré-sináptico.","B":"Ocorre baixa liberação de acetilcolina.","C":"Ocorre aumento dos receptores de acetilcolina.","D":"Ocorre redução dos receptores de acetilcolina."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-151967","number":"151967","sourceNumber":"151967","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Lactente com 4 meses, evoluiu com crise convulsiva, apatia, irritabilidade, vômito,\nanemia hipocrômica, oxaluria e falha no desenvolvimento. Neste caso, qual teste terapêutico\nindicado?","options":{"A":"Riboflavina.","B":"Tiamina (81).","C":"Piridoxina (B6).","D":"Cobalamina (812)."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-129716","number":"129716","sourceNumber":"129716","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 70 anos, é trazido ao pronto-socorro devido quadro de crise convulsiva. A\ncausa mais frequente nesta faixa etária é:","options":{"A":"Neuroinfecção.","B":"Doença de Alzheimer.","C":"Acidente vascular encefálico.","D":"Tumores intracranianos."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-103827","number":"103827","sourceNumber":"103827","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A rápida correção do sódio em pacientes com hiponatremia crônica pode levar a\nmielinólise pontinha central que se caracteriza por:","options":{"A":"síndrome de liberação inadequada de hormônio antidiurético.","B":"paralisia flácida.","C":"hipotensão postural.","D":"paralisia pseudônimo bulhar e queda do nível de consciência."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-107822","number":"107822","sourceNumber":"107822","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A doença de Alzheimer (DA) é um transtorno neurodegenerativo progressivo e fatal que\nse manifesta por deterioração cognitiva e da\nmemória, comprometimento progressivo das\natividades de vida diária e uma variedade de sintomas neuropsiquiátricos e de alterações\ncomportamentais. Qual abordagem terapêutica NÃO é recomendada para esta doença:","options":{"A":"Os agonistas muscarínicos e nicotínicos e seus compostos, por aumentar a liberação da\nacetilcolina, são de grande benefício, pois apresentam efeitos clínicos importantes na DA.","B":"O tratamento da DA deve ser multidisciplinar, envolvendo os diversos sinais e sintomas da\ndoença e suas peculiaridades de condutas.","C":"Os fármacos colinérgicos donepezila, galantamina e rivastigmina são considerados os de\nprimeira linha, estando todos recomendados para tratamento da DA leve e moderada.","D":"Os benefícios esperados com o tratamento da DA são redução na velocidade de progressão da\ndoença e a melhora da memória e da\natenção."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-107850","number":"107850","sourceNumber":"107850","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação ao Acidente Vascular Encefálico (AVE) assinale a alternativa incorreta:","options":{"A":"O AVE é uma emergência médica e, eventualmente, poderá necessitar de tratamento cirúrgico.","B":"O AVE é a principal hipótese para o diagnóstico diferencial em pacientes com déficits\nneurológicos de início súbito.","C":"A desidratação em pacientes com AVE é geralmente associada a um pior prognóstico, e o uso\nde fluidos hipotônicas são melhor indicados,\numa vez que reduzem o risco de edema cerebral e\nhipertensão intracraniana, especialmente no infarto extenso.","D":"A hiperglicemia ocorre em mais da metade dos pacientes na fase aguda do AVE, mesmo\naqueles sem historia de diabetes mellitus, e está associada com aumento da morbidade e\nmortalidade."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-103833","number":"103833","sourceNumber":"103833","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O diagnóstico de migrânea ou enxaqueca é mais provável em que tipo de paciente?","options":{"A":"Cefaleia geralmente de leve ou moderada intensidade, sensação difusa e dolorosa ou em\ncompressão em torno da cabeça, dor em couro cabeludo.","B":"Cefaleia geralmente Intensa, excruciante com congestão ocular, obstrução nasal, sudorese da\nfronte e da face ipsilateral.","C":"Ataques recorrentes de dor lancinante e súbita, descrita como um choque doloroso intenso e\nincapacitante. A dor pode ser desencadeada por falar, escovar os dentes, mastigar ou tocar\nlevemente no rosto.","D":"Cefaleia geralmente de moderada ou forte intensidade pulsátil, unilateral com náuseas e/ou\nfotofobia."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-103858","number":"103858","sourceNumber":"103858","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na investigação da fase aguda do acidente vascular encefálico (AVE), qual é o método\nde exame de imagem mais recomendado, devendo\nser realizada o mais rapidamente possível?","options":{"A":"Tomografia computadorizada do crânio.","B":"Ressonância Magnética encefálica.","C":"Angiografia cerebral.","D":"Doppler transcraniano."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-103789","number":"103789","sourceNumber":"103789","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em epilepsia \"marcha jacksoniana\" e \"paralisia de Todd\", melhor representam:","options":{"A":"Crises tônico-clônicas generalizadas.","B":"Crises de ausência.","C":"Crises epilépticas focais.","D":"Crises mioclônicas."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-103794","number":"103794","sourceNumber":"103794","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na miastenia gravis o neurotransmissor envolvido na sua fisiopatologia é:","options":{"A":"Dopamina.","B":"Acetilcolina.","C":"Serotonina.","D":"Glutamato."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-80980","number":"80980","sourceNumber":"80980","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação à crise epiléptica, marque a alternativa INCORRETA:","options":{"A":"A Ressonância Nuclear Magnética (RM) do cérebro complementa o estudo eletroencefalográfico,\ndevendo ser realizada em todos os pacientes\nmaiores de 18 anos de idade com suspeita de\nepilepsia.","B":"Na investigação das crises, a punção lombar é mandatória se houver suspeita de meningite ou\nencefalite.","C":"As drogas empregadas no tratamento da epilepsia podem levar à osteopenia ou à osteomalacia,\ne, com isso, aumentar o risco de fraturas\nósseas.","D":"História prévia de neoplasia de mama pode sugerir necessidades de estudo de imagem cerebral,\npelo risco aumentado de metástases servirem\nde focos convulsivos.","E":"No tratamento das crises, a falta de resposta a uma determinada droga anticonvulsivante, como\na carbamazepina ou a fenitoína, impede a resposta\na outra droga, sendo recomendadas outras\nformas de tratamento."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-60846","number":"60846","sourceNumber":"60846","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 30 anos de idade vem apresentando episódios recorrentes de dor de\ncabeça unilateral, orbitária ou temporal,\ngeralmente acompanhada de hiperemia conjuntival,\nlacrimejamento, rinorreia, congestão nasal, miose, edema palpebral e sudorese facial. As crises\nduram de 15 minutos a 3 horas, que duram semanas ou meses e são separados por meses ou\nanos de remissão, livres de cefaleia. As manifestações clínicas referem-se a:","options":{"A":"Cefaleia em salvas","B":"Neuralgia trigeminal","C":"Cefaleia crônica diária","D":"Enxaqueca (migrânea)","E":"Arterite de células gigantes"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-61501","number":"61501","sourceNumber":"61501","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Conforme Protocolos Clínicos e Diretrizes Terapêuticas do Ministério da Saúde sobre\nMiastenia Gavis (MG) de 2010, assinale a alternativa INCORRETA:","options":{"A":"A Azatioprina é indicada em pacientes com glicocorticoiderresistentes ou com efeitos adversos\nimportantes e que precisem reduzir doses de prednisona.","B":"A forma MG juvenil trata-se de uma situação definida pelo surgimento de sinais e sintomas\nmiastênicos entre o 1º e o 11º ano de idade, 10% de todos os casos de MG.","C":"A crise Miastênica é definida como disfunção respiratória que exige ventilação mecânica, é uma\ncomplicação potencialmente fatal que ocorre em aproximadamente 15%-20% dos pacientes com\nMG.","D":"A Prednisona é o agente imunossupressor mais comumente utilizado em MG, e sua eficácia\nestá no controle dos sintomas e na diminuição\nde exacerbações. É reservado para os casos\nrefratórios a piridostigmina.","E":"Em casos de exacerbação clínica com risco de vida, a plasmaférese deve ser considerada da\nmesma forma que a imunoglobulina, se esta\núltima estiver contraindicada ou não for disponível."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-46671","number":"46671","sourceNumber":"46671","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A síndrome de Claude Bernard-Horner consiste em:","options":{"A":"Enoftalmia, Midríase e Ptose.","B":"Exoftalmia, Surdez e Ptose.","C":"Enoftalmia, Miose e Ptose.","D":"Exoftalmia, Miose e Ptose.","E":"Exoftalmia, Midríase e Surdez."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-46659","number":"46659","sourceNumber":"46659","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 18 anos de idade, estudante, há oito meses vem apresentando episódios de\nmovimentos mastigatórios e automatismos, constando de gestos desajeitados de mexer na roupa,\nagarrar ou manusear objetos ao seu redor. Ao ser agarrado por familiar fica agitado. O quadro dura\nalguns minutos e desde o início apresenta consciência alterada com confusão após a crise e\namnésia para o fato. Marque a alternativa abaixo que melhor caracteriza o tipo de crise epiléptica e\na topografia de origem mais frequente.","options":{"A":"Crise parcial simples e origina no lobo frontal.","B":"Crise parcial complexa e origina no lobo frontal.","C":"Crise parcial simples e origina no lobo temporal.","D":"Crise de ausência e origina em todos os hemisférios cerebrais.","E":"Crise parcial complexa e origina no lobo temporal."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-46667","number":"46667","sourceNumber":"46667","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Lactente de quatro meses, com quadro de anemia microcítica, crise convulsiva\nmioclônica de difícil controle desde o nascimento. O ECG mostra padrão hipsarritmia. Qual a\ndeficiência vitamínica?","options":{"A":"Biotina.","B":"Niacina.","C":"Tiamina.","D":"Piridoxina.","E":"Riboflavina."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-324665","number":"324665","sourceNumber":"324665","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 76 anos de idade, procura atendimento na UBS por episódios de dor intensa\nem hemiface esquerda, principalmente em região\nmaxilar e de mandíbula, graduando até 8/10 na\nescala de dor. O quadro se repete há 3 anos, associado a sensação de choques e é precipitado\npela mastigação ou frio. Tem hipertensão arterial sistêmica, em uso de hidroclorotiazida e\nenalapril.\nAo exame, apresenta-se em bom estado geral, com sinais vitais estáveis, com alodínia térmica em\nhemiface esquerda. Demais exames segmentares sem alterações. Considerando o caso clínico\ndescrito, indique o diagnóstico mais provável:","options":{"A":"Nevralgia do nervo facial.","B":"Nevralgia do nervo trigêmeo.","C":"Cefaleia em salvas.","D":"Arterite de células gigantes."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-324666","number":"324666","sourceNumber":"324666","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 76 anos de idade, procura atendimento na UBS por episódios de dor intensa\nem hemiface esquerda, principalmente em região\nmaxilar e de mandíbula, graduando até 8/10 na\nescala de dor. O quadro se repete há 3 anos, associado a sensação de choques e é precipitado\npela mastigação ou frio. Tem hipertensão arterial sistêmica, em uso de hidroclorotiazida e\nenalapril.\nAo exame, apresenta-se em bom estado geral, com sinais vitais estáveis, com alodínia térmica em\nhemiface esquerda. Demais exames segmentares sem alterações. O exame complementar mais\nadequado para diagnóstico etiológico nesse caso:","options":{"A":"Ressonância magnética de crânio.","B":"Tomografia computadorizada de crânio.","C":"Eletroencefalograma.","D":"Biópsia da artéria temporal."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-324667","number":"324667","sourceNumber":"324667","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 76 anos de idade, procura atendimento na UBS por episódios de dor intensa\nem hemiface esquerda, principalmente em região\nmaxilar e de mandíbula, graduando até 8/10 na\nescala de dor. O quadro se repete há 3 anos, associado a sensação de choques e é precipitado\npela mastigação ou frio. Tem hipertensão arterial sistêmica, em uso de hidroclorotiazida e\nenalapril.\nAo exame, apresenta-se em bom estado geral, com sinais vitais estáveis, com alodínia térmica em\nhemiface esquerda. Demais exames segmentares sem alterações. Diante do quadro, indique a\nmelhor opção terapêutica para controle da dor:","options":{"A":"Tramadol e oxigenioterapia.","B":"Analgésico comum e escalonar para opioides, conforme resposta.","C":"Carbamazepina, oxcarbamazepina ou gabapentina.","D":"Analgésico comum associado à corticoterapia."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-284574","number":"284574","sourceNumber":"284574","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 20 anos de idade, estava acompanhada da mãe no metrô quando apresentou\nperda da consciência, seguida de rigidez\nmuscular, abalos musculares difusos e perda\nesfincteriana. A equipe do metrô iniciou rapidamente os primeiros-socorros, colocando algo macio\nsob a cabeça da paciente até cessarem os abalos, que duraram cerca de um minuto. A mãe ficou\nbastante assustada e relatou que a paciente era portadora de diabetes mellitus tipo 1. Nega outras\ncomorbidades. Nunca havia apresentado quadro semelhante. Neste momento, a paciente\nencontra-se ainda inconsciente, com ventilação espontânea. Indique a alternativa mais adequada\nem relação ao quadro.","options":{"A":"A etiologia mais provável nesse caso é hiperglicemia.","B":"O quadro, obrigatoriamente, envolveu ambos os hemisférios cerebrais.","C":"Neste momento, provavelmente, a paciente se encontra em uma crise de ausência.","D":"O \"grito epiléptico\" ocorre durante a fase clônica da crise."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-62822","number":"62822","sourceNumber":"62822","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente, oito anos de idade, é internada com um quadro súbito de náuseas, vômitos,\ndiarreia e dor abdominal, procurou serviço de urgência, sendo-lhe prescrito antiemético e\nhidratação oral, porém não melhorou e passou a apresentar cefaleia, vertigem e tontura, seguidas\nde visão turva, ptose palpebral, diplopia, disfagia, disartria, boca seca e progrediu para paralisia\nflácida motora, claramente descendente, associada a comprometimento autônomo disseminado.\nEstado de consciência preservado. Nos antecedentes, chama atenção o histórico de alimentação\ncom conservas caseiras de carne suína. O diagnóstico mais provável é de:","options":{"A":"Diarreia aguda por E. coli.","B":"Síndrome de Guillain-Barré.","C":"Diarreia por rotavírus.","D":"Botulismo.","E":"Diarreia viral."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283849","number":"283849","sourceNumber":"283849","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os sinais de alarme (red flags) na dor lombar aguda indicam a necessidade de\ninvestigação adicional com exames de imagem específicos. A alternativa que contém um achado\nque é considerado um dos sinais de alarme é","options":{"A":"tabagismo.","B":"cardiopatia.","C":"teste Phalen positivo.","D":"uso crônico de corticosteroides.","E":"uso crônico de anti-inflamatórios não hormonais."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-215586","number":"215586","sourceNumber":"215586","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa CORRETA.","options":{"A":"As alterações da parede torácica, como a escoliose idiopática e o nanismo, não levam à falência\nrespiratória.","B":"As patologias que cursam com falência respiratória por lesão de parênquima pulmonar\ncostumam estar isoladas e nunca se associam a doenças obstrutivas das vias aéreas.","C":"A hipertonia muscular com disfunção da parede torácica e a alteração da deglutição são\nmecanismos que levam pacientes com quadros neurológicos à falência respiratória crônica.","D":"As doenças neuromusculares cursam somente com hipoventilação alveolar."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-215602","number":"215602","sourceNumber":"215602","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre a falência da musculatura respiratória, é CORRETO afirmar que as doenças\nneuromusculares:","options":{"A":"Fazem com que os músculos respiratórios não sejam capazes de gerar ventilação alveolar\nadequada, ocasionando insuficiência respiratória crônica.","B":"Têm quadro clínico agudo.","C":"Estão relacionadas com disfunções do parênquima pulmonar.","D":"Estão relacionadas com erros inatos do metabolismo, como doença de Leigh e deficiência de\ncarnitina."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-218153","number":"218153","sourceNumber":"218153","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um adulto de 32 anos, sexo masculino, comparece à consulta na Unidade de Saúde da\nFamília do seu bairro, queixando-se de: cefaleia com forte intensidade, unilateral à direita, de\nduração aproximada de 30 minutos, podendo chegar até duas horas, acompanhada de hiperemia\nconjuntival, lacrimejamento no olho direito, rubor em hemiface direita e, eventualmente, congestão\nnasal. Os sintomas iniciaram há dois meses e os ataques de dor ocorrem várias vezes ao dia.\n\nSobre esse caso clínico, é CORRETO afirmar que o diagnóstico é e o\ntratamento profilático recomendado é\n. A alternativa que preenche, CORRETA\ne sequencialmente, as lacunas do trecho acima é:","options":{"A":"Cefaleia em salvas / Verapamil.","B":"Cefaleia em salvas / Amitriptilina.","C":"Cefaleia tensional / Sumatriptana.","D":"Enxaqueca com aura / Amitriptilina.","E":"Enxaqueca sem aura / Sumatriptana."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-218171","number":"218171","sourceNumber":"218171","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre as cefaleias, analise as assertivas e identifique com V as verdadeiras e com F as\nfalsas. ( ) Pode-se estabelecer o diagnóstico para migrânea se um(a) usuário(a) apresentar mais de\numa crise cefaleia com duas das seguintes características: caráter pulsátil, náuseas ou vômitos,\nintensidade moderada a grave e localização unilateral. ( ) São consideradas indicações para o início\nda terapia profilática da enxaqueca crises com frequência maior que uma vez na semana, quando\ninterferem significativamente no dia a dia do usuário, quando há uso excessivo de medicamentos\npara outras patologias, quando os medicamentos da terapia abortiva apresentam efeitos adversos\ne/ou são ineficazes e de acordo com a preferência do usuário. ( ) O tratamento da migrânea pode\nser feito com a estratégia \"passo a passo\", na qual se introduz um medicamento por vez, do menos\npotentes ao mais, e se ajusta ou associa em função da resposta terapêutica do usuário, ou com a\nestratégia que estratifica o tratamento em função da intensidade e das características do problema\ndo usuário. A segunda apresenta melhores resultados clínicos e evita maior tempo de dor com\nsofrimento do usuário, mas a primeira tem menos efeitos colaterais. A alternativa que contém a\nsequência CORRETA, de cima para baixo, é:","options":{"A":"F, F, V.","B":"F, V, V.","C":"F, V, F.","D":"V, V, F.","E":"V, F, V."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-157684","number":"157684","sourceNumber":"157684","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Escolha a associação INCORRETA entre o segmento do nervo espinhal e a respectiva\nárea de inervação:","options":{"A":"S4 e S5 ? Região perianal.","B":"T10 ? Mamilo.","C":"C7 ? Dedo médio.","D":"L4 ? Face medial da perna."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-157694","number":"157694","sourceNumber":"157694","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Nos doentes portadores de lesão medular, são encontrados com frequência alguns\npadrões característicos de lesão neurológica. Sobre a Síndrome de Brown-Séquard, indique a\nalternativa CORRETA.","options":{"A":"É caracterizada pela desproporção entre a perda motora nas extremidades superiores, que é\nmuito mais acentuada que nos membros inferiores.","B":"Caracteriza-se por paraplegia e por dissociação da perda sensorial com a perda de sensibilidade\na dor e temperatura.","C":"Caracteriza-se por comprometimento motor ipsilateral e perda da sensibilidade postural,\nconcomitantes com a perda contralateral da sensibilidade térmica e dor.","D":"De todas as lesões incompletas, é a que tem pior prognóstico."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-157703","number":"157703","sourceNumber":"157703","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As lesões cranioencefálicas encontram-se entre os tipos de trauma mais frequentes.\nSobre o TCE, assinale a alternativa CORRETA.","options":{"A":"Síndrome de herniação do uncus é caracterizada por anisocoria, com dilatação pupilar e\nhemiplegia contralateral.","B":"Hematomas subdurais tem a forma biconvexa, e estão mais localizadas na região temporal ou\ntêmporo-parietal.","C":"Hematomas epidurais são relativamente raros e resultam da ruptura da artéria meníngea média.","D":"Os anticonvulsivantes devem ser usados rotineiramente em todos os TCE graves, e o agente\nhabitualmente utilizado é o\n\nfenobarbital."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-157677","number":"157677","sourceNumber":"157677","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"?Tradicionalmente, considera-se que a lesão cerebral traumática é leve quando o\nquadro evolui com ausência de sinais\nneurológicos focais e o paciente apresenta um nível de\nconsciência igual ou superior a na avaliação pela escala de coma de Glasgow.? Assinale a\nalternativa que preenche a lacuna ADEQUADAMENTE.","options":{"A":"10","B":"11","C":"12","D":"13"},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-157640","number":"157640","sourceNumber":"157640","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino, 67 anos de idade, foi transportado ao hospital por resgate com\nquadro de prostração intensa, dificuldade de\nfala, perda dos movimentos do lado direito do corpo.\nEle foi encontrado assim em sua casa há 1 hora, sendo que previamente estava em bom estado\ngeral, segundo familiares. Sua pressão era de 220 x 130 mmHg. Sobre esse quadro, aponte a\nalternativa CORRETA:","options":{"A":"Caso indicado trombólise, devemos tolerar essa PA a fim de proteger área de penumbra.","B":"No máximo, podemos tolerar uma PA de 180 x 110 mmHg.","C":"Em caso de sangramento, a redução da PA a nível de 140 mmHg reduz sequelas no desfecho.","D":"A fim de preservarmos área de penumbra, o ideal seria normotensão em 24 horas."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134758","number":"134758","sourceNumber":"134758","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente com queixa de cefaleia de fortíssima intensidade, lancinante, de início há\nalguns minutos. Foi suspeitado de cefaleia em salvas, que NÃO apresenta a característica de:","options":{"A":"Ser unilateral.","B":"Causar midríase unilateral.","C":"Responder bem a analgésicos.","D":"Responder a oxigênio."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134772","number":"134772","sourceNumber":"134772","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente foi encontrado com carta sugestiva de suicídio, desacordado, evacuado,\nurinado e, próximo ao seu corpo, foi\nencontrado tubo de substância que provavelmente se trata de\nveneno do tipo \"Chumbinho\", de acordo com os familiares. Dentro desse quadro clínico, qual dos\nlistados abaixo, NÃO se enquadra na intoxicação por carbamato?","options":{"A":"Mio fasciculação.","B":"Roncos.","C":"Boca seca.","D":"Miose."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134776","number":"134776","sourceNumber":"134776","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Pacientes, com graves patologias neurológicas, necessitam tanto de\nmonitorização, quanto de intervenção na dita\nPressão Intra Craniana. Qual dos parâmetros,\ncondutas ou achados abaixo listados, NÃO causa influência direta na Pressão Intra craniana?","options":{"A":"PCO2 arterial.","B":"Pressão arterial média.","C":"Posicionamento da cervical.","D":"Hiperemia Cerebral."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-139774","number":"139774","sourceNumber":"139774","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Avalie os itens a seguir. I. Idade entre 6 meses e 6 anos.; II. Temperatura axilar igual\nou superior a 38°C.; III. Duração inferior a 15\nminutos.; IV. A convulsão generaliza-se desde o\ninício ou após alguns minutos.; V. Exame neurológico normal, passado o período pós-ictal\nimediato. Os critérios das convulsões febris benignas (típicas) na infância estão contidos, APENAS,\nnos itens:","options":{"A":"I, II e III.","B":"III, IV e V.","C":"I, II, III e IV.","D":"IV e V."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-139767","number":"139767","sourceNumber":"139767","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino, 73 anos de idade, previamente diabético e hipertenso, procura\nhospital com ajuda dos filhos, com quadro de\nmal-estar geral, perda motora no membro inferior\nesquerdo e que agora se estende também para o membro superior homolateral. Sua pressão está\nelevada com valor de 210 x 110 mmHg. Sobre esse caso, assinale a alternativa CORRETA:","options":{"A":"O valor tolerável da pressão nessa situação depende de se existem complicações ou de se está\nproposta trombólise, caso confirmado AVC isquêmico com critério de trombólise.","B":"Reduzir a PA a 180 x 110 mmHg.","C":"Tolerar essa PA.","D":"Normalizar a PA em uma hora, pois se trata de emergência hipertensiva."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-139771","number":"139771","sourceNumber":"139771","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente hipertensa e diabética tipo 2 refere intensa cefaleia, a pior de sua via,\nalém de vômitos e turvação visual. Utiliza ambulatoriamente Captopril, Hidroclorotiazida e\nMetiformina. Realizada tomografia de crânio sem achados, assim decidido por Tomografia com\ncontraste, a pedido do neurologista. Podemos assim AFIRMAR que:","options":{"A":"a tomografia exclui lesões isquêmicas.","B":"o uso de contraste não consegue mudar a conduta.","C":"é necessário suspender metiformina para realização do exame com contraste.","D":"não existe necessidade de mudança de conduta no momento."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111819","number":"111819","sourceNumber":"111819","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente hipertenso mal controlado, suspendeu, durante as festas do final de ano, sua\nmedicação anti-hipertensiva, que era Atenolol, Enalapril e Hidroclorotiazida. Após discussão\nfamiliar, deu entrada no hospital com intenso mal-estar, desorientação e agitação, sendo, então,\nrealizada tomografia de crânio. Foi abordado por quadro de emergência hipertensiva, que foi\ncaracterizado na Tomografia de crânio. Qual dos itens abaixo NÃO é compatível com esse\ndiagnóstico?","options":{"A":"Hemorragia subaracnoide.","B":"Edema cerebral por vasodilatação.","C":"Hemorragia intraparenquimatosa.","D":"Hematoma subdural crônico."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111825","number":"111825","sourceNumber":"111825","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma medida necessária, a fim de abordarmos adequadamente o paciente com\nhipertensão intracraniana, é a pressão de perfusão\ncerebral. Qual dos itens abaixo NÃO faz parte\ndo seu cálculo?","options":{"A":"Pressão intracraniana.","B":"Pressão arterial média.","C":"Pressão venosa central.","D":"Pressão sistólica."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111844","number":"111844","sourceNumber":"111844","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Para qual das etiologias de cefaleia a Dexametasona se mostra MAIS indicada para\ntratamento?","options":{"A":"Cluster.","B":"Arterite Temporal.","C":"Hemorragia Intraparenquimatosa.","D":"Tensional."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111862","number":"111862","sourceNumber":"111862","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Qual das alternativas abaixo se mostra MAIS adequada ao quadro clínico de cefaleia\nem salvas?","options":{"A":"Responde à oxigenoterapia.","B":"Ocorre rinorreia.","C":"Ocorre midríase unilateral.","D":"Todos são compatíveis."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111870","number":"111870","sourceNumber":"111870","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente dá entrada no pronto-socorro queixando-se de intensa cefaleia e mal-estar de\ninício súbito nesta manhã, quando iniciou suas atividades. Em avaliação inicial, mostrava-se lúcida,\nmas com fácies de dor e algo agitada. Sua pressão demonstrava valores elevados de 200 x 100\nmmHg. Dessa forma, qual informação podemos considerar ADEQUADA?","options":{"A":"Trata-se de emergência hipertensiva.","B":"Trata-se de AVC Hemorrágico.","C":"Está indicado Nitroprussiato de Sódio.","D":"Inicialmente devemos medicar com analgésicos e ansiolíticos."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111933","number":"111933","sourceNumber":"111933","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de 3 anos, com história ou crises convulsivas, em uso regular de fenobarbital,\ndá entrada no pronto-socorro com convulsão\ntônico clônico generalizada de duração maior do que\n15 minutos, segundo relato dos pais. Mãe refere que a criança não recebeu as últimas 2 doses da\nmedicação. Qual é a sequência ADEQUADA de condutas para esse caso?","options":{"A":"Encaminhar o paciente imediatamente para a UTI.","B":"Permeabilizar vias aéreas, oferecer O2 e administrar as 2 doses de fenobarbital que a criança\nnão recebeu.","C":"Aguardar 30 minutos de crise convulsiva, pois como a criança já é convulsiva a conduta inicial é\nexpectante.","D":"Permeabilizar vias aéreas, oferecer oxigênio e administrar midazolan endovenoso."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-350874","number":"350874","sourceNumber":"350874","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 70 anos, hipertenso e diabético há 25 anos, vem em consulta com geriatra\ncom queixa de esquecimentos há 1 ano. Filha\nrelata que o mesmo teve episódio de desorientação\nquando estava dirigindo para igreja e necessitou auxílio do neto para chegar ao destino. Tem\napresentado dificuldade no controle de suas finanças e de suas medicações. Na avaliação\ncognitiva inicial, fez 28 de 30 pontos no Mini exame do estado mental, perdendo 2 pontos na\nevocação. Nível de escolaridade: superior completo. História de infarto do miocárdio com colocação\nde stent há 10 anos. Qual o próximo passo para auxiliar no diagnóstico neste caso?","options":{"A":"Encaminhamento para realização de avaliação neuropsicológica detalhada e coleta de líquor.","B":"Realização do teste fluência verbal semântica (animais) e o teste do desenho do relógio (TDR),\nrastreio para sintomas depressivos e ressonância magnética de crânio.","C":"Realização da avaliação cognitiva de Montreal (MoCA), bateria Addenbrooke (ACE-R), rastreio\npara sintomas depressivos e ressonância\nmagnética de crânio.","D":"Aplicação da escala \"avaliação clínica da demência? (CDR-Clinical Dementia Rating), rastreio\npara sintomas depressivos e neuropsiquiátricos,\nalém de tomografia de crânio sem contraste."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-350893","number":"350893","sourceNumber":"350893","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 40 anos é atendida no ambulatório com queixa de cefaleia. Relata que o\nquadro iniciou-se na adolescência, inicialmente\nno período menstrual. Sempre foi caracterizado por\ndor em lado direito da cabeça, associada a náuseas e fotofobia, com duração de 3 a 8 horas.\n\nConseguia lidar bem com isso até cerca de 3 meses, quando recebeu diagnóstico de esclerose\nsistêmica durante investigação de desconforto em\nmãos associado a palidez local seguida de\narroxeamento e vermelhidão. Refere quadro de tristeza após essa descoberta, mas nega\nalterações do sono, alimentação ou perda de interesse por atividades prazerosas. Entretanto, relata\nque a frequência das dores de cabeça passou a ser a cada 2 ou 3 semanas e tem interesse em\nfazer uso de profilaxia medicamentosa. Qual das medicações abaixo é mais apropriada para esta\npaciente?","options":{"A":"Verapamil.","B":"Propranolol.","C":"Amitriptilina.","D":"Sumatriptano."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-350890","number":"350890","sourceNumber":"350890","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 64 anos, hipertenso e diabético, comparece ao pronto-atendimento com\nhemiparesia em dimidio direito. Percebeu alteração ao despertar hoje, pela manhã, às 6h, 1 hora\nantes do atendimento médico. PA 240x130mmHg. Realizou tomografia de crânio sem contraste\nsem sinais de sangramento intracraniano. Dentro desse contexto, qual a conduta mais adequada a\nser realizada?","options":{"A":"Encaminhar paciente para trombectomia.","B":"Iniciar trombolítico endovenoso, imediatamente.","C":"Administrar anti-hipertensivo parenteral para trombólise, após controle pressórico adequado.","D":"Prescrever anti-hipertensivo endovenoso, antiagregação plaquetária e estatina de alta potência."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321303","number":"321303","sourceNumber":"321303","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"SM, 78 anos, físico, antecedente de HAS e episódio prévio de hemorragia\nsubaracnóidea há 10 anos, informa que há 6\nmeses vem apresentando alteração de marcha\ncaracterizada por uma base de sustentação alargada, com os artelhos desviados lateralmente,\npostura ligeiramente fletida, aumento do balanço do tronco durante a marcha e diminuição da altura\ne comprimento dos passos. Há lentidão e hesitação ao iniciar a marcha com os pés parecendo\ngrudados ao chão. Nesse período, também passou a apresentar incontinência urinária. A esposa\nrelata que tem percebido o paciente com déficit de atenção, alterações de comportamento e de\npersonalidade e disfunção executiva manifestada por diminuição do processamento de informações\ncomplexas, e dificuldade para manipular novos conhecimentos. O paciente traz exames\nlaboratoriais normais, recentes, incluindo hemograma, eletrólitos, função renal e tireoidiana,\nenzimas hepáticas, glicemia e hemoglobina glicada, dosagem de vitaminas B12 e ácido fólico,\nlipidograma, VDRL e anti-HIV. A RM de crânio mostrou atrofia global leve e escala de atrofia mesial\ntemporal (MTA) de 1; microangiopatia periventricular Fazekas 1, além de aumento dos ventrículos,\nacompanhado de arredondamento dos cornos frontais e alargamento dos cornos temporais.\n\nAssinale, dentre as alternativas abaixo, a hipótese diagnóstica adequada para o caso clínico acima.","options":{"A":"Depressão.","B":"Doença de Alzheimer.","C":"Doença de Biswanger.","D":"Hidrocefalia de pressão normal."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321312","number":"321312","sourceNumber":"321312","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 25 anos, portador de epilepsia, é trazido ao departamento de emergência\ncom convulsão tônico- clônica generalizada.\nForam puncionados dois acessos venosos periféricos\ncalibrosos, de imediato, coletados exames laboratoriais de urgência, instalada monitorização e\nadministrados diazepam e fenitoína. Glicemia capilar 110mg/dL. O quadro convulsivo persiste,\nsendo administrada nova dose de diazepam endovenosa. Considerando o período de crise superior\na 30 minutos e a refratariedade às medidas instituídas até o momento, qual a próxima conduta?","options":{"A":"Prescrever fenobarbital endovenoso.","B":"Administrar uma dose adicional de diazepam.","C":"Iniciar sedação e proceder à intubação orotraqueal.","D":"Infundir fenitoína intravenosa em dose inferior à primeira."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321315","number":"321315","sourceNumber":"321315","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 28 anos é admitido na emergência com quadro de fraqueza muscular\nprogressiva ascendente há 3 semanas. Refere ainda\nparestesias discretas nos dedos das mãos.\nApresenta ausência de reflexos aquileu e patelar bilateralmente. Realizada punção lombar, que\nevidenciou proteinorraquia de 88mg/dL e 3 células/mm3 . Considerando a principal hipótese\ndiagnóstica, qual o tratamento de escolha?","options":{"A":"Plasmaférese.","B":"Reposição de vitamina B12.","C":"Pulsoterapia com metilprednisolona.","D":"Antibioticoterapia de amplo espectro."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321320","number":"321320","sourceNumber":"321320","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Adolescente, 12 anos, iniciou quadro de tosse produtiva e descarga nasal amarelada\nhá 2 semanas, evoluindo há 24 horas com\nfebre, cefaleia intensa, vômitos, proptose, dor e edema\nperiorbitário à direita, associado a oftalmoparesia ipsilateral. Qual é a principal hipótese\ndiagnóstica?","options":{"A":"Meningite.","B":"Pseudotumor cerebral.","C":"Leucemia mieloide aguda.","D":"Trombose de seio cavernoso."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321329","number":"321329","sourceNumber":"321329","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Lactente, 1 ano, previamente hígido, é trazido à emergência pelos pais devido à crise\nconvulsiva tônico-clônica generalizada. Genitora relata que a criança iniciou a crise logo após\ndespertar, aparentemente, sem nenhum fator desencadeante. Nega febre, trauma, uso de\nmedicações ou histórico de infecção recente. À admissão, paciente apresenta movimentos\n\ntônico-clônicos de membros e sialorreia importante, com os seguintes parâmetros: FC - 140bpm;\nFR - 40irpm; SatO2 - 96% (sob máscara de\noxigênio); Temperatura axilar - 36,5°C; glicemia capilar\n\n- 86 mg/dL. Qual das seguintes alternativas é a farmacoterapia mais apropriada nesse momento?","options":{"A":"Fenitoína, dose: 5mg/Kg, via endovenosa.","B":"Fenobarbital, dose: 5mg/Kg, via endovenosa.","C":"Diazepam, dose: 0,5mg/Kg, via intramuscular.","D":"Midazolam, dose: 0,2mg/Kg, via intramuscular."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321351","number":"321351","sourceNumber":"321351","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Seu Edinaílson, de 60 anos, é trazido para consulta por seus dois filhos: Edberto e\nEdnardo. Ele vem em cadeira de rodas, mas\nestá com punhos e tornozelos contidos. Segue o\nrelato dos filhos - Papai sempre foi um mecânico de referência aqui no bairro, mas tem dois anos\nque as coisas desandaram. A gente foi vendo ele ficar cada vez mais magro e não entendia o que\nestava acontecendo. Depois, o salário começou a diminuir, mas quando a gente perguntava, ele\nficava muito irritado. Levamos numa clínica popular, onde ele fez uma bateria de exames para\ndiabetes, pressão, hepatite e até sífilis e HIV, mas nunca deu nada. Ele começou a perder o prazo\ndos serviços e começou a fazer os serviços pela metade, mas o pior foi que ele começou a\ndestratar todo mundo. Ele sempre foi uma pessoa calma, mas começou a falar palavrão e querer\nbater nos outros. A gente só foi saber disso depois de um ano, porque ele chegou em casa\nmachucado porque tinha se envolvido em briga. A gente foi na oficina e o dono falou que ele não\ntinha mais condições de trabalhar. Ele disse que papai começou a urinar no chão do banheiro, que\nnão comia mais e que não se vestia mais direito. Levamos ele para cuidar em casa, mas ele estava\nmuito teimoso e briguento. Não queria comer, não queria tomar banho e não queria se vestir.\n\nEstamos levando do jeito que dá, mas quando ele começou a se urinar e se sujar, a gente viu que\nprecisava vir pedir ajuda de novo. Ele não está mais sabendo mexer em dinheiro, não toma mais\nbanho sem ajuda e agora começou a engasgar com a comida. Ele consegue andar e tem força,\nmas a gente teve que amarrar ele nessa cadeira, porque ele fica querendo pegar nas mulheres, é\nhorrível. Ele lembra da gente, lembra da nossa mãe, lembra dos irmãos, mas a gente não\nreconhece mais ele. Os filhos trouxeram exames laboratoriais recentes. Não havia alteração\nendócrino-metabólica significativa, nem hidroeletrolítica ou autoimune. Os exames de rastreamento\nde ISTs (HIV, sífilis e hepatites) também estavam sem alterações significativas. Ao se aproximar\npara realizar o exame físico de Seu Edinaílson, ele se mostrava calmo, mas pouco cooperativo. Ele\nsoube dizer o nome completo e reconheceu os filhos. Estava desorientado em espaço. O exame\nfísico não revelou alterações clínicas significantes. Assinale a alternativa com o diagnóstico\netiológico mais provável para a síndrome demencial apresentada no quadro.","options":{"A":"Doença de Creutzfeldt-Jakob.","B":"Demência Frontotemporal.","C":"Demência de Alzheimer.","D":"Demência Vascular."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-321352","number":"321352","sourceNumber":"321352","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Seu Edinaílson, de 60 anos, é trazido para consulta por seus dois filhos: Edberto e\nEdnardo. Ele vem em cadeira de rodas, mas\nestá com punhos e tornozelos contidos. Segue o\nrelato dos filhos - Papai sempre foi um mecânico de referência aqui no bairro, mas tem dois anos\nque as coisas desandaram. A gente foi vendo ele ficar cada vez mais magro e não entendia o que\nestava acontecendo. Depois, o salário começou a diminuir, mas quando a gente perguntava, ele\nficava muito irritado. Levamos numa clínica popular, onde ele fez uma bateria de exames para\ndiabetes, pressão, hepatite e até sífilis e HIV, mas nunca deu nada. Ele começou a perder o prazo\ndos serviços e começou a fazer os serviços pela metade, mas o pior foi que ele começou a\ndestratar todo mundo. Ele sempre foi uma pessoa calma, mas começou a falar palavrão e querer\nbater nos outros. A gente só foi saber disso depois de um ano, porque ele chegou em casa\nmachucado porque tinha se envolvido em briga. A gente foi na oficina e o dono falou que ele não\ntinha mais condições de trabalhar. Ele disse que papai começou a urinar no chão do banheiro, que\nnão comia mais e que não se vestia mais direito. Levamos ele para cuidar em casa, mas ele estava\nmuito teimoso e briguento. Não queria comer, não queria tomar banho e não queria se vestir.\n\nEstamos levando do jeito que dá, mas quando ele começou a se urinar e se sujar, a gente viu que\nprecisava vir pedir ajuda de novo. Ele não está mais sabendo mexer em dinheiro, não toma mais\nbanho sem ajuda e agora começou a engasgar com a comida. Ele consegue andar e tem força,\nmas a gente teve que amarrar ele nessa cadeira, porque ele fica querendo pegar nas mulheres, é\nhorrível. Ele lembra da gente, lembra da nossa mãe, lembra dos irmãos, mas a gente não\nreconhece mais ele. Os filhos trouxeram exames laboratoriais recentes. Não havia alteração\nendócrino-metabólica significativa, nem hidroeletrolítica ou autoimune. Os exames de rastreamento\nde ISTs (HIV, sífilis e hepatites) também estavam sem alterações significativas. Ao se aproximar\npara realizar o exame físico de Seu Edinaílson, ele se mostrava calmo, mas pouco cooperativo. Ele\nsoube dizer o nome completo e reconheceu os filhos. Estava desorientado em espaço. O exame\nfísico não revelou alterações clínicas significantes. O manejo farmacológico de sintomas\nneurocognitivos e comportamentais nas síndromes demenciais se dá geralmente com\n\nantidepressivos e antipsicóticos. No entanto, é preciso atenção ao uso de psicofármacos em idosos\ndevido a potenciais efeitos adversos. Considerando o quadro clínico de Seu Edinaílson, assinale a\nalternativa que traz uma opção de tratamento antidepressivo adequado em idosos.","options":{"A":"Diazepam.","B":"Trazodona.","C":"Amitriptilina.","D":"Tranilcipromina."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-292818","number":"292818","sourceNumber":"292818","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"ACR, 82 anos, advogado aposentado, há 6 meses passou a apresentar esquecimento\npara fatos recentes, tendo passado a esquecer\nde pagar as contas da casa e teve sua energia\ncortada pela companhia elétrica. Relata que no fim da tarde é comum ver uma criança\ndesconhecida brincando na varanda de sua casa. Relata também sono agitado com muitos\npesadelos frequentes. A esposa informa que há dias em que ele está muito apático, ficando\nisolado, sem se comunicar. O exame físico é normal, exceto pela presença de rigidez em roda\ndenteada em punho direito. Mini Exame do Estado Mental (MEEM) foi 25/30. Durante o MEEM\nrespondeu que estava no consultório de seu dentista, lembrou duas das três palavras solicitadas na\nevocação e errou três cálculos. Os exames laboratoriais são normais, exceto por anemia leve\nobservada no hemograma (Hb = 11g/dl; Ht 38%; VCM 100 fl; HCM 31 pg). A dosagem de vitamina\nB12 foi 259 pg/ml (VR: 239 a 931 pg/ml). A ressonância magnética de crânio mostrou atrofia global\nleve e escala de atrofia mesial temporal (MTA) de 1. Qual a principal hipótese diagnóstica para o\ncaso clínico?","options":{"A":"Doença de Alzheimer.","B":"Doença de Parkinson.","C":"Demência por corpúsculos de Lewy.","D":"Demência por deficiência de vitamina B12."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-292824","number":"292824","sourceNumber":"292824","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 30 anos procura atendimento no posto de saúde devido a episódios de\ncefaleia holocraniana em aperto, desde os 20 anos.\nDurante os episódios, a paciente deixa de fazer\natividades cotidianas, assim como prefere ficar em seu quarto com janela fechada e sem barulho.\n\nAo tentar fazer atividade física durante os episódios, relata piora dos sintomas com dor pulsátil em\nregião temporal. Nega vômitos durante os episódios. Se não tomar analgésicos, a paciente refere\nque fica até dois dias com dor. Faz uso de paracetamol 1 grama durante os episódios e, em\nalgumas ocasiões, faz uso deste medicamento mais de duas vezes ao dia. Nos últimos meses,\napresenta em média 8 crises ao mês. É portadora de asma e tem exame físico e neurológico\nnormais. Qual das medicações a seguir deve ser utilizada na paciente acima para diminuir a\nocorrência de crises de cefaleia?","options":{"A":"Topiramato.","B":"Naratriptano.","C":"Propranolol.","D":"Dipirona."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-292844","number":"292844","sourceNumber":"292844","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma criança de sete anos de idade chega à sala de emergência com história de\ninfecção intestinal há 2 semanas, e que após a\nmelhora clínica passou a apresentar fraqueza\nmuscular em ambos os membros inferiores acompanhados de dor e parestesia bem como de\ndificuldades de deglutição e constipação intestinal. Os reflexos tendinosos estavam ausentes. Qual\na hipótese diagnóstica mais provável?","options":{"A":"Esclerose múltipla.","B":"Encefalite herpética.","C":"Polirradiculoneurite aguda.","D":"Encefalomielite disseminada aguda."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-292846","number":"292846","sourceNumber":"292846","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No ambulatório, uma criança de 30 meses de idade apresenta alterações compatíveis\ncom Transtorno do Espectro Autista. Qual dos\ncritérios abaixo certamente foram considerados\ncomo os mais importantes na definição da hipótese diagnóstica?","options":{"A":"Capacidade limitada para fazer amizade com seus pares assim como algum prejuízo na\ncapacidade de iniciar ou manter uma conversação.","B":"Prejuízo limitado na espontaneidade de compartilhar prazer, interesses ou realizações com\noutras pessoas (p.ex., não mostrar, trazer ou apontar objetos de interesse).","C":"Prejuízo acentuado no uso de múltiplos comportamentos não verbais, como contato visual\ndireto, expressão facial, postura corporal e gestos para regular a interação social.","D":"Prejuízo limitado na atividade imaginativa, como representação de papéis de adultos,\npersonagens de fantasia ou animais; falta de interesse em histórias sobre acontecimentos\nimaginários."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-292867","number":"292867","sourceNumber":"292867","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em um turno de demanda programada na Unidade, Vanusa, irmã de Vanessa, traz\ndona Benzarina para atendimento. A consulta é\npara mostrar exames solicitados há seis meses. O\nregistro no prontuário traz ?síndrome demencial com predominância de disfunção executiva,\nsintomas neurológicos focais, síndrome pseudobulbar e início precoce de alteração de marcha?. A\nressonância nuclear magnética de crânio evidencia acometimento extenso de substância branca,\nno giro do cíngulo, no lobo temporal medial e no tálamo. Assinale a alternativa com o diagnóstico\nmais provável.","options":{"A":"Demência vascular.","B":"Demência de Alzheimer.","C":"Demência frontotemporal (DFT).","D":"Demência por corpúsculo de Lewy."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-259710","number":"259710","sourceNumber":"259710","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente, 65 anos, masculino, procura atendimento médico na Unidade Básica de\nSaúde devido a tremor em membros superiores\niniciado há pelo menos 5 anos. Paciente refere que\no tremor está atrapalhando suas atividades como escrita e alimentação, pois piora nessas\natividades, sem ser perceptível no repouso. Nega outros sintomas. Paciente é asmático e por isso\nnão fuma nem usa bebidas alcoólicas. Nega história familiar. Ao exame físico: Pressão Arterial de\n110 x 70mmHg; Pulso: 62 batimentos por minuto; presença de tremor em membros superiores\nvisualizada durante prova dos braços estendidos e índex-índex. Sem outras alterações. Qual o\nmelhor tratamento para o paciente acima?","options":{"A":"Primidona.","B":"Biperideno.","C":"Propranolol.","D":"Levodopa/carbidopa."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-259713","number":"259713","sourceNumber":"259713","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente 30 anos, feminino, procura atendimento em UPA devido a quadro de cefaleia.\nA paciente apresenta crises de cefaleia desde\nos 15 anos, algumas vezes incapacitantes,\npreferindo locais mais calmos e com pouca luminosidade, deixando de fazer atividades de rotina\nquando está com dor de cabeça. Alguma das crises são associadas com náuseas e vômitos. Ela\nprocura o atendimento com crise semelhante, com vômitos, iniciada há aproximadamente 20 horas,\nporém sem apresentar melhora com o uso de analgésicos que usa de rotina. Nega outras queixas\nou condições médicas relevantes. Exame físico e neurológico sem alterações. Pressão Arterial\n110x70mmHg, Pulso 90 batimentos por minuto. Qual a melhor conduta farmacológica para essa\npaciente, no momento?","options":{"A":"Dipirona 1 grama via oral.","B":"Tramadol 100mg endovenoso.","C":"Dexametasona 10mg endovenoso.","D":"Metoclopramida 10mg endovenoso."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-259743","number":"259743","sourceNumber":"259743","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Para o diagnóstico de Transtorno do Espectro Autista são necessários o preenchimento\nde critérios estabelecidos pelo DSM-5. Dentre os\nenunciados abaixo, qual o que apresenta maior\ncontribuição para definir os transtornos do espectro autista?","options":{"A":"Prejuízo na capacidade de iniciar ou manter uma conversação associado com falta de jogos ou\nbrincadeiras de imitação social variados.","B":"Atrasos ou funcionamento anormal para jogos imaginativos ou simbólicos e para manter\nadequadamente padrões de interação social.","C":"Padrões restritos de comportamento, interesses e atividades com adesão inflexível a rotinas ou\nrituais específicos e não funcionais.","D":"Déficit na interação social, visualizado na inabilidade em se relacionar com o outro, em geral\ncombinado com déficits de linguagem e alterações de comportamento."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-259747","number":"259747","sourceNumber":"259747","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma criança de 36 meses de idade chega no ambulatório com seus familiares uma\nsemana após ter tido uma crise convulsiva\nfebril. Qual das alternativas contém uma situação de\nrisco para recorrência das convulsões?","options":{"A":"O fato de a convulsão ter ocorrido com temperatura acima de 39 graus.","B":"O fato de a convulsão ter ocorrido nas primeiras 12 horas do surgimento da febre.","C":"O fato de a convulsão ter sido desencadeada após vacinação da criança de rotina.","D":"O fato de a convulsão ter sido classificada como generalizada e com duração inferior a 15\nminutos."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-259761","number":"259761","sourceNumber":"259761","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente, 75 anos, analfabeta, portadora de osteoartrose, hipertensão arterial sistêmica\ne diabetes mellitus não-insulino dependente.\nComparece ao posto de saúde para consulta de rotina\nacompanhada de sua filha. Apresenta a seguinte avaliação multidimensional: VISÃO ? Aplicação\ndo cartão de Jaeger: olho direito 20/70 e olho esquerdo 20/70. AUDIÇÃO ? Aplicação do teste do\nsussurro (whisper): paciente responde corretamente à pergunta formulada próxima ao ouvido direito\ne próxima ao ouvido esquerdo. FUNÇÃO DOS MEMBROS SUPERIORES PROXIMAL ? Paciente\nconsegue tocar a nuca com ambas as mãos. DISTAL ? Paciente consegue apanhar um lápis sobre\na mesa com cada uma das mãos e colocá-lo de volta no mesmo lugar. FUNÇÃO DOS MEMBROS\nINFERIORES ? Paciente consegue levantar da cadeira sozinho na segunda tentativa, mas utiliza\nos braços como apoio. Consegue caminhar 3,5 metros, voltar e sentar. ESTADO MENTAL ? Escore\ndo mini exame do estado mental (MEEM) de 15 pontos. HUMOR ? Escala de depressão geriátrica\nabreviada (GDS) = 12 pontos. DOMICÍLIO ? Paciente nega queda nos últimos 12 meses. Em sua\ncasa, não há escadas/batentes, tapetes soltos nem corrimão no banheiro. ATIVIDADES DIÁRIAS ?\nPaciente, sem auxílio, é capaz de sair da cama e preparar suas refeições. Porém, não consegue\nfazer compras. INCONTINÊNCIA ? Nega perda involuntária de urina. NUTRIÇÃO ? Nega perda de\npeso no último ano. Peso usual de 82 Kg. Altura usual de 1,60 cm. SUPORTE SOCIAL ? Conta\ncom apoio de sua filha mais nova para ajudá-la e caso fique incapaz de tomar decisões. Baseado\nna avaliação multidimensional da idosa acima descrita, qual a conduta mais adequada?","options":{"A":"Solicitar audiometria.","B":"Iniciar um antidepressivo.","C":"Prescrever um andador ou bengala.","D":"Reavaliar acuidade visual a cada 3 meses."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-259765","number":"259765","sourceNumber":"259765","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino, 55 anos, comparece à demanda espontânea com queixa de dor\nlombar iniciada há 1 semana durante a qual\nmanteve repouso relativo, pois já tinha passado por\ncrises semelhantes, mas que resolviam apenas com repouso e uso de relaxantes musculares. No\nentanto, dessa vez, resolveu buscar atendimento, pois além da persistência da dor tem sentido\ndormência na perna direita. Nega alterações urinárias ou intestinais ou dormência perineal. Ao\nexame, apresenta Lasègue positivo à direita e diminuição da força de dorsiflexão do pé direito. Qual\na conduta indicada nesse caso?","options":{"A":"Fisioterapia e retorno em 3 meses.","B":"Encaminhar para serviço de emergência.","C":"Anti-inflamatório oral e retorno em 1 semana.","D":"Corticoide de depósito e retorno em 1 mês."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234007","number":"234007","sourceNumber":"234007","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente, sexo masculino, 55 anos, portador de lombalgia cro?nica meca?nica\ninespeci?fica, ha? dois anos, com episo?dios\npouco frequentes de piora intermitente da dor.\nOntem, compareceu a? UPA com dor intensa, em choque, e pontadas (EVN10 de 10) na regia?o\nlombar com irradiac?a?o para ambas as pernas que apareceu apo?s levantamento de um peso no\ntrabalho. Nega trauma. Foi prescrito analge?sico sem melhora significativa e retornou para casa.\n\nHoje, acordou com retorno da intensidade da dor em 10, queixando-se de impossibilidade de andar\ne perda da contine?ncia urina?ria. Tem\nhisto?rico de transtorno depressivo grave tratado ha? dois\nanos. Atualmente sem medicac?o?es. Foi asma?tico e fez utilizac?a?o de corticoides por via oral,\ncronicamente, por cerca de 15 anos. Ao exame fi?sico, apresenta-se imo?vel no leito, intensa dor\na? mi?nima mobilizac?a?o, forc?a difi?cil de quantificar (pela presenc?a de dor intensa),\nsensibilidade alterada em territo?rio de L4?L5 e L5?S1, reflexos patelar e aquileu abolidos\nbilateralmente. Toque retal sugere hipotonia esfincteriana. Lasègue cla?ssico positivo\nbilateralmente. LEGENDA: EVN: Escala Visual Nume?rica de dor. Qual a conduta mais apropriada\npara o caso?","options":{"A":"Solicitar, imediatamente, transfere?ncia regulada para servic?o ciru?rgico tercia?rio\nespecializado.","B":"Solicitar ressona?ncia magne?tica de coluna lombar, analgesia e manter na observac?a?o da\nUPA.","C":"Solicitar PSA, PCR, tomografia computadorizada e encaminhar para ambulato?rio especializado.","D":"Solicitar ressona?ncia magne?tica de coluna lombar e encaminhar para ambulato?rio\nespecializado."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234038","number":"234038","sourceNumber":"234038","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher, 66 anos, acompanhada há 6 anos devido a doença de Parkinson, em uso de\nlevodopa desde o início do acompanhamento. Há 8 meses, apresenta movimentos involuntários,\ninicialmente em membros inferiores, depois acontecendo também em tronco e membros superiores,\niniciados após 90 minutos da tomada da levodopa, durando aproximadamente 30 minutos. Faz uso\natual de levodopa/carbidopa 250/25mg 1/2 (meio) comprimido em 5 tomadas ao dia (intervalo\nmédio de 3 horas entre as tomadas). Nega uso de outras medicações ou perda de efeito (rigidez,\nlentificação ou tremor) entre as tomadas. Ao exame neurológico são observados movimentos\ncoreiformes em membros inferiores e superiores, além de leve rigidez e bradicinesia assimétricas.\n\nQual a melhor opção terapêutica para ser associada a levodopa/carbidopa nessa paciente para\ndiminuir os movimentos descritos?","options":{"A":"Amantadina.","B":"Pramipexol.","C":"Biperideno.","D":"Rasagilina."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234040","number":"234040","sourceNumber":"234040","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 40 anos, com antecedente de epilepsia em uso irregular de ácido valproico 1\ngrama ao dia, sem tomar a medicação há 1 semana, é trazido pelo SAMU por apresentar episódios\nde convulsão tônico-clônicos generalizados há 30 minutos. Nesse período, o paciente já\napresentou 3 episódios com duração aproximada de 5 minutos cada, sem recobrar a consciência.\nApresentou, durante o transporte, mais um episódio convulsivo e foi medicado pelo médico do\nSAMU 2 vezes com diazepam 10 mg endovenoso. Na chegada, o paciente apresenta nova crise\nconvulsiva que persiste até o início de sua avaliação (aproximadamente 5 minutos). Ao exame,\npulso: 90 batimentos por minuto, pressão arterial de 160 x 90 mmHg. Glicemia capilar de 100 mg/dl.\nPeso aproximado de 80 kg. Após a monitorização e suporte clínico, qual a melhor conduta\nfarmacológica?","options":{"A":"Diazepam 10 mg endovenosa.","B":"Fenitoína 1.600 mg endovenosa lenta.","C":"Acido valproico 2 gramas via sonda.","D":"Fenobarbital 1.600 mg endovenoso lento."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234042","number":"234042","sourceNumber":"234042","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 80 anos, viúvo, aposentado e analfabeto, mora com a filha e comparece ao\nPosto de Saúde para consulta de rotina. Antecedentes: hipertensão, diabetes, osteoartrose de\njoelhos, obesidade, glaucoma e retinopatia diabética. Traz exames com hemograma, perfil\nglicêmico e lipídico, função renal e tireoidiana, todos normais. Filha refere que no último ano o\npaciente tem necessitado de ajuda para manejo das medicações e atividades fora do domicílio.\n\nPouco sai de casa e não demonstra mais interesse em sua vida cotidiana. Qual a provável causa\nda dificuldade em atividades do dia a dia e a\nabordagem inicial?","options":{"A":"Déficit cognitivo ? aplicar Mini-Exame do Estado Mental e iniciar tratamento de demência.","B":"Perda funcional multifatorial ? aplicar escala de Lawton e Katz e iniciar manejo de\ncomorbidades.","C":"Transtorno depressivo ? aplicar Escala de Depressão Geriátrica para diagnóstico e iniciar\ntratamento.","D":"Perda funcional secundária a senescência ? aplicar Avaliação Geriátrica Ampla e orientar sobre\no quadro."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234060","number":"234060","sourceNumber":"234060","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Menino de 4 anos é trazido ao Ambulatório de Pediatria encaminhado pela escola para\navaliação em relação ao desenvolvimento. A família observa alterações desde 18 meses de idade,\ncomo linguagem muito pobre, não atender quando chamado e dificuldades na socialização. O\npediatra levanta a possibilidade de Transtorno do Espectro Autístico. O que o pediatra levantou na\nanamnese que caracteriza essa condição?","options":{"A":"Funcionamento intelectual geral abaixo da média, que se originou durante o período de\ndesenvolvimento e está associado a prejuízo no comportamento adaptativo.","B":"Desenvolvimento anormal ou alterado, manifestado antes de 3 anos de idade, com perturbação\ncaracterística do funcionamento em cada um dos três domínios seguintes: interações sociais,\ncomunicação, comportamento focalizado e repetitivo.","C":"É prevalente no sexo feminino, diagnosticado entre 5 e 30 meses de vida e apresenta marcado\ndéficit no desenvolvimento, com\ndesaceleração do crescimento craniano, retardo intelectual grave,\nalterações de marcha e forte associação com quadros convulsivos.","D":"Agitação psicomotora, prejuízos no desenvolvimento da fala, com aquisição mais lenta e\npresença de trocas, omissões e distorções fonêmicas, retardo na aquisição de automatismos\ntardios, com desenvolvimento da noção temporoespacial mais lento. Não se observa prejuízo\nmarcado na teoria da mente nem nas dificuldades relacionais."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234062","number":"234062","sourceNumber":"234062","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de 6 anos de idade, sexo feminino, é levada pela mãe ao pediatra para\navaliação de comportamento estranho que vem\napresentando há alguns dias. Previamente hígida,\nna escola foi chamado atenção que a criança estava desatenta nas aulas. Mãe começou a\nperceber que a criança estava apresentando crises abruptas que duravam em média de 15\nsegundos, várias vezes ao dia onde ela apresentava olhar fixo, era chamada e não respondia,\ndeixava objetos que estavam na mão cair do chão, apresentando comprometimento da consciência\ncom interrupção da atividade que estava fazendo no momento. Tem história familiar de convulsão.\nO EEG mostrou descargas de espícula, onda lenta de projeção difusa, bilateral que não se\nfragmentam e se acentuam durante a hiperventilação da criança. Diante do quadro clínico exposto,\nqual o possível diagnóstico da criança?","options":{"A":"Epilepsia de Panayiotopoulos.","B":"Epilepsia ausência na infância.","C":"Epilepsia mioclônica da infância.","D":"Epilepsia com pontas centrotemporais."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199789","number":"199789","sourceNumber":"199789","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um jovem de 23 anos foi trazido pelo SAMU a um hospital de referência em trauma,\nvítima de acidente com moto apresentando\ntraumatismo cranioencefálico grave. Após a avaliação\ninicial, foram descartadas outras lesões, sendo sedado e colocado em ventilação mecânica. Ele é\ncasado, e no momento da internação, a esposa declarou que ele era um potencial doador. Após 48\nhoras na Unidade de Terapia Intensiva (UTI), evoluiu com ausência de reflexos de tronco cerebral.\nEm referência ao processo de doação de órgãos nesse caso, como a equipe médica assistente\ndeve proceder?","options":{"A":"Garantir que os médicos responsáveis pelo diagnóstico de morte encefálica façam parte da\nequipe de retirada de órgãos.","B":"Iniciar o processo de avaliação de morte encefálica imediatamente sem necessariamente\nconsultar a esposa ou outro familiar.","C":"Garantir a assinatura do termo de consentimento livre e esclarecido de autorização de doação\nde órgãos por um dos pais em conjunto com a\nesposa.","D":"Informar à família que eles podem solicitar um médico de confiança para que o mesmo\nacompanhe a avaliação da morte encefálica."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199802","number":"199802","sourceNumber":"199802","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente feminina, 38 anos, procura atendimento médico na centro de saúde com\nqueixa de cefaleia quase todos os dias.\nSegundo a paciente, desde os 20 anos ela tem episódios\nde cefaleia holocraniana, de caráter pulsátil, com fotofobia e fonofobia, impedindo de fazer\natividades rotineiras. Ela relata que inicialmente as dores melhoravam com analgésicos, e\naconteciam raramente. Porém, nos últimos anos, observou que as crises estão mais duradouras e\nocorrendo de 2 a 3 vezes por semana. Nega vômitos nos episódios, assim como sintomas\npremonitórios ou desencadeantes. Relata episódios prévios de cálculo renal e asma. Faz uso de\nanticoncepcional oral. Pressão Arterial 140 x 80 mmHg, pulso: 80. Exames físico e neurológico sem\nalterações. Qual a melhor opção terapêutica para a paciente acima?","options":{"A":"Topiramato.","B":"Propranolol.","C":"Candesartana.","D":"Carbonato de Lítio."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199810","number":"199810","sourceNumber":"199810","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino, 52 anos, procurou atendimento médico em emergência devido a\nepisódio de fraqueza em hemicorpo direito e dificuldade na fala iniciada há 2 horas. Nega\ncomorbidades prévias, exceto HAS. Faz uso regular de anlodipino 5 mg e AAS 100 mg. Ao exame\nPA = 180 x 100 mmHg; pulso = 96 batimentos; saturação de oxigênio = 96% em ar ambiente. Tem\nNIH de 15 à custa de hemiparesia à direita, disartria e afasia motora, sem alteração de nível de\nconsciência. Com 2 horas e 30 minutos de início do quadro, tem os seguintes exames laboratoriais\nnormais (hemograma, ureia, creatinina, TAP e TTPA) e a TC de crânio evidencia hematoma\nputaminal de 15 cm³ à direita. LEGENDA: PA = Pressão Arterial; HAS = Hipertensão Arterial\nSistêmica; NIH = National Institute of Health Stroke Scale; TAP = Tempo de Atividade de\nProtrombina; TTPA = Tempo de Tromboplastina Parcial Ativado; TC = Tomografia\nComputadorizada. Qual a melhor conduta para esse paciente?","options":{"A":"Fator VIIa recombinado.","B":"Dexametasona 10 mg endovenoso.","C":"Transfusão de concentrado de plaquetas.","D":"Anti-hipertensivo com alvo de PA < 140 mmHg."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199721","number":"199721","sourceNumber":"199721","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 72 anos procura assistência ambulatorial com queixa de alteração de\nmarcha e duas quedas da própria altura há um\nmês. Relata antecedentes de ?pressão alta,\nreumatismo e tontura?. Está fazendo uso contínuo de: losartana, hidroclorotiazida, carbonato de\ncálcio e cinarizina. No exame físico neurológico, evidenciou-se rigidez simétrica em cotovelos,\npunhos, joelhos e tornozelos, assim como em tronco. Ausência de tremor. Marcha com passos\ncurtos e arrastados, sem a participação dos movimentos dos braços. Considerando a principal\nhipótese diagnóstica, qual a conduta mais adequada neste momento?","options":{"A":"Suspender cinarizina.","B":"Prescrever rasagilina.","C":"Prescrever pramipexol.","D":"Prescrever levodopa + benserazida."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199677","number":"199677","sourceNumber":"199677","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na emergência, os pais relatam que sua filha de três anos de idade apresentou\nmovimentos anormais nos membros superiores e\ninferiores, há cerca de 30 minutos, no domicílio.\nQue sinais sugerem ao médico assistente que se trata de um evento convulsivo?","options":{"A":"Movimentos tônicos, clônicos ou tônico-clônicos na ausência de perda da consciência.","B":"Presença de deficit neurológicos focais na ausência de alteração prolongada da consciência.","C":"Perda de consciência e perda do controle esfinctérico na ausência de reflexos de autoproteção.","D":"Presença de aura, movimentos tônicos, clônicos ou tônico-clônicos na ausência de movimentos\nanômalos dos olhos."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199704","number":"199704","sourceNumber":"199704","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 82 anos, viúva, analfabeta, teve visita domiciliar requisitada pelos filhos.\nA\npaciente morava no interior do estado e, há 2 semanas, foi trazida para a casa de um dos filhos, na\ncapital. Está agitada à noite, fica rezando alto, não consegue dormir, apresenta dificuldade de\ndeambular e \"vem perdendo urina\". Os filhos dizem que ela não era assim, mas não sabem\nprecisar o início dos sintomas. Não faz uso de medicamentos, nega tosse e dispneia. Atividades de\nvida diária básicas comprometidas. Escala de depressão geriátrica = 3, mini exame do estado\nmental = 15 pontos. Nega alucinações visuais ou auditivas. Ao exame físico, apresenta marcha de\nbase alargada e passos curtos. Movimentação passiva das articulações sem resistência.\n\nConsiderando a hipótese diagnóstica mais provável, qual a conduta inicial mais adequada para esta\npaciente?","options":{"A":"Solicitar ressonância magnética de sistema nervoso.","B":"Prescrever antidepressivo e reavaliar com quinze dias.","C":"Simplificar o ambiente para evitar excesso de estímulo à paciente.","D":"Tranquilizar a paciente e familiares e orientar em relação a evolução do quadro demencial."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199731","number":"199731","sourceNumber":"199731","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Ao investigar queixa vertiginosa de paciente, um médico de família executa manobra\nsemiológica que sugere posição anormal de otólitos no ouvido interno direito. Ele decide então\nexecutar a manobra de Epley para reposicionamento dos otólitos. Qual número representa a figura\ncom a última posição que o paciente deve assumir antes de ser levado à ortostase?","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":["question_bank/media/medcurso/medcurso-neurologia-neu-unico/199731.png"],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-172998","number":"172998","sourceNumber":"172998","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 78 anos é levado à emergência com fraqueza em hemicorpo direito e\ndificuldade para falar há três horas. Na avaliação inicial, pressão arterial = 160 x 100 mmHg,\npulso\n\n= 90 batimentos por minuto, glicemia capilar = 100 mg/dl e saturação de oxigênio = 97%. Ao\nexame, encontra-se vígil, com afasia de Broca,\ndesvio do olhar conjugado para a esquerda e\nhemiparesia direita (escala NIHSS = 21). Antecedente patológico de hipertensão arterial sistêmica,\nsem diabetes. Na tomografia de crânio realizada com 3 horas e 30 minutos do início dos sintomas\nnão se observa nenhuma alteração aguda. Sem alterações em exames laboratoriais. Legenda:\nNIHSS = National Institutes of Health Stroke Scale. Qual a melhor terapêutica a ser tomada nesse\nmomento?","options":{"A":"Warfarin 5 mg.","B":"Clopidogrel 75 mg.","C":"Ácido acetilsalicílico 300 mg.","D":"Ativador de plasminogênio tecidual 0,9 mg/kg."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-172969","number":"172969","sourceNumber":"172969","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente, 75 anos, sexo masculino, comparece para avaliação clínica com queixa de\ntremor em membros superiores. Relata que o\nsintoma teria iniciado há cerca de 1 ano. Percebe o\ntremor principalmente em repouso e em membro superior direito. Ao exame neurológico: presença\nde tremor de repouso, assimétrico com predomínio em membro superior direito associado a\ndiscreta rigidez e bradicinesia também em membro superior direito. Durante a avaliação da marcha,\nnão se observa instabilidade postural. Qual a conduta medicamentosa mais adequada, nesse\nmomento?","options":{"A":"Primidona para controle do tremor.","B":"Propranolol para controle do tremor.","C":"Levodopa para controle da bradicinesia.","D":"Anticolinérgico para controle da bradicinesia."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-172966","number":"172966","sourceNumber":"172966","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No ambulatório, os pais de uma criança de 3 anos de idade trazem preocupações do\ntipo \"nosso filho parece não estar se desenvolvendo bem\". Após dois encontros com a família e a\ncriança, o médico formula a hipótese de Transtorno do Espectro Autista. Da extensa avaliação\nrealizada, qual dos critérios diagnósticos abaixo são coerentes com a suspeita clínica do médico?","options":{"A":"Alterações de pensamento, com prejuízo na associação de ideias, bloqueio de pensamento.","B":"Criança irritadiça, com choro fácil, sono agitado e despertares noturnos, agitação psicomotora.","C":"Disfasia grave, alterações relacionais (dificuldades de imitação e interesses específicos) e\ndificuldades de expressão afetiva.","D":"Ausência de atividade imaginativa, como representação de papéis de adultos, personagens de\nfantasia ou animais; falta de interesse em histórias sobre acontecimentos imaginários."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-172982","number":"172982","sourceNumber":"172982","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de cinco anos de idade chega à emergência com alteração do estado mental,\nem coma. Quais os passos fundamentais da\navaliação neurológica para essa criança, além do nível\nde consciência e do padrão respiratório?","options":{"A":"Avaliação das pupilas, motilidade ocular extrínseca e postura motora.","B":"Avaliação da resposta motora, movimentos oculares e resposta verbal.","C":"Avaliação da abertura ocular, da resposta à dor e de déficits neurológicos.","D":"Avaliação da hipertensão intracraniana, da herniação cerebral e movimentos oculares."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-172976","number":"172976","sourceNumber":"172976","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, trabalha como empregada doméstica, queixa-se\nde dor lombar crônica, de caráter mecânico,\nsem sinais de alarme, com exacerbação há 02\nsemanas. Relaciona a dor ao trabalho. Ao exame físico, apresenta sobrepeso, dor difusa à\npalpação da região lombar paravertebral sem irradiação. Ausência de pontos-gatilhos. Restante do\nexame físico sem alterações. Além da perda de peso, o que deve constar no plano terapêutico da\npaciente?","options":{"A":"Prescrição de analgésico opioides.","B":"Realização de exercício físico aeróbico e alongamento.","C":"Prescrição de antidepressivos por pelo menos 6 meses.","D":"Afastamento das atividades laborais até melhora do quadro álgico."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-172986","number":"172986","sourceNumber":"172986","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Durante visita domiciliar, você avalia um senhor de 53 anos com câncer de pulmão em\nestágio avançado, sem proposta terapêutica curativa. O paciente está consciente, apresenta\ndiscurso lúcido e está orientado quanto ao prognóstico de sua doença, sem demonstrar\ndificuldades de aceitação. Queixa-se de dispneia progressiva na última semana que chega a\nocorrer em repouso e, atualmente, pontua 7 na escala de Borg modificada (0 sem dispneia; 10\ndispneia máxima). Ao exame físico, sentado, apresenta-se emagrecido, PA = 110 x 80 mmHg,\npulso = 96 bpm, frequência respiratória = 24 irpm, SpO2 93% e expansão torácica diminuída\nsimetricamente, com dor à inspiração profunda. Ausculta respiratória apresenta diminuição do\nmurmúrio vesicular em bases. Vem em uso de codeína de 8/8h. Qual a próxima conduta para\nmelhorar o controle da dispneia do paciente?","options":{"A":"Iniciar oxigenioterapia domiciliar sob cateter.","B":"Associar Clonazepam por via oral de 12/12h.","C":"Substituir Codeína por Morfina por via oral de 4/4h.","D":"Administrar broncodilatadores por nebulização de 4/4h."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-150861","number":"150861","sourceNumber":"150861","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 36 anos, alcoolista crônico e com história prévia de epilepsia, foi trazido à\nemergência com quadro de convulsão tônico-clônica generalizada. Esposa relata que o paciente\ningeriu bebida alcoólica durante 3 dias seguidos e nesse período não tomou seus medicamentos.\nSegundo o socorrista que o trouxe, o paciente apresenta crises seguidas há 15 minutos. Na\nemergência, foi medicado com diazepam 10 mg, intravenoso, porém a crise não cedeu, mesmo\ncom a repetição da dose. Qual a próxima conduta a ser tomada?","options":{"A":"Fenitoína 20 mg/kg, intravenoso, na sala de emergência.","B":"Midazolam 0,2 mg/kg, intravenoso, na sala de emergência.","C":"Propofol 2 mg/kg, intravenoso, na unidade de terapia intensiva.","D":"Fenobarbital 10 mg/kg, intravenoso, na unidade de terapia intensiva."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-150871","number":"150871","sourceNumber":"150871","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 77 anos, hipertensa e diabética, admitida na emergência com história de\nhemiparesia à esquerda e disartria iniciadas há 1 hora. Realizou tomografia computadorizada de\ncrânio sem contraste que foi normal. Exames laboratoriais colhidos na emergência não revelaram\nalterações. No momento, a paciente está monitorizada e apresenta PA: 180 x 100 mmHg; FC: 78\nbpm; saturação arterial de O2 de 93%; glicemia capilar de 300 mg/dl; e temperatura axilar de 38ºC.\nA conduta inicial mais apropriada nesse momento é:","options":{"A":"Indicar trombólise com alteplase por intravenoso.","B":"Controlar glicemia com insulina regular por via subcutânea.","C":"Aumentar oferta de oxigênio com máscara de Venturi a 50%.","D":"Reduzir níveis pressóricos com nitroprussiato de sódio intravenoso."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-150844","number":"150844","sourceNumber":"150844","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A mãe de uma criança fala de seus temores em relação ao desenvolvimento de seu\nmenino de 18 meses de idade: ele atende pouco, quando chamado pelo nome; tem dificuldade de\nolhar as pessoas diretamente nos olhos; seus gestos são escassos; não aponta para as coisas que\ndeseja; tem pouco interesse por outras crianças e por brincadeiras de faz de conta. Qual a principal\nhipótese diagnóstica que merece ser pesquisada?","options":{"A":"Síndrome de Rett.","B":"Transtorno do espectro autista.","C":"Transtorno reativo de vinculação.","D":"TDAH com predomínio da defict de atenção."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-150881","number":"150881","sourceNumber":"150881","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 47 anos, hipertenso, tabagista, habitante de zona rural, procurou atendimento\nna Unidade Básica de Saúde angustiado, pois há 24\nhoras acordou com dor periauricular a\nesquerda e desde então vem observando desconforto com ruídos altos no ouvido esquerdo.\n\nObservou a face esquerda \"caída\" e apresenta dificuldade de se alimentar, com queda de alimentos\ne saliva pelo canto esquerdo da boca. Ao exame\nfísico, apresenta fraqueza acentuada na face\nesquerda, incluindo a região frontal e apagamento do sulco nasolabial esquerdo (vide figura). PA\n150 x 90 mmHg. Otoscopia e demais itens do exame físico estavam normais. (VER IMAGEM) Qual\na conduta adequada?","options":{"A":"Solicitar avaliação e acompanhamento fisioterápico com seguimento regular na Unidade Básica\nde Saúde, até melhora do quadro.","B":"Referenciar o paciente para avaliação tomográfica no ?Centro de referência, para o diagnóstico\ne tratamento do AVC? mais próximo.","C":"Agendar retorno em 24h para reavaliação, orientação de manter níveis pressóricos e\nencaminhar ao serviço de neurologia de modo eletivo.","D":"Encaminhar o paciente à Unidade de Pronto-Atendimento para avaliações do estado neurológico\na cada hora, e definição de conduta após 24h."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-127006","number":"127006","sourceNumber":"127006","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, é admitida no setor de emergência com hemiplegia\nesquerda de início súbito há 2 horas. Paciente tem, como única comorbidade, fibrilação atrial há\ntrês anos, sem necessidade de controle de frequência e em uso de rivaroxabana 15 mg por dia.\n\nDurante avaliação do médico plantonista, ela está orientada e descreve sua história em detalhes. O\nexame físico evidencia Pressão Arterial (PA) de 200 x 110 mmHg em repetidas aferições nos 4\nmembros, além de confirmar a hemiplegia. Não foram detectadas outras alterações relevantes.\n\nConsiderando o manuseio clínico ideal para este caso, além de manter a paciente em\nmonitorização, como deve ser feito o tratamento da PA nesse momento?","options":{"A":"Não iniciar medicamentos.","B":"Iniciar captopril por via oral.","C":"Iniciar nifedipino por via sublingual.","D":"Iniciar nitroprussiato por via endovenosa."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-126932","number":"126932","sourceNumber":"126932","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente feminina, 30 anos, há dois meses vem notando dificuldade de abrir os\nolhos, principalmente ao final do dia, que se associou à dificuldade de mastigação com\nregurgitação nasal frequente e, mais recentemente, disfagia e fadiga. Ao exame, nota-se fraqueza\nmuscular em cintura pélvica, mais pronunciada à esquerda, e reflexos preservados. Na\ninvestigação, a pesquisa de anticorpos antirreceptores de acetilcolina foi negativa. Nesse\ncontexto, qual exame laboratorial poderia confirmar o diagnóstico mais provável?","options":{"A":"Pesquisa de anticorpo anti-Jo-1.","B":"Pesquisa de anticorpo anti-GM1.","C":"Pesquisa de anticorpo anti-MuSK.","D":"Pesquisa de anticorpo anti-GQ1b."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-126934","number":"126934","sourceNumber":"126934","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um médico foi chamado por familiares para uma visita domiciliar a uma paciente de 59\nanos com câncer de mama e metástases\nósseas, sofrendo com dores intensas relacionadas\nao quadro que cediam parcialmente ao uso de paracetamol ou codeína. Há 3 dias, foi\nprescrito pelo médico oncologista morfina por via oral a cada 6 horas. Por receio de a paciente\ndesenvolver drogadição, os familiares vinham dando o medicamento somente se necessário e\npediram avaliação deste médico que fez a visita. Qual deve ser a conduta do médico visando uma\nboa prática de cuidados paliativos?","options":{"A":"Insistir em uso da morfina conforme prescrição.","B":"Preferir metadona via oral em intervalos regulares à morfina.","C":"Substituir a morfina por dipirona via oral em intervalos regulares.","D":"Preferir anti-inflamatórios não esteroides mantendo morfina sob demanda."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-102153","number":"102153","sourceNumber":"102153","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 67 anos, diabético e sedentário, apresentava quadro insidioso e\nprogressivo de perda de memória há 5 anos\ne, nos últimos 6 meses, vinha evoluindo com\ndificuldade de realizar suas atividades diárias, por prejuízo na linguagem (fluência e articulação\ndas\npalavras) e na realização de cálculos simples. O exame neurológico não demonstrava deficit\nmotores focais, rigidez de nuca ou alterações de pares cranianos. Quais seriam os achados\nhistopatológicos no sistema nervoso central mais característicos do diagnóstico mais provável\ndesse paciente?","options":{"A":"Placas amiloides.","B":"Corpúsculos de Pick.","C":"Corpúsculos de Lewy.","D":"Degeneração espongiforme."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-102165","number":"102165","sourceNumber":"102165","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino, 70 anos, procura-o no consultório com queixas de esquecimentos\nfrequentes (como o número da sua conta\nbancária ou de sua identidade) e distanciamento familiar\npor apatia e déficit de concentração, nas últimas duas semanas. Ao examiná-lo você identifica um\nindivíduo orientado no tempo e no espaço, capaz de recordar seus eventos do dia á dia e fatos\nrelevantes de sua história. Ao ser apresentada uma lista com cinco palavras simples, este é capaz\nde repeti-las imediatamente, após um minuto de concentração e após 10 minutos durante os quais\nele realizou outras tarefas. Esse contexto deve deixá-lo atento para qual diagnóstico mais\nprovável?","options":{"A":"Transtorno depressivo menor.","B":"Demência degenerativa de Pick.","C":"Tumor do lobo temporal medial.","D":"Infarto da artéria cerebral anterior."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-102124","number":"102124","sourceNumber":"102124","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Médico atende paciente de 74 anos. A idosa refere perda involuntária de urina há 6\nmeses e isso vem causando incômodo e, por\nessa razão, prefere ficar em casa. Relata ter caído à\nnoite, há uma semana, resultando em um hematoma no joelho direito. Qual a conduta imediata\nmais adequada para essa paciente?","options":{"A":"Avaliar: depressão, mecanismo de incontinência urinária e risco de queda.","B":"Deverá: prescrever alendronato de sódio 70 mg, semanal, e carbonato de cálcio 1,5 gramas\ndiária.","C":"Iniciar: terapia de reposição hormonal, após realização de mamografia e de ultrassonografia\ntransvaginal.","D":"Prescrever: carbonato de cálcio 1,5 gramas diária, fazer avaliação ambiental e solicitar\ndensitometria\n\nóssea."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-81294","number":"81294","sourceNumber":"81294","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 55 anos, hipertensa, usando irregularmente losartana. A família relata\ndespertar durante a noite há cerca de 30 minutos com cefaleia inédita, intensa, associada a\nnáuseas, vômitos e provavelmente um episódio de convulsão tônico-clônica. Ao exame,\n\nencontra-se com pressão arterial de 180 x 130 mmHg, frequência cardíaca de 55 bpm, comatosa,\nGlasgow de 6 e aparente hemiplegia à\nesquerda. Após entubação orotraqueal, foi encaminhada\npara tomografia de crânio, cujo resultado encontra-se abaixo. (VER IMAGEM). Qual a conduta mais\napropriada na sequência da assistência adequada para essa paciente?","options":{"A":"Realizar trombólise.","B":"Realizar derivação ventricular externa.","C":"Realizar punção de líquido cefalorraquidiano.","D":"Realizar tratamento agressivo da hipertensão com nitratos."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":["question_bank/media/medcurso/medcurso-neurologia-neu-unico/81294.png"],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-81280","number":"81280","sourceNumber":"81280","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 47 anos é atendida em pronto-socorro por cefaleia. Relata dor em aperto em\ntodo o lado esquerdo da cabeça, associada a náuseas, fotofobia e fraqueza em braço e perna\ndireitos, quadro esse precedido por escotomas visuais cintilantes. Diz que apresenta cefaleia desde\nos 17 anos, com frequência de 2 por mês, principalmente no período perimenstrual. Usa alprazolam\npara síndrome do pânico. Ao exame físico, apresenta-se ansiosa e hiperventilando. O exame dos\nnervos cranianos e da sensibilidade estão normais. Há diminuição da força em membros do dimídio\ndireito (conseguindo vencer resistência leve) com dimídio esquerdo normal, hiperreflexia tendinosa\nprofunda em dimídio direito e reflexos normais em dimídio esquerdo. Com esse quadro, a paciente\nfoi medicada com analgésico e submetida à realização de ressonância nuclear magnética de\nencéfalo, que se mostrou normal. Após 2 horas, estava assintomática e o exame físico normal.\n\nQual o diagnóstico mais provável da paciente?","options":{"A":"Enxaqueca.","B":"Epilepsia focal.","C":"Transtorno conversivo somatoforme.","D":"Acidente isquêmico transitório aterosclerótico."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-65700","number":"65700","sourceNumber":"65700","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 75 anos, masculino, é levado por sua filha para consulta com seu médico\nde família. Esta se queixa de que seu pai\nrecentemente saiu de casa e foi encontrado em outro\nbairro, pois não lembrava seu endereço e nem como chegar em casa. A filha relata que este é o\nterceiro episódio nos últimos 3 meses. Nega outras alterações neurológicas. O paciente não faz uso\nde medicamentos. Nega patologias prévias. Diante desta situação, qual a conduta inicial mais\nadequada?","options":{"A":"Encaminhar o paciente para o geriatra.","B":"Realizar o mini exame do estado mental.","C":"Solicitar uma tomografia computadorizada de crânio.","D":"Encaminhar o paciente para uma unidade de pronto atendimento.","E":"Recomendar observação clínica, pois as alterações são decorrentes do processo natural de\nenvelhecimento."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-141575","number":"141575","sourceNumber":"141575","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Qual a causa mais comum de hemorragia intracraniana?","options":{"A":"Angiopatia amiloide.","B":"Hemorragia subaracnoidea.","C":"Transformação hemorrágica de AVE prévio.","D":"Hemorragia intraparenquimatosa hipertensiva ."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-141576","number":"141576","sourceNumber":"141576","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Quais das opções abaixo apresenta contraindicações ao uso da terapia trombolítica no\nAVE isquêmico?","options":{"A":"Melhora rápida dos sintomas; glicemia < 50 ou > 400; PA persistentemente > 185/110 a despeito\ndo tratamento.","B":"AVE isquêmico prévio; glicemia < 80 ou > 400; PA persistentemente > 160/110 a despeito do\ntratamento.","C":"Melhora rápida dos sintomas; uso crônico de aspirina; PA persistentemente > 185/110 a\ndespeito do tratamento.","D":"Melhora rápida dos sintomas; glicemia < 80 ou > 400; PA persistentemente > 185/110 a despeito\ndo tratamento."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-141592","number":"141592","sourceNumber":"141592","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre a Síndrome de Guillain-Barré evidenciada na infecção por Zika vírus, qual das\nseguintes alternativas é a mais correta?","options":{"A":"Acomete primeiramente o diafragma.","B":"Inicialmente unilateral, principalmente a esquerda.","C":"O estudo de liquor não está indicado nas primeira semanas.","D":"Paralisia motora arrefléxica de evolução rápida, ascendente e simétrica."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-141586","number":"141586","sourceNumber":"141586","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Você atende na UPA um lactente de dois anos, sexo feminino, com história de febre há\n24 horas, e que antes de sair de casa,\napresentou crise convulsiva tônico-clônica generalizada e de\ncurta duração (aproximadamente cinco minutos). Após examinar o lactente, você observa que o\nmesmo se encontra febril e com exame neurológico normal e a única alteração ao exame físico é a\nfebre. Não existem dados dignos de nota na história pregressa e atual do lactente. Com base\nnessas informações, qual a conduta mais indicada ?","options":{"A":"Realizar anticonvulsivante e iniciar imediatamente antimicrobiano venoso.","B":"Solicitar EEG e parecer do neuropediatra, administrar antitérmico.","C":"Realizar punção lombar e iniciar anticonvulsivante e antitérmico.","D":"Baixar a febre e avaliar a etiologia infecciosa e orientar a família."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-141587","number":"141587","sourceNumber":"141587","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação aos critérios de diagnóstico de demência, assinale a resposta CORRETA:","options":{"A":"Perda de memória é necessariamente a primeira alteração que o paciente apresenta ou a família\npercebe.","B":"As alterações do comportamento fazem parte dos critérios diagnósticos e ocorrem somente em\nfase avançada da doença.","C":"Perda de memória há de ser necessariamente um elemento presente para se estabelecer o\ndiagnóstico de demência.","D":"Alterações parkinsonianas fazem parte dos critérios diagnósticos da síndrome demencial."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-349746","number":"349746","sourceNumber":"349746","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 24 anos, sem comorbidades conhecidas, sob estresse emocional intenso\nrelacionado ao preparo para uma prova de um\nconcurso público, procurou o pronto atendimento\ncom queixa principal de que o lado direito do rosto não se mexia havia 1 dia. Ao exame físico,\napresentava paralisia em hemiface superior e inferior à direita, paralisia da pálpebra superior\ndireita\nque levava à dificuldade de fechar o olho e piscar, além de desvio da rima labial para o lado\nesquerdo. As pupilas estavam isocóricas e fotorreagentes, e a força estava preservada (grau V) em\nmembros superiores e inferiores bilaterais. De acordo com o caso clínico apresentado, qual é a\nprincipal hipótese diagnóstica?","options":{"A":"Paralisia de Todd.","B":"Acidente vascular encefálico.","C":"Síndrome de Claude Bernard-Horner.","D":"Paralisia de Bell.","E":"Hemorragia subaracnoidea."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-349733","number":"349733","sourceNumber":"349733","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"É considerada uma manifestação clínica comum da Doença de Parkinson a","options":{"A":"estabilidade postural.","B":"hipercinesia.","C":"fasciculação.","D":"hipermobilidade.","E":"rigidez em roda dentada."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-365657","number":"365657","sourceNumber":"365657","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Segundo Velasco (2022), a primeira referência histórica feita à rabdomiólise consta na\nBíblia, em que há a descrição de uma doença aguda e grave que acometeu os israelitas após\ningerirem aves que provavelmente alimentavam-se com sementes de cicuta. (VELASCO, I.T.\nMedicina de emergência: abordagem prática. 16. ed. Barueri [SP]: Manole, 2022, com adaptações).\nAssim como o uso de sementes, algumas medicações podem induzir rabdomiólise, como, por\nexemplo, o uso de","options":{"A":"sinvastatina com ciprofibrato.","B":"furosemida com espironolactona.","C":"propranolol com anlodipino.","D":"AAS com clopidogrel."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-365655","number":"365655","sourceNumber":"365655","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente foi levado pela esposa ao pronto-socorro com quadro de intoxicação por\nbenzodiazepínico. Qual é a indicação medicamentosa para esse caso?","options":{"A":"Adrenalina","B":"Atropina","C":"Flumazenil","D":"Naloxone"},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-365644","number":"365644","sourceNumber":"365644","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma criança de 18 meses de vida é levada ao pronto-socorro após um episódio de\nconvulsão tônico-clônica generalizada com duração de aproximadamente dois minutos, seguida de\nsonolência. Chegou ao hospital cerca de uma hora após o evento agudo, dormindo em todo o\ntrajeto. No atendimento inicial, verificou-se Tax = 40 °C, ela foi medicada com antitérmico e\ndeixada\nem repouso. Ao acordar, realizou exame neurológico com resultado normal. Ao exame físico,\napresenta hiperemia de orofaringe e lesões aftosas em palato. Em relação ao diagnóstico dessa\npaciente, assinale a alternativa correta.","options":{"A":"Trata-se de uma convulsão febril complexa, uma vez que houve sonolência após o episódio\nagudo.","B":"Trata-se de um caso de meningite, visto que há presença de um quadro infeccioso nas vias\naéreas.","C":"Deve-se internar a paciente para investigação da convulsão por meio de exames\ncomplementares.","D":"Trata-se de uma convulsão febril simples, que habitualmente não ocorre mais de uma vez em 24\nhoras, mas pode se repetir em quadros infecciosos posteriores."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-349693","number":"349693","sourceNumber":"349693","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de onze anos que apresenta crises convulsivas, que iniciaram há seis meses,\nsem déficits até o momento. Existe história\nfamiliar de uma síndrome epiléptica generalizada,\ncaracterizada por movimentos súbitos e involuntários de um grupo ou de um único músculo. Qual\ndas seguintes alternativas apresenta o diagnóstico mais provável para esse paciente?","options":{"A":"Síndrome de Dravet.","B":"Síndrome de Lennox-Gastaut.","C":"Síndrome do lobo temporal.","D":"Síndrome de West.","E":"Epilepsia mioclônica juvenil."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-349720","number":"349720","sourceNumber":"349720","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A avaliação que considera múltiplas dimensões é denominada avaliação\nmultidimensional a qual estrutura e organiza\no cuidado às pessoas idosas. Em outras palavras, a\navaliação multidimensional permite a compreensão ampliada e integral do estado de saúde de um\ndeterminado indivíduo, buscando identificar e intervir nas áreas mais comprometidas e que podem\nafetar sua funcionalidade: doenças agudas ou crônicas, agravos como quedas e outros acidentes,\nquestões relativas a processos psicológicos/subjetivos ou, ainda, situações sociais, econômicas e\nculturais que podem trazer limitações para o exercício da autonomia e/ou independência. Tal\navaliação permite o direcionamento de intervenções oportunas, que respondam às reais\nnecessidades de cada pessoa, o que possibilita prognósticos mais favoráveis em sua trajetória de\nenvelhecimento. Referente à avaliação multidimensional do idoso, assinale a alternativa correta.","options":{"A":"A dimensão psicossocial enfatiza critérios sociais e étnico-raciais, sendo a questão da saúde\nmental exclusiva da dimensão clínica.","B":"A avaliação da capacidade de realizar atividades diárias (instrumentais e básicas) faz parte da\ndimensão clínica.","C":"A avaliação psicossocial busca avaliar a funcionalidade do indivíduo diante da sua comunidade.","D":"A dimensão clínica concentra-se em avaliar sinais de doenças passadas, ficando a cargo da\ndimensão funcional avaliar doenças atuais.","E":"A dimensão funcional considera de forma objetiva se uma pessoa é capaz ou não de realizar\natividades da vida diária."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-322153","number":"322153","sourceNumber":"322153","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre a dor, assinale a alternativa correta.","options":{"A":"Os nociceptores são responsáveis pela transdução.","B":"A dor neuropática tem como principal característica a melhora à noite e nos meses mais frios.","C":"A migrânea é um exemplo clássico de dor somática superficial.","D":"A pregabalina atua nos receptores opioides do sistema nervoso central, principalmente µ1 e µ2.","E":"A presença de injúria tecidual é essencial para a explicação do fenômeno doloroso."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-322156","number":"322156","sourceNumber":"322156","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre a neuromielite óptica, assinale a alternativa correta.","options":{"A":"É uma forma de apresentação da Esclerose Múltipla.","B":"Pleocitose é bastante específica para o diagnóstico.","C":"Também é conhecida como síndrome de Devic.","D":"A presença de paralisia espástica é frequente.","E":"A tomografia de crânio apresenta alterações específicas."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-322212","number":"322212","sourceNumber":"322212","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os pais levam Miguel de 8 anos para consulta, pois a diretora da escola disse que ele é\ndesatento e tem dificuldade em aprender. A conduta inicial do médico da Atenção Primária nessa\nsituação deve ser","options":{"A":"encaminhar Miguel ao neuropediatra.","B":"avaliar os ambientes familiar e escolar da criança.","C":"solicitar avaliação adicional tanto auditiva como visual.","D":"realizar testes de aptidão intelectual.","E":"solicitar eletroencefalograma."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-337591","number":"337591","sourceNumber":"337591","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. Para pacientes que sofreram AVEi como Roberto,\nestá indicado o uso de estatinas de alta potência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-305292","number":"305292","sourceNumber":"305292","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre a escala NIHSS (National Institutes of Health Stroke Scale), é CORRETO afirmar\nque:","options":{"A":"A presença de ataxia pode ser avaliada pela manobra index-nariz ou calcanhar-joelho.","B":"A presença de mutismo causado por barreira mecânica (cânula orotraqueal, por exemplo)\ncaracteriza pontuação máxima nos itens disartria e linguagem.","C":"A pontuação, nos casos em que o paciente não possui um membro (amputação), deve ser\nmáxima na avaliação de força desse membro.","D":"A heminegliência deve ser pontuada no paciente não contatuante.","E":"A escala de NIHSS é mais importante nos casos de AVC hemorrágico."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-305294","number":"305294","sourceNumber":"305294","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um homem de 34 anos é levado ao serviço médico de urgência com história de\nferimento por projétil de arma de fogo na\ncoxa direita. Ele relata que estava fazendo limpeza e\nmanutenção da sua arma, quando houve o disparo acidental. Relata que, durante alguns segundos,\nnão sentiu nenhuma dor e logo chamou por ajuda. No momento da avaliação, refere dor intensa.\n\nSobre a fisiopatologia da dor, assinale a alternativa correta.","options":{"A":"A temperatura elevada do projétil leva à inativação dos nociceptores de pele e estruturas mais\nprofundas.","B":"A dor experimentada pelo paciente pode ser caracterizada como visceral verdadeira.","C":"A retirada do projétil é essencial para uma adequada analgesia.","D":"Dentro do componente sensitivo-discriminativo, a modulação tem papel importante nesse caso e\ntem função evolutiva de proporcionar um comportamento de luta e/ou fuga.","E":"A ausência de dor nos primeiros segundos após o acidente pode estar relacionada com o\nhistórico do paciente (por exemplo: ex-militar)."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-298879","number":"298879","sourceNumber":"298879","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 16 anos de idade, com oito horas de evolução, compareceu à\nemergência por apresentar vertigem,\ndiplopia e surdez. Além disso, demonstrou deficits motores.\nAo exame físico, verificaram-se SatO2 = 96% em ar ambiente, FC = 92 bpm regular e PA = 180\nmmHg x 100 mmHg. Tomografia de crânio e angiotomografia não evidenciaram malformação\nvascular nem sangramento. Aos 15 anos, a paciente teve trombose venosa profunda. Em relação a\nesse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. Os sintomas da\npaciente sugerem acometimento carotídeo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-298881","number":"298881","sourceNumber":"298881","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 16 anos de idade, com oito horas de evolução, compareceu à\nemergência por apresentar vertigem,\ndiplopia e surdez. Além disso, demonstrou deficits motores.\nAo exame físico, verificaram-se SatO2 = 96% em ar ambiente, FC = 92 bpm regular e PA = 180\nmmHg x 100 mmHg. Tomografia de crânio e angiotomografia não evidenciaram malformação\nvascular nem sangramento. Aos 15 anos, a paciente teve trombose venosa profunda. Em relação a\nesse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. O uso de\ntrombolítico é contraindicado para essa paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-305316","number":"305316","sourceNumber":"305316","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 12 anos queixa-se de cefaleia recorrente, moderada, com intervalos\nvariáveis, de dias, semanas ou meses. A dor é\nbilateral e pulsátil e, por vezes, acompanhada de\nirritabilidade, anorexia e náusea. Antes do quadro de dor, vê \"bolinhas coloridas\" e sente\nformigamento na língua. Sobre o diagnóstico mais provável, assinale a alternativa CORRETA.","options":{"A":"O paciente está na faixa etária de menor incidência em pediatria.","B":"Podem fazer parte dos sintomas que precedem a dor: formigamento em hemicorpo, disfasia e\ndisartria.","C":"O paciente apresenta o tipo de quadro mais comum, que é o de dor precedida por sintomas\nvisuais e sensitivos.","D":"Para o diagnóstico adequado, é necessário investigar com tomografia de crânio e exames\nlaboratoriais.","E":"Casos familiares semelhantes são a exceção."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-298897","number":"298897","sourceNumber":"298897","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 2 anos e 3 meses de idade foi levado ao ambulatório de pediatria pela\nmãe, pois ela está preocupada com um \"caroço\" no pescoço do filho, que ela notou há cinco\nmeses. Relatou que o filho é bastante ativo, que se alimenta bem, sempre ganhou peso, mas fala\npouco e palavras difíceis de compreender. Ademais, há muito tempo apareceram alguns\nmachucados no couro cabeludo dele, que o menino coça bastante e tem algumas crostas. Ao\nexame físico, constataram-se altura = 90 cm (escore z 0), peso = 12,300 kg (escore z entre 0 e -2),\nFC = 120 bpm, FR = 26 irpm e SatO2 = 97% em AA. No couro cabeludo, há várias lesões com\ncrostas melicéricas e presença de linfonodo retroauricular medindo 1,5 cm, móvel, fibroelástico,\nindolor à palpação. Observaram-se oroscopia, dentes em bom estado, sem lesões, sem frênulo\nlingual, otoscopia, com membrana timpânica translúcida, sem abaulamentos ou retrações e\nausculta cardíaca, BNF, RR, 2t, sem sopro. Verificaram-se, ainda, ausculta pulmonar, MVUD, sem\nRA, abdome, RHA+, depressível, sem megalias, indolor à palpação e genitália com testículos em\nbolsa escrotal e fimose. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Investigação de autismo deve ser realizada em crianças que não falam aos\n18 meses de idade e, entre os métodos de avaliação, está a escala M-CHAT.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-261238","number":"261238","sourceNumber":"261238","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dL e creatinina = 1,4 mg/dL. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Ácido valproico é contraindicado para esse paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-261239","number":"261239","sourceNumber":"261239","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dL e creatinina = 1,4 mg/dL. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Epidemiologicamente trata-se de craniofaringioma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-261241","number":"261241","sourceNumber":"261241","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dL e creatinina = 1,4 mg/dL. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. A radioterapia nos tumores malignos do SNC pode ser\nutilizada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274377","number":"274377","sourceNumber":"274377","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A respeito das demências secundárias, ou aquelas que têm lesão estrutural do sistema\nnervoso central, assinale a alternativa CORRETA.","options":{"A":"A infecção pelo HIV é a causa mais comum.","B":"A demência vascular é uma forma secundária comum, e a forma de doença de Binswanger é\nrelacionada à arteriosclerose das artérias da substância branca.","C":"A Hipertensão Intracraniana com Pressão Normal (HICPN) é uma causa importante e, para seu\ndiagnóstico, observa-se a tríade de alteração da marcha com características apráxicas,\ndeterioração cognitiva e incontinência urinária. O teste de punções repetidas de líquido\ncefalorraquidiano normalmente é negativo para melhora do quadro.","D":"A doença priônica é uma causa comum em idosos.","E":"As síndromes neuroinfecciosas devem ter diagnóstico por líquido cefalorraquidiano, sendo os\nexames de neuroimagem descartados nesse caso."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274389","number":"274389","sourceNumber":"274389","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 14 anos é levado ao hospital por quadro ao qual os pais chamaram de\nconvulsão. Segundo a anamnese, o paciente apresentou movimentos generalizados, versão ocular\ne perda de consciência, com duração de 1 minuto, seguida por sonolência. Enquanto examina o\npaciente, o pediatra faz a anamnese mais detalhada. Das seguintes características, qual deve fazer\no pediatra pensar em um diagnóstico alternativo?","options":{"A":"Perda do controle esfinctérico.","B":"Movimentos tônicos.","C":"Cianose central.","D":"Confusão mental após cessar o episódio.","E":"Localização de estímulo doloroso durante o episódio."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-262556","number":"262556","sourceNumber":"262556","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Certo paciente de 58 anos de idade, vítima de AVC isquêmico troncoencefálico,\nencontra-se entubado há duas semanas e sem uso de\nsedação há 10 dias. Após avaliação\nneurológica, houve orientação para dar início a protocolo de morte encefálica (ME). Ao exame\nneurológico, ele encontra-se comatoso (Glasgow 3T), com tetraplegia; pupilas médio-fixas sem\nresposta fotomotora; reflexos corneopalpebral e de tosse ausentes; afebril; PA = 110 mmHg x 80\nmmHg; TAX retal = 35,5 °C; AC = RC2T com BNF; AP = MVF sem RA; e SatO2 = 100%. Exames\nlaboratoriais sem alterações. Acerca desse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. No protocolo de ME, serão realizados dois exames\nclínicos, sendo um dos médicos responsável pelo exame clínico necessariamente da especialidade\nneurologia, neuropediatria ou neurocirurgia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-262558","number":"262558","sourceNumber":"262558","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Certo paciente de 58 anos de idade, vítima de AVC isquêmico troncoencefálico,\nencontra-se entubado há duas semanas e sem uso de\nsedação há 10 dias. Após avaliação\nneurológica, houve orientação para dar início a protocolo de morte encefálica (ME). Ao exame\nneurológico, ele encontra-se comatoso (Glasgow 3T), com tetraplegia; pupilas médio-fixas sem\nresposta fotomotora; reflexos corneopalpebral e de tosse ausentes; afebril; PA = 110 mmHg x 80\nmmHg; TAX retal = 35,5 °C; AC = RC2T com BNF; AP = MVF sem RA; e SatO2 = 100%. Exames\nlaboratoriais sem alterações. Acerca desse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. No protocolo de ME, está indicada a manutenção da\npressão arterial sistólica maior ou igual a 100 mmHg ou da pressão arterial média maior ou igual a\n65 mmHg.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-262559","number":"262559","sourceNumber":"262559","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Certo paciente de 58 anos de idade, vítima de AVC isquêmico troncoencefálico,\nencontra-se entubado há duas semanas e sem uso de\nsedação há 10 dias. Após avaliação\nneurológica, houve orientação para dar início a protocolo de morte encefálica (ME). Ao exame\nneurológico, ele encontra-se comatoso (Glasgow 3T), com tetraplegia; pupilas médio-fixas sem\nresposta fotomotora; reflexos corneopalpebral e de tosse ausentes; afebril; PA = 110 mmHg x 80\nmmHg; TAX retal = 35,5 °C; AC = RC2T com BNF; AP = MVF sem RA; e SatO2 = 100%. Exames\nlaboratoriais sem alterações. Acerca desse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. O protocolo de ME somente poderá ser aberto após\naquecimento do paciente com TAX retal > 36 °C.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-262560","number":"262560","sourceNumber":"262560","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Certo paciente de 58 anos de idade, vítima de AVC isquêmico troncoencefálico,\nencontra-se entubado há duas semanas e sem uso\nde sedação há 10 dias. Após avaliação\nneurológica, houve orientação para dar início a protocolo de morte encefálica (ME). Ao exame\nneurológico, ele encontra-se comatoso (Glasgow 3T), com tetraplegia; pupilas médio-fixas sem\nresposta fotomotora; reflexos corneopalpebral e de tosse ausentes; afebril; PA = 110 mmHg x 80\nmmHg; TAX retal = 35,5 °C; AC = RC2T com BNF; AP = MVF sem RA; e SatO2 = 100%. Exames\nlaboratoriais sem alterações. Acerca desse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. A presença de atitude de descerebração ou decorticação\ninvalida o diagnóstico de ME.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-262562","number":"262562","sourceNumber":"262562","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Certo paciente de 58 anos de idade, vítima de AVC isquêmico troncoencefálico,\nencontra-se entubado há duas semanas e sem uso de\nsedação há 10 dias. Após avaliação\nneurológica, houve orientação para dar início a protocolo de morte encefálica (ME). Ao exame\nneurológico, ele encontra-se comatoso (Glasgow 3T), com tetraplegia; pupilas médio-fixas sem\nresposta fotomotora; reflexos corneopalpebral e de tosse ausentes; afebril; PA = 110 mmHg x 80\nmmHg; TAX retal = 35,5 °C; AC = RC2T com BNF; AP = MVF sem RA; e SatO2 = 100%. Exames\nlaboratoriais sem alterações. Acerca desse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. O teste de apneia é considerado inconclusivo quando a\nPaCO2 final for menor que 56 mmHg na ausência de movimentos respiratórios.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-262563","number":"262563","sourceNumber":"262563","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Certo paciente de 58 anos de idade, vítima de AVC isquêmico troncoencefálico,\nencontra-se entubado há duas semanas e sem uso de\nsedação há 10 dias. Após avaliação\nneurológica, houve orientação para dar início a protocolo de morte encefálica (ME). Ao exame\nneurológico, ele encontra-se comatoso (Glasgow 3T), com tetraplegia; pupilas médio-fixas sem\nresposta fotomotora; reflexos corneopalpebral e de tosse ausentes; afebril; PA = 110 mmHg x 80\nmmHg; TAX retal = 35,5 °C; AC = RC2T com BNF; AP = MVF sem RA; e SatO2 = 100%. Exames\nlaboratoriais sem alterações. Acerca desse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. A presença de hipernatremia grave refratária ao\ntratamento sempre inviabiliza a determinação de ME.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-284353","number":"284353","sourceNumber":"284353","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. A evolução da esclerose múltipla depende da faixa etária do paciente, sendo que a mais\ncomum é a forma progressiva, na qual os sintomas e sinais neurológicos se intensificam sem\nremissão, com acometimento neurológico motor.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274427","number":"274427","sourceNumber":"274427","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher de 83 anos, hipertensa, sem outras comorbidades, comparece à unidade\nde saúde para verificação da pressão arterial\nde rotina. Está assintomática no momento. Utiliza\napenas um comprimido de losartana 50 mg. No momento do exame, sua pressão arterial é de\n90x60 mmHg. A paciente refere que eventualmente tem sentido tonturas, porém nega outras\nmanifestações. Tendo em vista suas características e o histórico apresentado, qual dos seguintes\nagravos representa um maior risco à saúde dessa paciente nesse contexto?","options":{"A":"Câncer de mama.","B":"Infecção urinária.","C":"Queda.","D":"Demência vascular.","E":"Depressão."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-255703","number":"255703","sourceNumber":"255703","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 70 anos de idade perdeu-se em casa e não sabia onde ficava a\nprópria cozinha. Há uma semana, deixou o fogão\naceso quando foi ao mercado. A filha dela, então,\nlevou-a ao geriatra, que realizou exame do estado mental, o qual demonstrou alterações\nprincipalmente nos testes de memória, bem como no teste do relógio. Realizaram-se exames de\nsangue e tomografia de crânio. Nenhum laboratorial estava alterado. Seu médico prescreveu\nmemantina e donepezila. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. A memantina é um inibidor da acetilcolinesterase, útil para demência\navançada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-239294","number":"239294","sourceNumber":"239294","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. A paciente deve ser\nencaminhada para trombólise química com tenecteplase em até duas horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-239295","number":"239295","sourceNumber":"239295","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Uma pressão arterial maior ou\nigual a 230 mmHg x 90 mmHg não contraindica para realização de trombólise com maior segurança\ndessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-239296","number":"239296","sourceNumber":"239296","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Para pacientes com sequelas\npsicóticas importantes de acidente vascular cerebral, o uso de antipsicóticos típicos, como a\nquetiapina, é boa alternativa medicamentosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-239297","number":"239297","sourceNumber":"239297","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Essa paciente possui alto risco\nde síndrome de imobilidade, que ocorre em pacientes acamados por períodos prolongados, sendo\na hipercalcemia e reabsorção óssea achados frequentes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-255730","number":"255730","sourceNumber":"255730","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 12 anos de idade vai ao pediatra em razão de sua mãe querer fazer\numa avaliação anual com exames. Dessa vez, o\npediatra solicitou hormônio do crescimento sérico\n(GH), que veio uma vez e meio aumentado, acima dos valores de referência. O paciente faz\natividades físicas regulares e não apresenta alteração estrutural. Esse paciente tinha suspeita de\nsíndrome de West, mas esta foi descartada. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. ACTH é a primeira linha no tratamento e corticoide é\nutilizado para pacientes não respondedores.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-239354","number":"239354","sourceNumber":"239354","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 12 anos de idade vai a consulta agendada em Unidade de Saúde da\nFamília acompanhada pela mãe. A familiar demonstra preocupações quanto ao desenvolvimento\nda filha, alegando ser esta uma das mais baixas entre as respectivas colegas e que ainda não teve\na primeira menstruação, a despeito de estar notando desenvolvimento das mamas há 10 meses,\nobservando-se a presença de broto mamário ao exame físico. Refere-se, também, que a mãe está\nreceosa de a filha vir a ser diagnosticada com síndrome dos ovários policísticos (SOP), tendo base\ntal preocupação em leitura de informações da internet em correlação com o fato de a filha\napresentar acne facial, de ainda nunca ter menstruado e de possuir histórico familiar de primeiro\ngrau de obesidade e diabetes mellitus tipo 2. Faz uso de metilfenidato 10 mg/dia por diagnóstico\nprévio de transtorno de deficit de atenção e hiperatividade, demonstrando manter atenção apenas\npara atividades do próprio interesse, sem, no entanto, apresentar histórico de baixo desempenho\nescolar ou prejuízo da vida social. Em avaliação ponderoestatural, verifica-se IMC de 21 kg/m²,\nconsiderado adequado para a idade da paciente. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. O diagnóstico de transtorno de deficit de\natenção e hiperatividade é clínico, levando-se em conta a exigência de que deve haver clara\nevidência de que os sintomas interferem na qualidade do funcionamento social, acadêmico ou\nocupacional ou reduzem-na, tornando questionável o diagnóstico prévio da paciente do caso\nclínico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-196649","number":"196649","sourceNumber":"196649","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Determinada paciente de 18 anos de idade, com histórico de mais de 10 manchas\ncastanhas em tronco, pelve e membros desde a\ninfância, efélides nas regiões axilares e inguinais e\npresença de vários (> 5) nódulos de Lisch em cada íris, apresenta quadro de perda de controle\nesfincteriano há um mês. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\nquanto ao provável diagnóstico dessa paciente, julgue o item a seguir. Trata-se de uma doença\nhereditária, congênita, autossômica dominante, mas com grande proporção de mutações\nesporádicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-196605","number":"196605","sourceNumber":"196605","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Determinada paciente de 18 anos de idade, com histórico de mais de 10 manchas\ncastanhas em tronco, pelve e membros desde a\ninfância, efélides nas regiões axilares e inguinais e\npresença de vários (> 5) nódulos de Lisch em cada íris, apresenta quadro de perda de controle\nesfincteriano há um mês. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\nquanto ao provável diagnóstico dessa paciente, julgue o item a seguir. Considerando-se a\nprevalência de depressão, ansiedade, psicose e desejo suicida, além de problemas de expressão e\nsocialização, alguns autores recomendam a psicoterapia como parte integrante do tratamento de\nsuporte aos pacientes com tal doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-214504","number":"214504","sourceNumber":"214504","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 58 anos de idade, negro, chega à emergência levado pela esposa por\nestar sonolento, queixando-se de cefaleia de\nforte intensidade, fadiga e episódios de náuseas\nseguidos de vômito de forte intensidade. A esposa relata que os sintomas se iniciaram no dia e vêm\napresentando piora progressiva. Nega queixas de dor torácica e (ou) precordial, e também nega\nqueixas álgicas abdominais. O paciente refere quadro prévio de hipertensão arterial e está em uso\nde anti-hipertensivos. A esposa relata que ele se queixa de episódios frequentes de cefaleia no\núltimo ano e que tem estado \"muito estranho\" nos últimos três meses, apresentando ações\ninconsequentes até nas pequenas decisões diárias. Ao exame, apresenta-se em estado geral\nregular, acordado e conversando, porém com aspecto sonolento, ventilando espontaneamente em\nar ambiente. Apresenta ausculta cardíaca e pulmonar sem particularidades. Sinais vitais: FC = 58\nbpm; FR = 22 irpm; PA = 190 mmHg x 125 mmHg; SatO? = 97%; e temperatura axilar (Tax) = 38,6\n\n°C. Acerca desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. Os episódios de vômito de forte intensidade, apresentados pelo paciente, podem ser\nclassificados como \"vômito em jato\", um sinal de hipertensão intracraniana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-214351","number":"214351","sourceNumber":"214351","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 58 anos de idade, negro, chega à emergência levado pela esposa por\nestar sonolento, queixando-se de cefaleia de\nforte intensidade, fadiga e episódios de náuseas\nseguidos de vômito de forte intensidade. A esposa relata que os sintomas se iniciaram no dia e vêm\napresentando piora progressiva. Nega queixas de dor torácica e (ou) precordial, e também nega\nqueixas álgicas abdominais. O paciente refere quadro prévio de hipertensão arterial e está em uso\nde anti-hipertensivos. A esposa relata que ele se queixa de episódios frequentes de cefaleia no\núltimo ano e que tem estado \"muito estranho\" nos últimos três meses, apresentando ações\ninconsequentes até nas pequenas decisões diárias. Ao exame, apresenta-se em estado geral\nregular, acordado e conversando, porém com aspecto sonolento, ventilando espontaneamente em\nar ambiente. Apresenta ausculta cardíaca e pulmonar sem particularidades. Sinais vitais: FC = 58\nbpm; FR = 22 irpm; PA = 190 mmHg x 125 mmHg; SatO? = 97%; e temperatura axilar (Tax) = 38,6\n\n°C. Acerca desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. Se as alterações comportamentais forem de caráter insidioso, de aumento progressivo e\nacompanhadas de sintomas físicos, devem- se excluir alterações de origem orgânica antes de se\npensar em um diagnóstico psiquiátrico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-214361","number":"214361","sourceNumber":"214361","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 58 anos de idade, negro, chega à emergência levado pela esposa por\nestar sonolento, queixando-se de cefaleia de\nforte intensidade, fadiga e episódios de náuseas\nseguidos de vômito de forte intensidade. A esposa relata que os sintomas se iniciaram no dia e vêm\napresentando piora progressiva. Nega queixas de dor torácica e (ou) precordial, e também nega\nqueixas álgicas abdominais. O paciente refere quadro prévio de hipertensão arterial e está em uso\nde anti-hipertensivos. A esposa relata que ele se queixa de episódios frequentes de cefaleia no\núltimo ano e que tem estado \"muito estranho\" nos últimos três meses, apresentando ações\ninconsequentes até nas pequenas decisões diárias. Ao exame, apresenta-se em estado geral\nregular, acordado e conversando, porém com aspecto sonolento, ventilando espontaneamente em\nar ambiente. Apresenta ausculta cardíaca e pulmonar sem particularidades. Sinais vitais: FC = 58\nbpm; FR = 22 irpm; PA = 190 mmHg x 125 mmHg; SatO? = 97%; e temperatura axilar (Tax) = 38,6\n\n°C. Acerca desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. Considerando a possibilidade diagnóstica de uma neoplasia intracraniana, os tumores\nmalignos mais prevalentes são os gliomas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-196686","number":"196686","sourceNumber":"196686","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\nglicazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A respeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir. Com\nessa paciente, deve-se abordar a prevenção de quedas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-196697","number":"196697","sourceNumber":"196697","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\nglicazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A respeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir.\n\nIdosos apresentam maior risco de quedas quando são do sexo feminino e usam polifarmácia,\nrevelam histórico de quedas anteriores e idade\nacima de 80 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-177686","number":"177686","sourceNumber":"177686","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O escopo da abordagem comunitária do médico de família foge do completo isolamento\ndo consultório médico, envolvendo, também, ações\nde modificação do ambiente da comunidade,\nvisando à promoção da qualidade de vida e à prevenção de doenças da população. Considerando\nesse contexto, Rafael, residente do 2º ano de medicina de família e comunidade, procurou auxílio\nda prefeitura para implantar um programa de incentivo à atividade física, na área geográfica de sua\natuação, o qual incluía a revitalização da praça próxima ao posto, a implantação de academia ao ar\nlivre e a pista de caminhada. Três vezes por semana, Rafael investia a 1ª hora de sua manhã\norganizando um grupo de caminhada e orientando a população na prática de exercícios físicos.\n\nConsiderando a situação hipotética apresentada e os conhecimentos médicos correlatos, julgue o\nitem a seguir. É indispensável a realização de exame médico antes dos idosos iniciarem o\nprograma de caminhada, mesmo que em baixa intensidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-154346","number":"154346","sourceNumber":"154346","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente D.G.F., 40 anos de idade, sexo feminino, vítima de acidente automobilístico\ncom três óbitos no local, foi admitida em\nUTI após a estabilização do quadro de traumatismo\ncranioencefálico grave. Ela segue estável hemodinamicamente sem uso de drogas vasoativas, com\nnecessidade de suporte ventilatório e sem sedação há 48 horas. O laboratório clínico não aponta\ndistúrbios hidroeletrolíticos e metabólicos, a gasometria arterial está dentro dos parâmetros de\nnormalidade, temperatura central é de 36,5°C e PAM = 80 mmHg. Com base nesse caso clínico e\nconsiderando os preceitos legais e as Diretrizes para Avaliação e Validação do Potencial Doador de\nÓrgãos em Morte Encefálica, assinale a alternativa correta.","options":{"A":"A paciente é classificável como elegível para a doação, pelos critérios da Organização Mundial\nde Saúde. Essa denominação descreve aquele\npaciente sob suspeita de morte encefálica, que\napresenta lesão encefálica, grave ou catastrófica de origem conhecida, e Glasgow 3 na escala de\ncoma, e que necessita de ventilação mecânica.","B":"A sepse sempre contraindica a doação de órgãos. O potencial doador que se apresente séptico,\nmesmo com estabilidade hemodinâmica e (ou) redução progressiva de vasopressores, não pode\nser doador, pelo fato da transmissibilidade da infecção.","C":"A morte encefálica pode ser definida objetivamente por coma aperceptivo com ausência de\natividade motora espinal, ausência de\nreflexos de tronco e apneia. Destaca-se que o paciente deve\napresentar lesão encefálica de causa conhecida, irreversível e capaz de provocar o quadro,\nausência de evidências de intoxicação exógena ou de uso de drogas depressoras do Sistema\nNervoso Central (SNC), ausência de distúrbios hidroeletrolíticos ou acidobásicos graves,\ntemperatura corporal central idealmente \"maior ou igual\" 35°C e PAM \"maior ou igual\" 60 mmHg.","D":"O diagnóstico de morte encefálica deve ser confirmado por, no mínimo, dois médicos, sendo um\ndeles especialista em neurologia ou neurocirurgia. O intervalo mínimo entre as duas avaliações\nclínicas necessárias para a caracterização da morte encefálica varia conforme a faixa etária, sendo\npara adultos o intervalo de seis horas. Não exclui o diagnóstico de morte encefálica a ocorrência de\nreflexos flexores ou extensores, podendo considerar-se o uso de bloqueadores neuromusculares\n\nna prevenção destes durante a estimulação.","E":"A causa do coma aperceptivo e arreflexo pode ser imputada aos medicamentos depressores do\nSNC, mesmo quando utilizados em doses terapêuticas usuais. Um dos exemplos a ser ponderado\né o uso do fenobarbital enteral e da dexmedetomidina."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-154321","number":"154321","sourceNumber":"154321","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em uma unidade básica de saúde, chega pela primeira vez, um paciente de 2 anos de\nidade com história de crises convulsivas e de alterações no desenvolvimento visual, auditivo e,\nprincipalmente, motor. Ao interrogar a mãe do paciente, constata-se que essas alterações tiveram\ninício logo após o nascimento dele, de modo que a hipótese principal levantada é a de paralisia\ncerebral infantil. A respeito do diagnóstico apresentado, a etiologia mais frequente desse quadro\né:","options":{"A":"Hemorragia cerebral.","B":"Malformações congênitas.","C":"Anoxia cerebral.","D":"Placenta prévia.","E":"Kernicterus."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289447","number":"289447","sourceNumber":"289447","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 4 anos de idade, sexo masculino, foi levado à consulta pelos pais, os quais\nrelatam que, há cerca de um mês, observaram mudança no comportamento do filho, que vem\napresentando quedas frequentes, tremores e mudanças progressivas no jeito de andar e de falar,\ndeambulando como se estivesse embriagado, optando por brincadeiras que pode realizar sentado,\ne apresentando dificuldade ao levantar-se do chão. Ao exame clínico, apresentou marcha de base\nalargada, disdiadococinesia, incapacidade de realizar prova dedo-nariz e disartria. Foi solicitada\nressonância magnética de encéfalo, que evidenciou massa heterogênea captante de contraste em\nlinha média do cerebelo, invadindo o quarto ventrículo, compatível com meduloblastoma. Acerca\ndesse caso clínico, e considerando os conhecimentos médicos a respeito dos tumores de sistema\nnervoso central na infância, julgue o item a seguir. Estaria claro o envolvimento do cerebelo entre\nas estruturas comprimidas pelo tumor, mesmo na ausência do exame de imagem.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289450","number":"289450","sourceNumber":"289450","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 4 anos de idade, sexo masculino, foi levado à consulta pelos pais, os quais\nrelatam que, há cerca de um mês, observaram mudança no comportamento do filho, que vem\napresentando quedas frequentes, tremores e mudanças progressivas no jeito de andar e de falar,\ndeambulando como se estivesse embriagado, optando por brincadeiras que pode realizar sentado,\ne apresentando dificuldade ao levantar-se do chão. Ao exame clínico, apresentou marcha de base\nalargada, disdiadococinesia, incapacidade de realizar prova dedo-nariz e disartria. Foi solicitada\nressonância magnética de encéfalo, que evidenciou massa heterogênea captante de contraste em\nlinha média do cerebelo, invadindo o quarto ventrículo, compatível com meduloblastoma. Acerca\ndesse caso clínico, e considerando os conhecimentos médicos a respeito dos tumores de sistema\nnervoso central na infância, julgue o item a seguir. Esse caso é exceção, já que a grande maioria\ndos tumores de sistema nervoso em crianças é de localização extraencefálica, sendo de\nlocalização medular em mais de 50% dos casos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289452","number":"289452","sourceNumber":"289452","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 4 anos de idade, sexo masculino, foi levado à consulta pelos pais, os quais\nrelatam que, há cerca de um mês, observaram mudança no comportamento do filho, que vem\napresentando quedas frequentes, tremores e mudanças progressivas no jeito de andar e de falar,\ndeambulando como se estivesse embriagado, optando por brincadeiras que pode realizar sentado,\ne apresentando dificuldade ao levantar-se do chão. Ao exame clínico, apresentou marcha de base\nalargada, disdiadococinesia, incapacidade de realizar prova dedo-nariz e disartria. Foi solicitada\nressonância magnética de encéfalo, que evidenciou massa heterogênea captante de contraste em\nlinha média do cerebelo, invadindo o quarto ventrículo, compatível com meduloblastoma. Acerca\ndesse caso clínico, e considerando os conhecimentos médicos a respeito dos tumores de sistema\nnervoso central na infância, julgue o item a seguir. O meduloblastoma é o tumor cerebral mais\nassociado à neurofibromatose tipo 1, de forma que se deve pesquisar, nesse paciente, manchas\ncafé com leite e efélides axilares, entre outros achados típicos dessa facomatose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289454","number":"289454","sourceNumber":"289454","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 4 anos de idade, sexo masculino, foi levado à consulta pelos pais, os quais\nrelatam que, há cerca de um mês, observaram mudança no comportamento do filho, que vem\napresentando quedas frequentes, tremores e mudanças progressivas no jeito de andar e de falar,\ndeambulando como se estivesse embriagado, optando por brincadeiras que pode realizar sentado,\ne apresentando dificuldade ao levantar-se do chão. Ao exame clínico, apresentou marcha de base\nalargada, disdiadococinesia, incapacidade de realizar prova dedo-nariz e disartria. Foi solicitada\nressonância magnética de encéfalo, que evidenciou massa heterogênea captante de contraste em\nlinha média do cerebelo, invadindo o quarto ventrículo, compatível com meduloblastoma. Acerca\ndesse caso clínico, e considerando os conhecimentos médicos a respeito dos tumores de sistema\nnervoso central na infância, julgue o item a seguir. O meduloblastoma é o tumor de fossa posterior\nmais frequente na infância.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289456","number":"289456","sourceNumber":"289456","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 4 anos de idade, sexo masculino, foi levado à consulta pelos pais, os quais\nrelatam que, há cerca de um mês, observaram mudança no comportamento do filho, que vem\napresentando quedas frequentes, tremores e mudanças progressivas no jeito de andar e de falar,\ndeambulando como se estivesse embriagado, optando por brincadeiras que pode realizar sentado,\ne apresentando dificuldade ao levantar-se do chão. Ao exame clínico, apresentou marcha de base\nalargada, disdiadococinesia, incapacidade de realizar prova dedo-nariz e disartria. Foi solicitada\nressonância magnética de encéfalo, que evidenciou massa heterogênea captante de contraste em\nlinha média do cerebelo, invadindo o quarto ventrículo, compatível com meduloblastoma. Acerca\ndesse caso clínico, e considerando os conhecimentos médicos a respeito dos tumores de sistema\nnervoso central na infância, julgue o item a seguir. É pouco provável que o paciente em questão\nevolua com necessidade de derivação ventrículo-peritoneal e de hipertensão intracraniana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289458","number":"289458","sourceNumber":"289458","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considere que um paciente do sexo feminino, 9 anos de idade, previamente hígida,\nchega à emergência levada pela mãe. Chega\nsonolenta, febril e hipotônica, e a mãe relata que a\nfilha apresentou episódio de convulsão, tonico-clônica, os movimentos iniciaram em membro\nsuperior esquerdo e, após alguns minutos, a crise generalizou-se. Teve duração de pelo menos 5\nminutos. No caminho entre a casa e a emergência, a criança apresentou novo episódio, idêntico ao\nprimeiro. Ao exame físico, apresenta torpor, Tax = 39 ºC, oroscopia e otoscopia normais, sem\nsinais de meningismo ou esforço ventilatório. Em relação ao caso clínico apresentado, julgue o item\na seguir. Trata-se de caso clássico de convulsão febril, e os pais devem ser tranquilizados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-152168","number":"152168","sourceNumber":"152168","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 39 anos de idade, negra, hipertensa prévia, pré-eclâmpsia\nna última gestação, apresenta crise\nconvulsiva tônico-clônica e é atendida na emergência do\nhospital. Não possui histórico prévio de convulsão. Ao chegar, estava em estado pós-ictal, Glasgow\n9, pressão arterial de 160 x 100 mmHg; FC = 105 bpm; FR = 16 irpm. O médico plantonista do local\nexamina a paciente, que está com pupilas fixas, anisocóricas, hemiparética à direita e\napresentando afasia motora. Solicita uma tomografia de crânio que evidencia hemorragia\nintraparenquimatosa em região frontotemporal esquerda, com hipótese diagnóstica de trombose\nvenosa de seio sagital. A paciente é internada no serviço de neurologia do hospital e sua prescrição\ncontém manitol, fenitoína, dexametasona e anticoagulante. Após dois dias de internação, paciente\nevolui com nova crise convulsiva e Glasgow 7. Com base nesse caso clínico, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. O sinal de delta vazio é um dos\nachados radiológicos esperados na trombose venosa de seio sagital.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-152172","number":"152172","sourceNumber":"152172","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 39 anos de idade, negra, hipertensa prévia, pré-eclâmpsia\nna última gestação, apresenta crise\nconvulsiva tônico-clônica e é atendida na emergência do\nhospital. Não possui histórico prévio de convulsão. Ao chegar, estava em estado pós-ictal, Glasgow\n9, pressão arterial de 160 x 100 mmHg; FC = 105 bpm; FR = 16 irpm. O médico plantonista do local\nexamina a paciente, que está com pupilas fixas, anisocóricas, hemiparética à direita e\napresentando afasia motora. Solicita uma tomografia de crânio que evidencia hemorragia\nintraparenquimatosa em região frontotemporal esquerda, com hipótese diagnóstica de trombose\nvenosa de seio sagital. A paciente é internada no serviço de neurologia do hospital e sua prescrição\ncontém manitol, fenitoína, dexametasona e anticoagulante. Após dois dias de internação, paciente\nevolui com nova crise convulsiva e Glasgow 7. Com base nesse caso clínico, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. A anticoagulação melhora o\nprognóstico dessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289462","number":"289462","sourceNumber":"289462","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considere que um paciente do sexo feminino, 9 anos de idade, previamente hígida,\nchega à emergência levada pela mãe. Chega\nsonolenta, febril e hipotônica, e a mãe relata que a\nfilha apresentou episódio de convulsão, tonico-clônica, os movimentos iniciaram em membro\nsuperior esquerdo e, após alguns minutos, a crise generalizou-se. Teve duração de pelo menos 5\nminutos. No caminho entre a casa e a emergência, a criança apresentou novo episódio, idêntico ao\nprimeiro. Ao exame físico, apresenta torpor, Tax = 39 ºC, oroscopia e otoscopia normais, sem\nsinais de meningismo ou esforço ventilatório. Em relação ao caso clínico apresentado, julgue o item\na seguir. A punção lombar torna-se desnecessária em razão da ausência de sinais meníngeos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-152166","number":"152166","sourceNumber":"152166","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 39 anos de idade, negra, hipertensa prévia, pré-eclâmpsia\nna última gestação, apresenta crise\nconvulsiva tônico-clônica e é atendida na emergência do\nhospital. Não possui histórico prévio de convulsão. Ao chegar, estava em estado pós-ictal, Glasgow\n9, pressão arterial de 160 x 100 mmHg; FC = 105 bpm; FR = 16 irpm. O médico plantonista do local\nexamina a paciente, que está com pupilas fixas, anisocóricas, hemiparética à direita e\napresentando afasia motora. Solicita uma tomografia de crânio que evidencia hemorragia\nintraparenquimatosa em região frontotemporal esquerda, com hipótese diagnóstica de trombose\nvenosa de seio sagital. A paciente é internada no serviço de neurologia do hospital e sua prescrição\ncontém manitol, fenitoína, dexametasona e anticoagulante. Após dois dias de internação, paciente\nevolui com nova crise convulsiva e Glasgow 7. Com base nesse caso clínico, e considerando os\nconhecimentos médicos a ele relacionados, julgue o item a seguir. Diparesia facial periférica,\ndisfagia, disartria e disfonia são esperadas se ocorrer acomentimento da musculatura bulbar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289464","number":"289464","sourceNumber":"289464","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considere que um paciente do sexo feminino, 9 anos de idade, previamente hígida,\nchega à emergência levada pela mãe. Chega\nsonolenta, febril e hipotônica, e a mãe relata que a\nfilha apresentou episódio de convulsão, tonico-clônica, os movimentos iniciaram em membro\nsuperior esquerdo e, após alguns minutos, a crise generalizou-se. Teve duração de pelo menos 5\nminutos. No caminho entre a casa e a emergência, a criança apresentou novo episódio, idêntico ao\nprimeiro. Ao exame físico, apresenta torpor, Tax = 39 ºC, oroscopia e otoscopia normais, sem\nsinais de meningismo ou esforço ventilatório. Em relação ao caso clínico apresentado, julgue o item\na seguir. A manifestação da crise, com reentrância em menos de 24 horas, reforça a hipótese de\nconvulsão febril.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-289466","number":"289466","sourceNumber":"289466","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considere que um paciente do sexo feminino, 9 anos de idade, previamente hígida,\nchega à emergência levada pela mãe. Chega\nsonolenta, febril e hipotônica, e a mãe relata que a\nfilha apresentou episódio de convulsão, tonico-clônica, os movimentos iniciaram em membro\nsuperior esquerdo e, após alguns minutos, a crise generalizou-se. Teve duração de pelo menos 5\nminutos. No caminho entre a casa e a emergência, a criança apresentou novo episódio, idêntico ao\nprimeiro. Ao exame físico, apresenta torpor, Tax = 39 ºC, oroscopia e otoscopia normais, sem\nsinais de meningismo ou esforço ventilatório. Em relação ao caso clínico apresentado, julgue o item\na seguir. A manifestação inicialmente focal torna desnecessária a investigação com exames de\nimagem.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-152080","number":"152080","sourceNumber":"152080","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Lactente de 7 meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: indica-se o uso de\nanticonvulsivantes com o intuito de evitar novas crises.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-152087","number":"152087","sourceNumber":"152087","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Lactente de 7meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: necessita-se de uma\ninvestigação complementar ambulatorial com tomografia computadorizada e eletroencefalograma.","options":{"A":"CERTO","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-152095","number":"152095","sourceNumber":"152095","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Lactente de 7meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: prescreve-se,\nimediatamente, medicamento antitérmico, evitando assim a aparição de outro episódio convulsivo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-135052","number":"135052","sourceNumber":"135052","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Julgue o próximo item, relativo a acidente vascular cerebral. Todo deficit neurológico\nagudo deve ser visto pelo médico como um\npossível acidente vascular isquêmico:","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-134956","number":"134956","sourceNumber":"134956","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Julgue o seguinte item, relativo à epilepsia. Classifica-se o mal epiléptico em estágios\nde acordo com o tempo referente à atuação dos\nmecanismos de homeostasia cerebral. No estágio\nI, a convulsão apresenta duração menor que trinta minutos. Todavia, caso não haja controle nesse\nintervalo de tempo, o estágio II se instala e, após este, ocorre o mal epiléptico refratário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-105547","number":"105547","sourceNumber":"105547","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em diversos ramos da medicina é necessário que se saiba manejar a dor, uma vez que\nela faz parte da grande maioria dos inúmeros quadros clínicos com que o médico se depara,\nindependentemente de sua especialidade. Para isso, é adequado que se diferencie a dor\nclassificada como neuropática daquela dita nociceptiva. Considerando essas informações, assinale\na alternativa que apresenta uma característica da dor neuropática:","options":{"A":"Secundária a dano tissular.","B":"Referida como \"em pressão\".","C":"Geralmente tem irradiação proximal.","D":"Descrita como lancinante, paroxística ou em formigamento.","E":"Sem associação com sinais autonômicos."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-108134","number":"108134","sourceNumber":"108134","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de sessenta e cinco anos de idade foi internado em uma unidade de\nemergência em virtude da apresentação súbita de desvio da comissura labial para a esquerda,\nparesia do membro superior direito e afasia. Após duas horas de internação do paciente, uma\nequipe da neurologia identificou o desaparecimento dos sintomas, entretanto foram encontradas\nmanchas hipocrômicas localizadas difusamente no tronco e nas extremidades, que apresentavam\nbaixa sensibilidade térmica. Com referência ao caso clínico acima apresentado, julgue o seguinte\nitem. O desvio da comissura labial para a esquerda associado à paresia do membro superior direito\né um indicador do diagnóstico de paralisia facial central.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-88659","number":"88659","sourceNumber":"88659","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. Os fumantes correm o risco\n200% maior de sofrer um acidente vascular cerebral que os não fumantes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-88683","number":"88683","sourceNumber":"88683","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca da síndrome de Guillain-Barré, julgue o próximo item. A síndrome de\n\nGuillain-Barré é uma doença paralítica inflamatória aguda causada pela agressão imunomediada do\nsistema nervoso periférico e, na maioria dos casos, é precedida por uma doença infecciosa aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-64720","number":"64720","sourceNumber":"64720","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher, 42 anos de idade, com história prévia de febre reumática, com importante\nestenose da válvula mitral e fibrilação\natrial, foi admitida no setor de Cardiologia para realização de\nvalvotomia mitral por balão. Após a realização deste procedimento, a paciente começou a\napresentar alteração da consciência, vertigem e amaurose, bilateralmente. Neste caso, se for\naventada a possibilidade de um acidente vascular encefálico, assinale a alternativa que apresenta a\nprovável artéria acometida:","options":{"A":"Artéria cerebral média.","B":"Artéria cerebral anterior.","C":"Artéria cerebral posterior.","D":"Porção distal da artéria basilar.","E":"Ramos perfurantes da artéria cerebral média."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352378","number":"352378","sourceNumber":"352378","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nQuanto à avaliação geral do nível de atividade do paciente, é importante mencionar diversas\nferramentas de medição, como as Escalas de\nDuke, as Atividades Instrumentais de Vida Diária,\nbem como escalas específicas no contexto oncológico, a exemplo do Eastern Cooperative\nOncology Group e da Escala de Karnofsky. Além disso, para a classificação adequada destas\núltimas, é relevante considerar exames complementares, como hemograma, avaliação da função\nrenal, dos níveis de transaminases e do coagulograma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352401","number":"352401","sourceNumber":"352401","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 68 anos de idade deu entrada com uma cefaleia de início súbito,\ndescrita como a pior que já experimentou,\nacompanhada de rebaixamento do nível de consciência.\nImediatamente, foi assegurada a via aérea e uma tomografia foi realizada, cuja imagem está\napresentada abaixo. A respeito do quadro clínico apresentado, da imagem acima e de seus temas\ncorrelatos, julgue o item a seguir. Trata-se de quadro clássico de hemorragia subaracnóidea (HSA)\ncom hemoventrínculo e classificação Fischer 5 e Hunt-Hess IV.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352400","number":"352400","sourceNumber":"352400","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 68 anos de idade deu entrada com uma cefaleia de início súbito,\ndescrita como a pior que já experimentou,\nacompanhada de rebaixamento do nível de consciência.\nImediatamente, foi assegurada a via aérea e uma tomografia foi realizada, cuja imagem está\napresentada abaixo. A respeito do quadro clínico apresentado, da imagem acima e de seus temas\ncorrelatos, julgue o item a seguir. A hemorragia vítrea pode ocorrer e é um indicativo de\nprognóstico\ndesfavorável. Portanto, é essencial realizar a fundoscopia em todos os pacientes diagnosticados\ncom HSA.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352399","number":"352399","sourceNumber":"352399","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 68 anos de idade deu entrada com uma cefaleia de início súbito,\ndescrita como a pior que já experimentou,\nacompanhada de rebaixamento do nível de consciência.\nImediatamente, foi assegurada a via aérea e uma tomografia foi realizada, cuja imagem está\napresentada abaixo. A respeito do quadro clínico apresentado, da imagem acima e de seus temas\ncorrelatos, julgue o item a seguir. Em pacientes em tratamento com anticoagulantes, é fundamental\nadministrar a reversão de forma ágil assim que disponível. O idarucizumabe é utilizado para\nreverter a ação da dabigatrana, enquanto o andexanet alfa é indicado para reverter a ação da\napixabana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352392","number":"352392","sourceNumber":"352392","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considerando a imagem acima e os conceitos suscitados por ela, julgue o item a\nseguir. Trata-se de cortes de regiões analisadas\npelo Alberta Stroke Program Early CT Score que\navalia apenas acidentes vasculares encefálicos isquêmicos no território de artéria cerebral média e\nquanto maior a pontuação, maior a área de isquemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352391","number":"352391","sourceNumber":"352391","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considerando a imagem acima e os conceitos suscitados por ela, julgue o item a\nseguir. No contexto da ressonância magnética,\nas sequências de difusão (DWI) positiva e a FLAIR\n(Fluid-Attenuated Inversion Recovery) negativa são altamente sensíveis. A presença dessas\ncaracterísticas é suficiente para concluir a avaliação do mismatch e prever que o déficit ocorreu há\nmenos de 4,5 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-366238","number":"366238","sourceNumber":"366238","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: É definida\ncomo convulsão em vigência de febre em crianças\nentre 3 meses e 5 anos de idade, desde que\nsem evidência de infecção intracraniana ou causa definida para o episódio, bem como exclusão de\nconvulsões febris anteriores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-366237","number":"366237","sourceNumber":"366237","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: O pico de\nidade é entre crianças entre 3 e 5 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-366211","number":"366211","sourceNumber":"366211","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: Geralmente é\nquadro espontâneo, sem fator causal, no qual a criança é investigada com exames laboratoriais e\nde imagem de crânio chegando a realizar líquor para diagnóstico de exclusão de infecção\nsubclínica de sistema nervoso central.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-366210","number":"366210","sourceNumber":"366210","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: À medida que\na temperatura aumenta, especialmente\nultrapassando os 39 °C, e à medida que se prolonga a\nduração dessa temperatura, aumenta a probabilidade de ocorrência de episódios convulsivos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-366209","number":"366209","sourceNumber":"366209","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Acerca de crise febril e seus conceitos correlatos, julgue o próximo item: O risco de\nrecorrência é mais elevado em crianças que experimentaram o episódio após completar 1 ano de\nidade. Algumas delas, ocasionalmente, podem necessitar de anticonvulsivantes por um período,\ndependendo da frequência das crises ao longo do ano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-343396","number":"343396","sourceNumber":"343396","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As síndromes geriátricas compartilham diversas características, embora heterogêneas.\nElas são altamente prevalentes entre idosos,\nsobretudo idosos frágeis, têm impacto significativo na\nqualidade de vida, comprometem de forma substancial a funcionalidade dos indivíduos e costumam\nser multifatoriais, acometendo, no seu desenvolvimento, diversos órgãos e sistemas. Dentre as\nalternativas abaixo, a que só contém síndromes geriátricas é:","options":{"A":"Incapacidade cognitiva, depressão, movimentos involuntários.","B":"Incontinência urinária, instabilidade e quedas, iatrogenia.","C":"Imobilidade, mal de Parkinson, reumatismo.","D":"Osteoporose, perda de autonomia, deterioração cognitiva."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-343397","number":"343397","sourceNumber":"343397","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre os tipos de disbasia (alteração da marcha), é CORRETO afirmar:","options":{"A":"Marcha espástica: essa é a característica de intoxicação alcoólica ou por barbitúricos. O\npaciente embriagado titubeia, cambaleia, inclina-se\npara diante e para trás, parecendo, a cada\nmomento, que está prestes a perder o equilíbrio e cair. O controle sobre o tronco e as pernas fica\nmais comprometido.","B":"Marcha vestibular: quando o doente tem paralisia do movimento de flexão do pé ao tentar\ncaminhar, toca com a ponta do pé o solo e\ntropeça. Para evitar, levanta acentuadamente o membro\ninferior, lembrando o ?passo de ganso?.","C":"Marcha escavante: o paciente, para caminhar, acentua a lordose lombar e vai inclinando o\ntronco ora para direita, ora para esquerda,\nalternadamente, lembrando o andar de um pato.\nObservada nos pacientes com diminuição da força dos músculos pélvicos e da coxa, e também nas\nmulheres grávidas.","D":"Marcha Parkinsoniana: o doente anda como um bloco, enrijecido, sem o movimento automático\ndos braços. A cabeça permanece inclinada para\nfrente e os passos são curtos e rápidos, dando a\nimpressão de que o doente ?corre atrás do seu centro de gravidade? e que vai cair pra frente."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-343401","number":"343401","sourceNumber":"343401","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"CMS, sexo feminino, 37 anos, dá entrada no pronto socorro relatando estar com ?a pior\ndor de cabeça da sua vida?. Refere início súbito, associada a náuseas e vômitos. Informou que\ncom frequência apresenta alterações visuais que duram em torno de 15 minutos, com sucessão de\ndores de cabeça do tipo pulsátil. No exame neurológico, encontrava- se sonolenta, sem sinais\nfocais, reflexos cutâneos plantares flexores e com rigidez de nuca (++/4+). O diagnóstico e o exame\ninicial mais indicados são:","options":{"A":"Hemorragia subaracnóidea por sangramento de aneurisma intracraniano; TC de crânio sem\ncontraste.","B":"Crise de migrânea com aura; angiorressonância do crânio.","C":"Crise de migrânea sem aura; punção lombar.","D":"Estado migranoso; angiografia com subtração digital."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-307098","number":"307098","sourceNumber":"307098","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 72 anos de idade foi levada ao pronto-socorro, relatando que, no dia\nanterior, acordou com dificuldade para falar, movimentar o braço e a perna direitos e notou que a\nboca estava ?torta? ao exame. Ela estava consciente, com PA = 178 x 116 mmHg, FC = 84 bpm,\nFR = 16 irpm e SatO? = 98% em ar ambiente. A tomografia de crânio realizada após dois dias de\ninternação revela hipodensidade leucocortical de limites parcialmente definidos envolvendo\nterritório\nda artéria cerebral média esquerda. Tendo em vista esse caso clínico e os conhecimentos médicos\ncorrelatos, assinale a alternativa correta.","options":{"A":"A hipertensão não entra como fator de risco para os eventos isquêmicos cerebrais.","B":"O início de corticosteroides e uso profilático de drogas antiepilépticas são recomendados no\ntratamento desse paciente.","C":"Nesse caso, recomenda-se a administração de ácido acetilsalicitico, dose inicial de 325 mg nas\nprimeiras 24 horas a 48 horas.","D":"Nessa paciente, a fibrilação atrial não seria fator de risco pelo evento ter acometido o sistema\nnervoso central.","E":"A reabilitação precoce em nada contribui em pacientes estáveis clinicamente, sem apresentar\nimpacto no prognóstico depois do evento."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-307107","number":"307107","sourceNumber":"307107","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 5 meses de vida foi levado à emergência por apresentar contração\ntônica rápida em flexão, com duração de 10\nsegundos, da musculatura do pescoço, do tronco e dos\nmembros. Essas crises iniciaram-se há duas semanas e ocorrem em salvas, especialmente ao\ndespertar e em períodos de sonolência, frequentemente acompanhados de choro. Os responsáveis\npela criança negam qualquer episódio de febre e (ou) outros sintomas. Nesse caso clínico, o\nprovável diagnóstico é Alternativas:","options":{"A":"cólica do lactente, demandando observação e orientação para casa.","B":"síndrome mioclônica atônica, precisando de observação.","C":"síndrome de West, com necessidade de EEG que revela hipsarritmia.","D":"síndrome convulsiva febril, com prescrição de clobazan para casa.","E":"síndrome focal por hipoglicemia."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-307116","number":"307116","sourceNumber":"307116","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"No que tange ao tema convulsão febril, assinale a alternativa correta. Alternativas:","options":{"A":"Apresenta evolução insidiosa, frequentemente associada a deficit neurológico.","B":"Apresenta maior recorrência quanto maior a idade do início.","C":"São, na maioria das vezes, generalizadas e breves, e podem ser clônicas.","D":"São acompanhadas de automatismos motores orais ou palpebrais.","E":"Manifesta-se acompanhada de estado pós-ictal prolongado."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274594","number":"274594","sourceNumber":"274594","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Durante o tratamento farmacológico, o médico pode vir a prescrever analgésicos que\nsão utilizados para reduzir e aliviar dores.\nConsiderando os dois grupos principais de analgésicos e\nsuas subdivisões, quanto aos opioides fortes, é CORRETO afirmar:","options":{"A":"Incluem somente a Morfina e a Fentanila.","B":"O Sulfato e o Cloridrato de Morfina podem ser utilizados por VO, retal, IM, SC, IV, espinal ou\nintraventricular.","C":"Estabilizada a dose, a Morfina deve ser substituída pela deliberação controlada ou por fármacos\nde ação curta, reservando-se a Morfina de ação\nprolongada.","D":"A Metadona pode ser empregada no tratamento da dor aguda no doente com câncer e não da\ndor não decorrente de neoplasia."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274597","number":"274597","sourceNumber":"274597","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considerando os vários exames complementares que ajudam na elucidação e\ndiagnóstico da dor do paciente, o tipo de\nexame complementar que permite melhor visualização de\ntodas as estruturas do tronco e dos elementos que compõem a coluna vertebral é:","options":{"A":"Ressonância magnética.","B":"Tomografia computadorizada.","C":"Radiografia óssea.","D":"Exame ultrassonográfico."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274598","number":"274598","sourceNumber":"274598","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os medicamentos adjuvantes são representados por fármacos inicialmente\nempregados para outras finalidades que não o\ntratamento da dor, contudo, buscam melhorar o\ndesempenho afetivo-motivacional, o rendimento do tratamento analgésico, o sono e o apetite dos\nindivíduos enfermos. A alternativa que apresenta os fármacos que são benéficos no tratamento da\ndor, mormente se crônica, neuropática ou nociceptiva, e para a profilaxia da enxaqueca, é:","options":{"A":"Ansiolíticos.","B":"Anestésicos locais.","C":"Corticosteroides.","D":"Antidepressivos."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274601","number":"274601","sourceNumber":"274601","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"As intervenções psicocomportamentais visam a alteração das crenças e a modificação\ndos comportamentos disfuncionais, bem como a alteração\nda percepção da dor neuropática,\npermitindo uma melhor adesão ao tratamento e maior confiança nas condutas propostas aos\npacientes. Nesse sentido, se encontra a psicoterapia de apoio, a qual traz benefícios para a\nnormalização das alterações afetivas não passíveis de controle farmacológico. Considerando as\ntécnicas de psicoterapia, é CORRETO afirmar:","options":{"A":"A psicoterapia auxilia os doentes a vislumbrar os seus objetivos de vida.","B":"As técnicas de psicoterapia devem ser regularmente prescritas para doentes com dor muito\nintensa porque a capacidade de participação torna-se comprometida devido às limitações\nfuncionais.","C":"As técnicas de psicoterapia podem ser regularmente prescritas para doentes adequadamente\ncontrolados com medicamentos.","D":"A psicoterapia possui como objetivo tratar apenas os problemas de depressão."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-263354","number":"263354","sourceNumber":"263354","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um homem com 55 anos de idade é encaminhado para esclarecimento diagnóstico de\ndéficit cognitivo associado a transtornos do movimento com suspeita de síndrome de Parkinson.\n\nNesse caso, qual é o achado semiológico que contribui para esse diagnóstico?","options":{"A":"Reflexos patelares exaltados associados à presença de clônus de rótula e de pés.","B":"Tremor em repouso, de baixa frequência e algo assimétrico (predominando na mão direita).","C":"Diminuição da sensibilidade vibratória e da propriocepção consciente nos membros inferiores.","D":"Presença de oftalmoplegia internuclear com alterações graves na mirada conjugada horizontal."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-268900","number":"268900","sourceNumber":"268900","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 55 anos de idade compareceu ao pronto atendimento relatando\nfraqueza, que se iniciou nos membros inferiores\ne foi progredindo para a cintura pélvica e os\nmembros superiores, com início há oito dias. Relatou infecção intestinal três semanas antes do\ninício da fraqueza. Ao exame, apresenta força muscular grau 2 nos membros inferiores e grau 3\nnos membros superiores. Verificam-se FC = 100 bpm, FR = 20 irpm, SatO2 = 98% e PA = 120\nmmHg x 80 mmHg. A hipótese diagnóstica foi feita como síndrome de Guillain-Barré. De acordo\ncom essa hipótese diagnóstica, espera-se encontrar","options":{"A":"hiperreflexia, alteração de sensibilidade, função esfincteriana preservada e líquido\ncefalorraquidiano com celularidade normal e aumento da concentração proteica.","B":"hiporreflexia, sensibilidade inalterada, função esfincteriana alterada e líquido\ncefalorraquidiano\ncom celularidade e concentração proteica aumentadas.","C":"arreflexia, sensibilidade inalterada, função esfincteriana alterada e líquido cefalorraquidiano\ncom\ncelularidade e concentração proteica aumentadas.","D":"hiporreflexia, sensibilidade inalterada, função esfincteriana alterada e líquido\ncefalorraquidiano\ncom celularidade e concentração proteica normais.","E":"arreflexia, alteração de sensibilidade, função esfincteriana preservada e líquido\ncefalorraquidiano\ncom celularidade normal e aumento da concentração\nproteica."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274616","number":"274616","sourceNumber":"274616","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Convulsões são alterações paroxísticas da função neurológica (comportamental,\nmotora e/ou autonômica). A convulsão clônica no\nrecém-nascido se caracteriza por:","options":{"A":"Movimentos rítmicos, inicialmente de 1 a 3 segundos, declinando progressivamente.","B":"Movimentos rítmicos, inicialmente de 1 a 15 segundos, declinando progressivamente.","C":"Movimentos rítmicos, inicialmente de 1 a 10 segundos, declinando progressivamente.","D":"Movimentos arrítmicos, inicialmente de 1 a 15 segundos, declinando progressivamente."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274617","number":"274617","sourceNumber":"274617","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Considerando a convulsão mioclônica no recém-nascido, quanto à sua característica\nprincipal, é CORRETO afirmar:","options":{"A":"Relaxamento de todos os músculos do corpo.","B":"Movimentos lentos e predileção pelo grupo muscular flexor.","C":"Movimentos de velocidade rápida e predileção pelo grupo muscular flexor.","D":"Ausência de movimento e atrofia do grupo muscular flexor."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-263367","number":"263367","sourceNumber":"263367","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um homem com 62 anos de idade chega à sala de emergência de um hospital com\nquadro de instalação abrupta, há cerca de\n1 hora, de monoparesia superior direita associada à\nafasia não fluente. O paciente, que tem histórico de diabete melito tipo 2, vem usando metformina\n850 mg 2 vezes por dia, além de Ácido Acetilsalicílico (AAS), devido à ocorrência de fibrilação\natrial\nparoxística recorrente, tendo um ponto no escore CHA2DS2-VASc. Não há outras morbidades nem\nalergias. Na admissão hospitalar, o paciente mantém o déficit, que parece ter piorado um pouco\nnos últimos minutos. Está acordado, angustiado com a inegável afasia não fluente (Broca) e com\ndiminuição moderada da força no membro superior direito. Apresenta PA = 160 x 100 mmHg, FC =\n110 bpm, com ritmo cardíaco irregular e com anisocardiosfigmia. Neste momento, apresenta\nglicemia capilar = 300 mg/dl. O paciente é imediatamente encaminhado para a realização de uma\ntomografia computadorizada de crânio sem contraste, cuja imagem é apresentada na figura a\nseguir, tendo o laudo sido liberado cerca de 2 horas e 30 minutos após o início do quadro\nneurológico. Diante desse quadro, quais são o diagnóstico e a conduta médica adequados nesse\nmomento?","options":{"A":"Ataque isquêmico transitório; iniciar anticoagulação plena endovenosa em associação ao AAS.","B":"Acidente vascular encefálico isquêmico; proceder à trombólise imediata com rtPA.","C":"Acidente vascular encefálico isquêmico; contraindicar a terapia trombolítica.","D":"Ataque isquêmico transitório; associar clopidogrel ao AAS."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-263369","number":"263369","sourceNumber":"263369","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma adolescente com 11 anos de idade, com diagnóstico de epilepsia, chega ao\nPronto-Socorro (PS) inconsciente, com movimentos tônico-clônicos generalizados, cianótica, com\ndesvio do olhar e sialorreia. A mãe informa que a adolescente iniciou a crise há 20 minutos, sem\nrecuperar a consciência ao longo do trajeto para o PS. Na sala de emergência, devido à\npersistência do quadro, é administrado diazepam endovenoso por 3 vezes, com intervalo de 5\nminutos entre as doses. Apesar da intervenção terapêutica, a paciente mantém o quadro\nconvulsivo. Nesse caso, a próxima conduta médica deve ser administrar:","options":{"A":"Topiramato por infusão endovenosa contínua.","B":"Fenitoína em dose de ataque endovenosa.","C":"Diazepam em dose dobrada endovenosa.","D":"Tiopental por cânula endotraqueal."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274622","number":"274622","sourceNumber":"274622","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A epilepsia é um dos transtornos neurológicos de maior prevalência no mundo.\nConsiderando a epilepsia rolândica, é CORRETO afirmar:","options":{"A":"Esse é o tipo mais comum de desordem epiléptica da infância, afetando entre 15% e 25% das\ncrianças com o distúrbio.","B":"É um tipo de epilepsia que não acomete crianças e adolescentes.","C":"Só acomete crianças a partir dos 7 anos.","D":"Só acomete crianças até os 7 anos."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-263374","number":"263374","sourceNumber":"263374","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente com 47 anos de idade, motorista de ônibus, comparece ao ambulatório da\natenção secundária relatando início de dor lombar baixa há 2 semanas, a qual se irradia para\nmembros inferiores. Ele nega ter sofrido queda e/ou trauma local. Devido à intensidade da dor,\nprocurou atendimento em emergência na época, tendo recebido medicação endovenosa e\norientação para acompanhamento ambulatorial para investigação. O paciente afirma que possui dor\nainda incapacitante, a qual piora ao se sentar e ao ficar em pé, mas que melhora com o repouso.\n\nEssa dor possui irradiação pela região posterior da coxa e perna, chegando até a planta do pé à\ndireita. Também relata diminuição da\nsensibilidade no dorso do pé direito. Ao realizar exame físico,\napresentou teste de elevação do membro inferior estendido positivo à direita quando realizando a\n40 graus, além de hipoestesia em região de dorso do pé direito, com reflexos sem alterações e sem\nperda de força muscular. A conduta imediata adequada para o caso é","options":{"A":"receitar opioide a curto prazo e orientar o paciente a retornar ao trabalho conforme intensidade\nda dor.","B":"prescrever anti-inflamatórios, relaxante muscular e início de exercícios para fortalecimento\nlombar.","C":"encaminhar o paciente para cirurgia imediata para descompressão.","D":"receitar corticosteroide sistêmico e repouso por 14 dias."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-273347","number":"273347","sourceNumber":"273347","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 25 anos, após quadro de diarreia autolimitada prévia dá entrada no PS\ncom quadro de perda de força ascendente,\ndiminuição dos reflexos tendinosos e sensação de\nformigamento nas pernas. O exame do líquor mostra importante proteinorraquia com celularidade\nnormal. Considerando-se a principal hipótese podemos afirmar que:","options":{"A":"Cerca de 80% apresentam parestesia de mãos e pés associada a fraqueza","B":"Alteração de sensibilidade é comum, sendo mais facilmente diagnosticada testando-se a\nsensibilidade tátil","C":"Na fase aguda a apresentação com dorsalgia é rara e deve sugerir diagnóstico diferencial mais\namplo","D":"A presença de disautonomia é infrequente, mas confere pior prognóstico neurológico"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274627","number":"274627","sourceNumber":"274627","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O surgimento de uma síndrome pode decorrer de diversos fatores, tais como genéticos\ne hereditários, até situações traumáticas e\nepigenéticas. Considerando a definição da Síndrome de\nTourette, é CORRETO afirmar:","options":{"A":"Denota o quadro clínico em crianças resultante do excesso de cortisol por qualquer causa.","B":"É conhecida como a doença dos tiques e as crianças que a sofrem realizam movimentos rápidos\ne involuntários dos músculos e produção\ninvoluntária de ruídos e palavras.","C":"É o transtorno mental caracterizado por humor e comportamentos instáveis, que se inicia\nnormalmente em crianças de 2 anos.","D":"É a condição que causa inflamação nas paredes de alguns vasos sanguíneos do corpo."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-291498","number":"291498","sourceNumber":"291498","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente masculino, com 62 anos de idade, vem à consulta médica na atenção\nsecundária ambulatorial, encaminhado por tremor. O\npaciente conta que, há alguns meses, teve\ninício com tremor no braço direito e que, agora, parece ter progredido para ambos os braços e\nambas as pernas. O paciente diz que o tremor piora quando ele \"está nervoso\", mas que parece\nmelhorar quando faz alguma atividade, como cozinhar ou comer. Entretanto, o paciente conta que é\ndifícil, para ele, levantar-se da posição sentada e começar a andar. Também refere que perde o\nequilíbrio quando está caminhando e \"muda de rota\", e tem dificuldade para parar de caminhar,\nrelatando duas quedas no mês anterior à consulta. Com base no que foi apresentado, o diagnóstico\ndesse paciente é:","options":{"A":"Tremor essencial.","B":"Paralisia supranuclear progressiva.","C":"Doença de Huntington.","D":"Doença de Parkinson."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-291507","number":"291507","sourceNumber":"291507","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher de 61 anos foi trazida ao pronto-socorro devido à disartria e hemiparesia\ndireita há 3 horas. Ela estava em uma\nreunião de trabalho quando, subitamente, iniciou com os\nsinais e sintomas. O serviço móvel de urgência foi acionado e, após a avaliação inicial, fez contato\ncom o pronto-socorro para receber a paciente. Não há relato de episódios prévios, infarto do\nmiocárdio, cirurgia ou hemorragia recentemente, apenas de hipertensão arterial há 10 anos, em uso\nde losartana 50mg, 2 vezes ao dia. O exame físico não apresenta maiores alterações, exceto por\nredução de força em membro superior e inferior direito. A paciente estava alerta, contudo, parecia\nter alguma dificuldade para compreensão dos comandos do médico urgencista. Sua pressão\narterial é de 120 x 80 mmHg, frequência cardíaca = 92 bpm, com 18 movimentos respiratórios por\nminuto. Se a tomografia computadorizada de crânio não mostrar sinais de sangramento, a conduta\na ser adotada imediatamente é","options":{"A":"encaminhamento para tratamento endovascular.","B":"admissão em unidade de terapia intensiva para estabilização.","C":"administração de Alteplase, via endovenosa.","D":"administração de ácido acetil salicílico e observação em unidade semi-intensiva."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-274640","number":"274640","sourceNumber":"274640","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O transplante é capaz de promover melhoria na qualidade e perspectiva de vida. É\ntransplante de órgão a reposição de:","options":{"A":"Coração, esclera e pele.","B":"Pulmão, cartilagem e osso.","C":"Rim, válvula cardíaca e vaso sanguíneo.","D":"Fígado, pâncreas e intestino."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-291512","number":"291512","sourceNumber":"291512","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma lactente do sexo feminino, de 18 meses de idade, chega para atendimento em\nUnidade Básica de Saúde. A mãe informa que, há 3 dias, a criança apresentou quadro de\nconvulsão tônico-clônica generalizada acompanhada de versão ocular, liberação de esfíncter\nvesical e sialorreia, com duração de aproximadamente 10 minutos. No momento, apresentava\ntemperatura axilar de 38ºC. Foi levada ao pronto atendimento, onde chegou sem crise e recebeu\nalta após 4 horas com diagnóstico de resfriado comum. O episódio convulsivo não se repetiu e a\ncriança está afebril há 48 horas. A mãe relata episódio semelhante aos 11 meses de idade. A\ncriança não apresenta outros antecedentes pessoais ou familiares relevantes. O seu\ndesenvolvimento neuropsicomotor é normal e o exame clínico não apresenta alterações.\n\nConsiderando os dados clínicos da paciente, essa criança apresenta:","options":{"A":"Convulsão febril simples. A mãe deve ser orientada quanto à abordagem nos episódios febris e a\ncriança deve manter acompanhamento de rotina na UBS pelo caráter benigno do quadro.","B":"Convulsão febril simples. O médico deve prescrever benzodiazepínico (diazepam ou nitrazepam)\npara uso durante os episódios febris, com o\nobjetivo de prevenir epilepsia futura.","C":"Convulsão febril complexa. A criança deve realizar eletroencefalograma e tomografia\ncomputadorizada de crânio por não ser o primeiro episódio convulsivo febril apresentado.","D":"Convulsão febril complexa. Os familiares precisam ser alertados sobre a possibilidade de a\ncriança apresentar desempenho escolar fraco futuramente como sequela dos episódios\nconvulsivos."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-266499","number":"266499","sourceNumber":"266499","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Marta, de 69 anos de idade, acompanhava seu esposo em uma consulta médica de\nrotina. O casal aguardava o atendimento\nquando, de repente, Marta começou a passar mal. O\nesposo dela, então, pediu ajuda, aos gritos, afirmando \"Marta está tendo uma bilora, não fala nada\ncom nada!\" (sic). A médica Joana prontamente atendeu Marta e iniciou a avaliação dela. Na\navaliação clínica da paciente, constatou-se hemiparesia à esquerda, anisocoria, afasia, nível 14 na\nescala de Glasgow (AO4/RV 4/RM6), pressão arterial de 190 mmHg x 120 mmHg, frequência\ncardíaca de 52 bpm e glicemia capilar de 294 mg/dL. Considerando o caso clínico precedente,\njulgue o próximo item. Se não houver sinais de lesão em órgãos-alvo, o caso deve ser tratado como\nprovável pseudocrise hipertensiva, cabendo à médica Joana exercer demora permitida, administrar\nà paciente dois comprimidos de captopril 25 mg e um de diazepan 5 mg, por via oral, e questionar a\npaciente sobre o que a estaria afligindo no momento, buscando entendê-la como um todo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-266500","number":"266500","sourceNumber":"266500","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Marta, de 69 anos de idade, acompanhava seu esposo em uma consulta médica de\nrotina. O casal aguardava o atendimento\nquando, de repente, Marta começou a passar mal. O\nesposo dela, então, pediu ajuda, aos gritos, afirmando \"Marta está tendo uma bilora, não fala nada\ncom nada!\" (sic). A médica Joana prontamente atendeu Marta e iniciou a avaliação dela. Na\navaliação clínica da paciente, constatou-se hemiparesia à esquerda, anisocoria, afasia, nível 14 na\nescala de Glasgow (AO4/RV 4/RM6), pressão arterial de 190 mmHg x 120 mmHg, frequência\ncardíaca de 52 bpm e glicemia capilar de 294 mg/dL. Considerando o caso clínico precedente,\njulgue o próximo item. Na ausência de resposta às medidas estabelecidas na avaliação inicial, a\nequipe médica deve orientar Marta a retornar à sua residência, para repousar, e orientar o esposo\ndela a acionar o serviço de atendimento móvel de urgência (SAMU) caso surjam sinais de piora na\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-230553","number":"230553","sourceNumber":"230553","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na Artéria Carótida Interna (ACI) as ondas de velocidade de fluxo são normalmente de\nbaixa resistência. Assim podemos APENAS concordar que:","options":{"A":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é de baixa resistência,\nenquanto na Artéria Carótida Comum (ACC) é do tipo\nintermediário entre as carótidas interna e\nexterna.","B":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é de alta resistência,\nenquanto na Artéria Carótida Comum (ACC) é do\ntipo elevado entre as carótidas interna e externa.","C":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é sem resistência, enquanto\nna Artéria Carótida Comum (ACC) é do tipo\nintermediário entre as carótidas interna e externa.","D":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é de alta resistência,\nenquanto na Artéria Carótida Comum (ACC) é do\ntipo intermediário entre as carótidas interna e\nexterna."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-244473","number":"244473","sourceNumber":"244473","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 24 anos de idade apresentou história de seis dias de fraqueza\nprogressiva dos membros inferiores de forma\nascendente e, na manhã de hoje, não consegue\nandar em razão da paralisia completa dos membros inferiores bilateralmente. Há duas semanas,\nela teve um episódio de gastroenterite com diarreia profusa, aquosa, com duração de três dias.\nNega comorbidades prévias. Não há histórico familiar positivo para doenças crônicas. Pressão\narterial = 84 bpm, frequência respiratória = 18 irpm, temperatura = 36ºC, saturação de oxigênio =\n97% no ar ambiente. Exame neurológico: sem sinais de rigidez do pescoço ou meningismo. Sem\nenvolvimento dos pares cranianos. Força muscular: membros inferiores esquerdo e direito grau 0,\nmembros superiores esquerdo e direito grau 5, arreflexia em membros inferiores e reflexo em\nmembros superiores grau 2. Sensibilidade tátil e dolorosa normal globalmente. No primeiro dia após\na admissão, a paciente foi internada na enfermaria neurológica e seus sintomas continuaram a\npiorar. Começou a alegar diminuição da força em membros superiores bilateralmente. A RM foi\nsugestiva de realce da raiz nervosa, e a RM de crânio foi normal. Com base nesse caso clínico e\nnos conhecimentos médicos referentes à provável Síndrome de Guillain-Barré (SGB), assinale a\nalternativa CORRETA.","options":{"A":"A paciente em estudo pode ser tratada com timoglobulina de cavalo 0,4 g kg IVI por cinco dias.\n\nO mecanismo exato de ação não é conhecido, mas acredita-se que vários mecanismos estejam\nenvolvidos, incluindo a inibição da produção de anticorpos, a inibição da ligação do complemento e\na neutralização dos anticorpos patológicos.","B":"O importante conceito imunológico da SGB é o desenvolvimento de reatividade cruzada de\nautoanticorpos direcionados contra os axônios encontrados em neurônios e mielina.","C":"Uma terapia alternativa para a paciente é a plasmaférese. Esse mecanismo consiste na retirada\nde metabólicos de amônia associados a\nautoanticorpos IgM presentes no plasma.","D":"A SGB é considerada uma polineuropatia axonal aguda padrão de luva e bota de neurônio motor\nsuperior. Portanto, a paciente necessita de realização de fundoscopia ocular para confirmação de\nneurite óptica, achado esse patognomônico da SGB.","E":"A SGB é geralmente precedida por uma infecção respiratória ou gastrointestinal, e o organismo\nassociado mais comum é a bactéria causadora de diarreia Campylobacter jejuni. No entanto,\nHaemophilus influenzae, Mycoplasma pneumoniae e infecções virais (CMV, HIV e EBV) também\nforam associados à SGB."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-244479","number":"244479","sourceNumber":"244479","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente de 2 anos e 3 meses de idade foi levado pela mãe, desesperada, ao\npronto atendimento. A criança apresentou um\nepisódio de crise convulsiva em casa, em que se\ncontorceu toda, debateu-se, ficou desacordada, um pouco roxa e salivando, mas logo retomou a\nconsciência. A crise durou cerca de 3 minutos. Agora, passados 15 minutos, o paciente está\nlevemente sonolento. Nunca havia apresentado algo parecido antes. Sempre foi um garoto\nsaudável. Durante o dia, estava bem, porém inapetente e só reclamou de dor para engolir. Nega\ntosse, vômitos, diarreia, cefaleia. Ao exame físico, encontra-se febril (39,5 ºC), taquipneico leve,\ntaquicárdico FC = 143 bpm, pulsos amplos, com boa perfusão periférica. Observam-se ausculta\ncardiopulmonar normal, abdome inocente, sem sinais meníngeos ou localizatórios, com pupilas\nisocóricas isofotorreagentes, orofaringe com hiperemia e placas purulentas em amígdalas, e cadeia\nganglionar cervical anterior aumentada. Depois de aproximadamente 20 minutos, a criança já\nestava bem alerta e com temperatura de 38,3 ºC (havia tomado dipirona no caminho de casa para o\nhospital). Com base nesse caso clínico e considerando o quadro convulsivo apresentado por esse\npaciente, assinale a alternativa correta.","options":{"A":"Como a crise ocorreu em vigência de febre, deve ser colhido líquor para análise microbiológica e\nafastamento da hipótese de meningite.","B":"Na ocasião da alta, o paciente deve ser encaminhado para realização de eletroencefalograma e\ntomografia de crânio.","C":"Trata-se de convulsão febril simples e não há indicação de anticonvulsivante profilático nesse\nmomento.","D":"Deveria ser administrado diazepam à admissão, pois o paciente estava sonolento ainda.","E":"Trata-se de crise de ausência e está indicada profilaxia com ácido valproico preferencialmente."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-230584","number":"230584","sourceNumber":"230584","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre isquemia cerebral de origem extracraniana, marque a CORRETA:","options":{"A":"A arterite de Takayasu pode levar a isquemia cerebral extracraniana, sendo mais comum em\nhomens a partir da sexta década de vida.","B":"A displasia fibromuscular ocorre mais frequentemente em pacientes do sexo feminino.","C":"A aterosclerose não é causa comum de ataque isquêmico transitório e de acidente vascular\ncerebral.","D":"Na displasia fibromuscular a cirurgia de endarterectomia de carótidas é sempre o melhor\ntratamento."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-230591","number":"230591","sourceNumber":"230591","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A endarterectomia de carótida é uma cirurgia consagrada no tratamento da isquemia\ncerebral de origem extracraniana. Sobre suas complicações, é CORRETO afirmar:","options":{"A":"A microembolização cerebral pode levar a acidente vascular encefálico.","B":"A lesão intra-operatória do nervo vago causa alteração motora de metade da língua.","C":"A lesão do nervo hipoglosso pode levar a regurgitações alimentares, com broncoaspiração e\npneumonia de repetição.","D":"O ramo mandibular do nervo facial quando lesado leva a dificuldade em emitir notas de timbre\nagudo e resulta em fatigabilidade da voz."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-230623","number":"230623","sourceNumber":"230623","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A redução da polifarmácia podem diminuir o nível de fragilidade e os desfechos\nadversos e os riscos das intervenções. Podemos\napenas CONCORDAR que:","options":{"A":"A identificação da fragilidade não deve ser vista como uma razão para se negar ou suspender\ntratamentos, mas como um meio para se\nprogramarem intervenções individualizadas e centradas\nno paciente.","B":"A identificação da fragilidade deve ser vista como uma razão para se negar ou suspender\ntratamentos, mas como um meio para se programarem\nintervenções individualizadas e centradas\nno paciente.","C":"A identificação da fragilidade não deve ser vista como uma razão para se negar ou suspender\ntratamentos, nunca como um meio para se\nprogramarem intervenções individualizadas e centradas\nno paciente.","D":"A identificação da fragilidade não deve ser vista como uma razão para se negar ou suspender\ntratamentos, mas como um meio para se programarem intervenções gerais e não centradas no\npaciente."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-230624","number":"230624","sourceNumber":"230624","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Independentemente do instrumento para rastreio e identificação utilizado, a síndrome\nde fragilidade deve ser pesquisada em todos idosos\nacima de 70 anos de idade e naqueles com\nDCV, podemos assim CONCORDAR que:","options":{"A":"Assim mesmo que abaixo dessa faixa etária, medidas para a sua prevenção e tratamento não\ndevem ser operacionalizadas.","B":"Assim mesmo que abaixo dessa faixa etária, medidas para a sua prevenção e tratamento devem\nser operacionalizadas.","C":"Assim abaixo dessa faixa etária, medidas para a sua prevenção e tratamento não devem ser\noperacionalizadas.","D":"Assim mesmo que abaixo dessa faixa etária, medidas para a sua prevenção e tratamento nunca\ndevem ser operacionalizadas."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-230637","number":"230637","sourceNumber":"230637","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A partir de estudo cardiovascular criou critérios diagnósticos conhecidos como o\n\n?Fenótipo da Fragilidade de Fried et al.?, ou ?Escala de Rastreio de Fragilidade do\nCardiovascular?. Podemos apenas CONCORDAR que:","options":{"A":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso\nintencional, fraqueza muscular, exaustão (fadiga), redução da velocidade da marcha e diminuição\ndo grau de atividade física.","B":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso não\nintencional, fraqueza muscular, exaustão (fadiga), redução da velocidade da marcha, mas não\ndiminuição do grau de atividade física.","C":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso não\nintencional, fraqueza muscular, exaustão (fadiga), redução da velocidade da marcha e diminuição\ndo grau de atividade física.","D":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso não\nintencional, mas sem fraqueza muscular, exaustão ou fadiga."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-206168","number":"206168","sourceNumber":"206168","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os tumores cerebrais primários são um conjunto de neoplasias malignas originárias de\ncélulas de sustentação do tecido nervoso. A gradação dos tumores é baseada em aspectos\nhistopatológicos. Podemos considerar INADEQUADO que:","options":{"A":"A ressecção cirúrgica é o tratamento recomendado na maioria dos casos de tumor cerebral, com\nobjetivo de remover amplamente a neoplasia com a máxima preservação das funções neurológicas.","B":"Eventualmente, a localização do tumor em área eloquente permite apenas citorredução ou\nbiópsia da lesão.","C":"São tumores raros, correspondendo a 2% dos todos os cânceres conhecidos, com baixa\nmortalidade em adultos ? status pouco modificado pelo emprego das modalidades erapêuticas\ndisponíveis.","D":"O diagnóstico definitivo é firmado pelo estudo histopatológico de espécime tumoral obtido por\nbiópsia estereotática ou a céu aberto, sendo essencial para o planejamento terapêutico."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-203148","number":"203148","sourceNumber":"203148","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um lactente de 5 meses de vida iniciou quadro de alteração do desenvolvimento\nneuropsicomotor, acompanhado de movimentos do tipo\njack-knife e slaam, simétricos, de curta\nduração, mais evidentes quando desperta. Foi avaliado pela neurologia pediátrica, sendo realizado\num eletroencefalograma com o traçado apresentado. A respeito desse caso clínico, assinale a\nalternativa que corresponde ao diagnóstico e à conduta mais adequada para o caso.","options":{"A":"Diagnóstico: síndrome de Aicardi. Tratamento: vigabatrina.","B":"Diagnóstico: epilepsia mioclônica do lactente. Tratamento: não há tratamento específico.","C":"Diagnóstico: síndorme de Ohtahara. Tratamento: drogas antiepiléticas.","D":"Diagnóstico: síndrome de West. Tratamento: ACTH.","E":"Diagnóstico: síndrome de Dravet. Tratamento: vigabatrina."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-206104","number":"206104","sourceNumber":"206104","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Os sintomas do Transtorno do Déficit de Atenção e Hiperatividade (TDAH), segundo os\ncritérios do DSM-V, persistirão por mais de 6 meses, causando prejuízo em pelo menos dois\nambientes diferentes, não havendo outra patologia que explique melhor o quadro clínico. Isso\nocorre antes de qual idade?","options":{"A":"7 anos de idade.","B":"18 anos de idade.","C":"12 anos de idade.","D":"5 anos de idade."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-206162","number":"206162","sourceNumber":"206162","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Qual das alterações cardiovasculares abaixo NÃO é considerada como decorrente do\navançar da idade em pacientes geriátricos?","options":{"A":"Redução do número de miócitos.","B":"Redução da dependência de pré-carga.","C":"Redução da responsividade ?-adrenérgica.","D":"Disfunção diastólica aumentada."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-183910","number":"183910","sourceNumber":"183910","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A cerca das causas, do tratamento e das consequências relacioandas às quedas de\nidosos, julgue o item a seguir. Escadas com\ndegraus de altura ou largura irregular, tapetes\npequenos ou capachos em superfícies lisas, móveis deslizantes, roupas excessivamente compridas\ne escadas com iluminação frontal são exemplos de riscos domésticos para quedas de idosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-175122","number":"175122","sourceNumber":"175122","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Com relação aos tumores do Sistema Nervoso Central, assinale a alternativa\nINCORRETA:","options":{"A":"Os sítios primários de metástase cerebral mais comuns são: pulmão, mama, melanoma e cólon.","B":"Astrocitomas correspondem a 50% dos tumores encefálicos primários.","C":"Fludrocortisona é indicado na maioria dos casos para redução do edema peritumoral.","D":"Anticonvulsivantes devem ser utilizados se o tumor é localizado próximo a área sensitivo-motora."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-177226","number":"177226","sourceNumber":"177226","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação à sarcopenia na população idosa, definida como a perda de massa e de\nfunção muscular, que ocorre ao longo dos anos, podendo ser intensificada pela presença de\ndoenças crônicas, assinale a alternativa correta:","options":{"A":"O diagnóstico de sarcopenia é realizado exclusivamente pela análise da massa muscular com\ndensitometria, bioimpedância ou análise de dobras cutâneas.","B":"O uso de ésteres de testosterona injetável é indicado para a recuperação de massa magra\nnesses pacientes.","C":"A insulinoterapia com insulinas de ação longa é uma das estratégias terapêuticas aprovadas\npara aumentar-se o anabolismo muscular desses\npacientes.","D":"Na população idosa em geral, o treinamento de potência é menos efetivo que o de força quando\nestudam-se desfechos de funcionalidade.","E":"A prática de exercício físico resisitido e o aumento da ingesta proteica resultaram em efeitos\npositivos em vários ensaios clínicos com idosos sarcopênicos."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-159614","number":"159614","sourceNumber":"159614","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo masculino, de oitenta e três anos de idade, portador de mal de\nAlzheimer e que, havia seis anos, sofrera\ninfarto agudo do miocárdio, o que motivou a colocação de\nstent em sua artéria coronária direita, apresentou quadro súbito de paralisia do dimidio esquerdo,\nbem como alteração da fala e do nível de consciência. Ao ter sido internado na UTI,\n\ndiagnosticou-se AVCI no paciente. Durante o período de internação na UTI, ele apresentou\ndificuldade de se alimentar por via oral,\ncom episódios de broncoaspiração associados, motivo por\nque foi necessário definir a SNE como via exclusiva de alimentação. Realizada avaliação da\ndeglutição mediante videodeglutograma, foi diagnosticada disfagia orofaríngea grave. Foi solicitada\nao paciente a realização de gastrostomia endoscópica. Nesse período, ele estava em uso de\nclopidogrel e AAS. A partir desse caso clínico, julgue o próximo item. Para a realização da\ngastrostomia endoscópica, o paciente deve suspender o uso das referidas medicações pelo menos\ncinco dias antes do procedimento e, durante o pré-operatório, deve substituí-las por heparina de\nbaixo peso molecular, suspendendo seu uso, entretanto, vinte e quatro horas antes do\nprocedimento cirúrgico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-154481","number":"154481","sourceNumber":"154481","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 35 anos de idade, queixa-se de apresentar dor em face\nesquerda, em região maxilar e mandibular.\nRelata que a dor é de forte intensidade, ocorre em\nparoxismos, com início e término súbitos, havendo relação por vezes com a escovação dos dentes\nou mastigação. Procurou avaliação odontológica, porém não foram constatadas alterações\ndentárias ou bucais. Refere que, por vezes, chega a apresentar mais de 10 crises por dia, afetando\nseu humor e sua capacidade laboral. Qual o tratamento mais adequado para o agravo em questão?","options":{"A":"Sumatriptano.","B":"Nebulização com oxigênio a 100%.","C":"Carbamazepina.","D":"Prednisona.","E":"Ergotamínicos."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-154493","number":"154493","sourceNumber":"154493","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 34 anos de idade, previamente hígida, com queixa de\nfraqueza muscular há cerca de 1 semana. Relata\nque, por vezes, tem apresentado diplopia e ptose\npalpebral, principalmente ao final do dia. O médico que a atende logo suspeita de um diagnóstico, e\nresolve fazer um teste com edrofônio para corroborar sua hipótese. Após a aplicação do fármaco,\nos sintomas da paciente \"milagrosamente\" desapareceram. Tendo como base o caso acima, qual é\na principal hipótese diagnóstica?","options":{"A":"Dermatomiosite.","B":"Guillain-Barré.","C":"Esclerose Múltipla.","D":"Miastenia Gravis.","E":"Distrofia Muscular de Duchenne."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-154495","number":"154495","sourceNumber":"154495","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente do sexo feminino, 34 anos de idade, previamente hígida, com queixa de\nfraqueza muscular há cerca de 1 semana. Relata\nque, por vezes, tem apresentado diplopia e ptose\npalpebral, principalmente ao final do dia. O médico que a atende logo suspeita de um diagnóstico, e\nresolve fazer um teste com edrofônio para corroborar sua hipótese. Após a aplicação do fármaco,\nos sintomas da paciente \"milagrosamente\" desapareceram. Qual o anticorpo que provavelmente\nserá encontrado na paciente em questão?","options":{"A":"Anti-centrômero.","B":"Anti-músculo liso.","C":"Anti-receptor de acetilcolina.","D":"Anti-citoplasma de neutrófilo.","E":"Anti-Ro."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-168445","number":"168445","sourceNumber":"168445","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um menino com 5 anos e 11 meses de idade faz seguimento de rotina em Unidade\nBásica de Saúde desde o nascimento, sem\nantecedentes morbidos relevantes. Em sua última\nconsulta, há um ano, sua estatura era de 110 cm; na consulta atual está medindo 111 cm. Há 4\nmeses, passou a apresentar cefaleia holocraniana diária, de intensidade moderada a forte e\ndificuldade visual. A avaliação oftalmolóogica revelou hemianopsia bitemporal. A principal hipótese\ndiagnósticada para esse caso é","options":{"A":"cordoma.","B":"schwannoma.","C":"craniofaringeoma.","D":"tumor de plexo coroide."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-154476","number":"154476","sourceNumber":"154476","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Adolescente de 12 anos, previamente hígida, refere incoordenação do movimento das\nmãos há cerca de 10 dias, com piora\nprogressiva e evolução para movimentos involuntários dos\nmembros, com melhora durante o sono e piora quando está nervosa. Apresenta às vezes\ndificuldade de escrever e de falar, labilidade emocional e por vezes choro durante os episódios. A\nprincipal hipótese diagnóstica é:","options":{"A":"Encefalomielite Disseminada Aguda.","B":"Síndrome Conversiva.","C":"Lúpus Eritematoso Sistêmico.","D":"Coréia de Sydenham.","E":"Doença de Huntington."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-159515","number":"159515","sourceNumber":"159515","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Julgue o item a seguir, acerca da doença de Parkinson. Além de apresentar efeitos\ncolaterais significativos, a Levodopa é o principal tratamento clínico dessa doença neurológica, já\nque, devido ao seu efeito neuroprotetor, modifica o curso progressivo da doença de Parkinson.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-159522","number":"159522","sourceNumber":"159522","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Julgue o item a seguir, acerca da doença de Parkinson. Os distúrbios do movimento\nobservados nos portadores dessa doença são\ninvoluntários, aleatórios, rápidos e migratórios e,\ncom frequência, passam subitamente de uma parte do corpo para outra, em sequência imprevisivel\ne sem propósito.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-168451","number":"168451","sourceNumber":"168451","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher com 40 anos de idade é atendida em hospital, queixando-se de ter tido\ncefaleia súbita de forte intensidade, com náuseas e vômitos, seguida de perda de consciência. Ao\nexame, mostra-se consciente, orientada, sem deficit motor, com pupilas isocóricas e rigidez de\nnuca importante. Neste caso, o diagnóstico mais provável é:","options":{"A":"Enxaqueca complicada.","B":"Hemorragia subaracnoide.","C":"Hematoma intraparenquimatoso.","D":"Acidente vascular cerebral isquêmico."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-158024","number":"158024","sourceNumber":"158024","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O médico está avaliando Maria, uma senhora de 70 anos de idade, que apresentou\nAVC há cerca de quatro meses, com boa\nrecuperação do quadro de hemiparesia à direita que\nantes apresentava, mas que manteve algumas sequelas motoras. Maria voltou a conseguir tomar\nbanho, vestir-se, comer e ir ao banheiro sem necessitar de auxílio. Entretanto, o esposo dela,\nAntônio, teve de assumir as tarefas de preparar refeições, fazer compras e limpar a casa, pois\nMaria não mais conseguiu. Ela ainda toma decisões e \"manda na casa\", definindo que coisas serão\ncompradas e quais pratos serão feitos. No que se refere a esse caso hipotético, assinale a\nalternativa CORRETA.","options":{"A":"Maria é independente para as atividades básicas de vida diária, mas dependente para as\natividades instrumentais de vida diária. Não tem autonomia preservada.","B":"Maria é dependente para as atividades básicas de vida diária, mas independente para as\natividades instrumentais de vida diária. Não tem autonomia preservada.","C":"Maria é dependente para as atividades básicas de vida diária e para as atividades instrumentais\nde vida diária. Tem autonomia preservada.","D":"Maria é independente para as atividades básicas de vida diária, mas dependente para as\natividades instrumentais de vida diária. Tem autonomia preservada.","E":"Maria é independente para as atividades básicas de vida diária e para as atividades\ninstrumentais de vida diária. Tem autonomia preservada."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-168508","number":"168508","sourceNumber":"168508","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher com 75 anos de idade, aposentada há 15 anos, reside em uma instituição\nde longa permanência de idosas conveniada à\nprefeitura local. Ela perdeu contato com sua família,\napresenta demência grave, síndrome da imobilidade e cognitiva, vive restrita ao leito e com\ndependência completa de outra pessoa para realização de todas as atividades da vida diária na\ninstituição. Tem histórico de três internações hospitalares prolongadas no último semestre devido a\npneumonia por aspiração e está em uso regular de haloperidol 2 mg/dia para controle de episódios\nde agitação psicomotora frequentes. A referida instituição localiza-se na área de abrangência de\numa Unidade Básica de Saúde, cujo médico de família é chamado para discutir a conduta com o\nnovo responsável pela instituição. Nessa situação, o médico de família deve","options":{"A":"construir novo plano de cuidado para os cuidadores, com ajuste medicamentoso.","B":"discutir e implementar cuidados paliativos junto aos cuidadores e responsáveis na instituição.","C":"construir genograma e ecomapa para estabelecer plano terapêutico orientado aos cuidadores da\npaciente na instituição.","D":"aplicar miniexame do estado mental para estabelecer o grau de comprometimento mental da\npaciente e as condutas adequadas."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-168505","number":"168505","sourceNumber":"168505","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma criança do sexo masculino com 8 anos de idade é atendida em consulta com\nmédico de Unidade Secundária de Saúde para\navaliação de transtorno de comportamento. A mãe\nrelata que o filho perde material escolar com frequência, costuma esquecer as tarefas do dia-a-dia\ne demora a atender quando chamado pelo nome. Informa, ainda, que a criança é repreendida na\nescola por não parar no mesmo lugar, levantar-se o tempo todo da cadeira, falar demais e\nintrometer-se na conversa alheia, além de ter notas ruins. O exame clínico evidencia\nanormalidades. O diagnóstico e a conduta adequados ao caso são","options":{"A":"desenvolvimento normal, com comportamentos comuns na infância; orientar a família.","B":"transtorno de déficit de atenção/hiperatividade; iniciar tratamento com risperidona.","C":"transtorno de espectro autista; encaminhar o paciente para atendimento especializado.","D":"transtorno de déficit de atenção/hiperatividade; iniciar tratamento com metilfenidato."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-133979","number":"133979","sourceNumber":"133979","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente masculino de 32 anos de idade, em acompanhamento irregular em diversos\nserviços de psiquiatria em razão de transtorno ansioso generalizado e dependência de\nbenzodiazepínicos, agitado e trêmulo, invade sala de atendimento. Considerando essa situação\nhipotética e sabendo que, logo em seguida, o paciente manifestou um dos sinais maiores da\nsíndrome de abstinência por benzodiazepínicos, de acordo com o Projeto Diretrizes - Abuso e\nDependência dos Benzodiazepínicos, assinale a alternativa correta em relação ao sinal\napresentado.","options":{"A":"Náuseas.","B":"Vômitos.","C":"Pesadelos.","D":"Irritabilidade.","E":"Convulsões."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-129014","number":"129014","sourceNumber":"129014","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um paciente com 23 anos de idade foi vítima de acidente ofídico e procurou\natendimento médico queixando-se de pouca dor\nno local da picada, boca seca, diplopia, dificuldade\nde deglutição, dores musculares generalizadas, oligúria e urina com coloração vermelha escura. Ao\nexame, apresentou ptose palpebral bilateral, midríase e plegia dos pares cranianos III, IV e VI. O\nresultado do exame de urina evidenciou mioglobinúria. Com base nesse caso hipotético, assinale a\nalternativa que apresenta o tipo de acidente ofídico descrito.","options":{"A":"Crotálico.","B":"Botrópico.","C":"Laquético.","D":"Elapídico.","E":"Colubrídeo."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-111342","number":"111342","sourceNumber":"111342","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Assinale a alternativa que apresenta característica do quadro de delirium (confusão\nmental aguda) no idoso:","options":{"A":"Demosntração de distúrbio da consciência com redução do alerta em relação ao ambiente.","B":"Preservação da memória de fixação.","C":"Baixo comprometimento da linguagem e da cognição.","D":"Desenvolvimento gradual do quadro ao longo de meses ou anos.","E":"Presença de sintomas como agressividade e alimentação compulsiva."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-97798","number":"97798","sourceNumber":"97798","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Um homem com 38 anos de idade vem à consulta no ambulatório de clínica médica\nencaminhado da unidade básica de saúde por apresentar episódios recorrentes de cefaleia. As\ncrises iniciaram-se há dois anos, com cefaleia unilateral esquerda, de forte intensidade,\nacompanhada de lacrimejamento, rinorreia e ptose palpebral do mesmo lado da dor, durando de 20\na 30 minutos. O paciente relata que as crises ocorrem diariamente por cerca de duas semanas,\ncessando completamente e reiniciando, aproximadamente, seis meses depois. Os últimos\nepisódios ocorreram há quatro meses. O paciente refere uso de analgésicos comuns e naproxeno\ndurante as crises, relatando alívio apenas parcial, e nega a ocorrência de aura ou presença de\nfatores desencadeantes. A hipótese diagnóstica e a conduta a ser adotada para esse paciente são:","options":{"A":"Enxaqueca sem aura, sendo indicado iniciar profilaxia com amitriptilina.","B":"Arterite de células gigantes, necessitando de avaliação pelo reumatologista.","C":"Cefaleia tensional, devendo ser prescrito relaxante muscular como ciclobenzaprina.","D":"Cefaleia em salvas, devendo o paciente ser encaminhado para avaliação do neurologista."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-64439","number":"64439","sourceNumber":"64439","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente feminina, 65 anos, hipertensa, diabética e obesa, iniciou há mais ou menos 1\nhora quadro súbito de hemiparesia completa à direita. Realizou tomografia computadorizada de\ncrânio em intervalo de 60 minutos que evidenciou: (VER IMAGEM). Paciente após o exame\nmantém o quadro neurológico. O próximo passo será:","options":{"A":"Alta com acompanhamento ambulatorial com neurologista","B":"Se não houver contraindicações deve-se realizar terapia trombolítica o quanto antes","C":"Internação por 24 horas para acompanhamento","D":"Realização de punção liquórica","E":"Expansão volêmica agressiva"},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-75554","number":"75554","sourceNumber":"75554","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança com 11 anos de idade, frequentando o quarto ano do ensino fundamental, é\nencaminhada ao pediatra pela escola por apresentar indisciplina e problemas de aprendizagem. A\ndiretora solicita encaminhamento para o neurologista, psicólogo e oftalmologista. Na consulta em\nUnidade Básica de Saúde, a mãe conta que a classe da criança já teve três trocas de professora no\nano corrente, e que em casa a criança é muito esperta e cuida do irmão de 5 anos, no horário em\nque ela está trabalhando. Levando em consideração a Reforma Psiquiátrica Brasileira, o Movimento\nde Luta Antimanicomial e a Política Nacional de Saúde Mental, a conduta adequada é:","options":{"A":"Valorizar o prejuízo que a criança já tem em decorrência do atraso na escolarização, instituindo\ntratamento clínico para transtorno de hiperatividade e déficit de atenção com ritalina e\npsicoterapia\nno Centro de Atenção Psicossocial (CAPS).","B":"Prevenir a piora do quadro e a possibilidade de internação em hospital psiquiátrico por\nintermédio da pronta referência do caso ao\npsiquiatra, antes que ocorra recrudescimento e seja\nimperioso o tratamento manicomial.","C":"Agendar os procedimentos ambulatoriais requisitados, em cumprimento ao princípio da\nintersetorialidade da Lei n.º 8.080/1990,\ncom cobertura pelo benefício financeiro do Programa \"De\nVolta Para Casa\".","D":"Acionar o Conselho Tutelar mediante denúncia de bullying e assédio moral da escola contra a\ncriança, pela repetência serial e tentativa de culpabilizar a vítima pelo próprio agravo sofrido.","E":"Orientar a mãe a respeito da possibilidade de o\n\ncomportamento da criança dever-se a situações sociais do entorno escolar e/ou doméstico, e\nviabilizar contato da Equipe de Saúde da Família com a escola."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-75564","number":"75564","sourceNumber":"75564","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem com 38 anos de idade, pedreiro, vem à Unidade Básica de Saúde com relato\nde dor lombar contínua há uma semana, aos\nesforços acentuados, a qual não causa limitação de\nsuas atividades diárias. Informa, com bastante firmeza, diminuição da sensibilidade na face lateral\nda perna esquerda. Ao exame físico apresenta dor à digitopressão lombar com teste de Lasègue\nnegativo bilateralmente. A conduta a ser adotada na sequência deve ser:","options":{"A":"prescrever anti-inflamatórios não esteróides e fisioterapia.","B":"solicitar ressonância nuclear magnética da coluna vertebral.","C":"prescrever infiltração com corticoesteroides.","D":"afastar o paciente do trabalho por 30 dias.","E":"solicitar cintilografia de coluna vertebral."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-352179","number":"352179","sourceNumber":"352179","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Escolar com 7 anos, deu entrada na emergência com quadro de convulsão\n\ntônico-clônica generalizada de início há cerca de 20 minutos. Mãe refere o diagnóstico de paralisia\ncerebral e epilepsia. Faz uso regular de carbamazepina, mas a medicação acabou há 3 dias. No\nmomento está monitorado, afebril, com via aérea segura e oxigênio nasal. Frequência cardíaca:\n110 bpm, pressão arterial: 110/70 mmHg. Glicemia capilar de 90 mg%. Exames laboratoriais foram\ncoletados. Com relação ao tratamento medicamentoso a ser instituído podemos afirmar:","options":{"A":"Fenobarbital por via venosa deve ser a medicação de primeira linha, mas apresenta risco de\ndepressão respiratória e hipotensão.","B":"Trata-se de um estado de mal epiléptico refratário com risco de sequelas neurológicas graves,\nportanto deve ser intubado e iniciar tiopental ou midazolam contínuos.","C":"Fenitoína por via venosa deve ser a medicação de primeira linha pois tem efeito para cessar o\nevento convulsivo vigente, além de ter efeito profilático para novas crises.","D":"Benzodiazepínico por via venosa deve ser a medicação de primeira linha, mas pode ser\nadministrado por via intramuscular, retal ou nasal caso não possua acesso venoso."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-354083","number":"354083","sourceNumber":"354083","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 93 anos de idade, doença de Alzheimer em fase grave (FAST 7b), em uso de\ndonepezila, memantina, sertralina e olanzapina. Além de valsartana, anlodipina, hidroclorotiazida\npara hipertensão; metformina e glibenclamida para diabetes; sinvastatina para dislipidemia;\nglicosamina com condroitina em pó para osteoartrite; alendronato, cálcio e vitamina D para\nosteoporose; e paracetamol para dor. Ela começou a apresentar dificuldades para aceitar os\nmedicamentos, ora recusando-os ora retendo-os na boca. Nesse caso, qual deve ser a conduta\nmais adequada?","options":{"A":"amassar e dissolver todos os medicamentos de uso habitual nos alimentos e líquidos.","B":"acrescentar um medicamento inibidor de bomba de prótons para proteção gástrica.","C":"otimizar a prescrição e avaliar a desprescrição dos medicamentos inapropriados.","D":"introduzir sonda nasoenteral para garantir o fornecimento de todos os medicamentos.","E":"solicitar internação hospitalar para administração parenteral de medicações equivalentes e\nsuplementação nutricional."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-336260","number":"336260","sourceNumber":"336260","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, jovem, falece em UTI de grande hospital, após ser resgatado de acidente\nmotociclístico, com o qual não foi encontrado\nnenhum documento. Três pessoas se identificaram\ncomo familiares da vítima: pai, mãe e um tio que é portador de insuficiência renal crônica e\nsubmetido a hemodiálise 3 vezes por semana. Informaram ao Hospital que o rapaz falecido tinha 20\nanos e que havia perdido todos os documentos em um assalto, além de manifestarem vontade de\ndoação de rim para o tio com nefropatia. De acordo com a legislação atual, qual deve ser a conduta\nda Central de Transplantes?","options":{"A":"Aceitar a doação, pois, de acordo com o Decreto Federal N° 9175 de 18 de outubro de 2017,\nCapítulo III, Seção II, Parágrafo Único: ?Não supre as exigências do caput o simples\nreconhecimento de familiares se nenhum dos documentos do falecido for encontrado, exceto nas\nhipóteses em que autoridade oficial que detenha fé pública certifique a identidade?, logo, sendo\npossível a realização desta doação.","B":"Recusar a doação, pois, de acordo com o Decreto Federal N° 9175 de 18 de outubro de 2017,\nCapítulo III, Seção II, Parágrafo Único: ?Não supre as exigências do caput o simples\nreconhecimento de familiares se nenhum dos documentos do falecido for encontrado[...]?, logo o\nconsentimento das pessoas envolvidas não será válido.","C":"Aceitar a doação, pois, de acordo com o Decreto Federal N° 9175 de 18 de outubro de 2017,\nCapítulo III, Seção I, Art. 17: ?A retirada\nde órgãos, tecidos, células e partes do corpo humano\npoderá ser efetuada após a morte encefálica, com o consentimento expresso da família, conforme\nestabelecido na Seção II deste Capítulo.?, logo, como a família está presente, não há impedimento\npara a doação.","D":"Aceitar a doação, pois, de acordo com o Decreto Federal N° 9175 de 18 de outubro de 2017,\nCapítulo III, Seção II, Segundo Parágrafo: ?Caso seja utilizada vontade de parente de segundo\ngrau, deverão estar circunstanciadas, no termo de autorização, as razões de impedimento dos\nfamiliares de primeiro grau.?, logo como os pais estão presentes e de acordo com a doação, não\nhá impedimentos."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-337626","number":"337626","sourceNumber":"337626","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente sexo masculino, 32 anos, procurou atendimento no pronto atendimento\nreferindo que iniciou há cerca de uma semana\ncom uma dor de cabeça importante, unilateral,\nintermitente e predominantemente à noite. Relata ainda que apresenta corrimento nasal e ocular\nassociados. Sem comorbidades nem uso de medicações, informa que não apresentou melhora com\ndipirona. Assinale a alternativa que apresenta CORRETAMENTE a principal hipótese diagnóstica e\nconduta.","options":{"A":"Cefaleia por abuso de analgésicos e iniciar naproxeno.","B":"Migrânea como áurea e iniciar triptanos.","C":"Hemorragia subaracnoidea e pedir TC de crânio.","D":"Cefaleia em salvas e oxigenoterapia."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-320435","number":"320435","sourceNumber":"320435","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em consulta de rotina, lactente com 18 meses, observa-se as seguintes medidas\nevolutivas do perímetro cefálico (PC): ao\nnascer (35 cm), 1 mês (37 cm), 4 meses (42 cm), 7 meses\n\n(44 cm), 9 meses (44,5 cm), 12 meses (44,5 cm). Desenvolvimento: sorriso social com dois meses,\ngargalhadas com quatro meses, sentou-se com sete meses, arrastou-se com nove meses e\nbalbucio de sons consonantais com dez meses. Atualmente, não fica de pé com apoio, não\nengatinha, emite sons guturais, não pega o brinquedo ou objetos em seu campo de alcance. Tem\ncontato visual, mas não compreende jogos de esconde-esconde, dança, acenar adeus ou bater\npalmas. Realiza movimentos repetitivos e estereotipados de mãos, do tipo lavar ou esfregar. Há um\nmês apresentou quatro crises convulsivas tônico-clônicas generalizadas. O diagnóstico sindrômico\né:","options":{"A":"Transtorno do espectro autista.","B":"Atraso do desenvolvimento neuropsicomotor.","C":"Paralisia cerebral.","D":"Regressão do desenvolvimento neuropsicomotor.","E":"Não apresenta alterações do crescimento e desenvolvimento."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-336286","number":"336286","sourceNumber":"336286","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Menina, 9 anos, deu entrada no PS em crise convulsiva caracterizada por movimentos\ntônico clônicos generalizados associados a\nperda de controle esfincteriano e perda da consciência\nhá 30 minutos. Após realização de 3 doses de diazepam endovenoso, paciente mantinha em crise\nconvulsiva. A próxima medicação a ser feita é:","options":{"A":"Carbamazepina","B":"Tiopental","C":"Lorazepam","D":"Fenitoína"},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-291918","number":"291918","sourceNumber":"291918","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma menina de 7 anos é avaliada no pronto atendimento com queixa de cefaleia que,\nsegundo a mãe, teve início há três meses, com intensidade progressiva. A dor atinge toda a cabeça\ne piora ao acordar. Ao exame clínico, notou-se alteração do equilíbrio e da coordenação motora.\n\nNesse caso, é CORRETO afirmar que o exame indicado como complementar ao diagnóstico, é:","options":{"A":"A radiografia do crânio.","B":"O eletroencefalograma.","C":"O eletroneuromiografia.","D":"A ressonância magnética de crânio."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-313281","number":"313281","sourceNumber":"313281","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Após quadros neurológicos graves, um dos instrumentos indicados para\nacompanhamento e avaliação é a escala de coma\nde Jouvet. Não é parâmetro ligado a essa\nescala:","options":{"A":"Perceptividade.","B":"Reatividade inespecífica.","C":"Reatividade autonômica.","D":"Padrão de resposta motora.","E":"Reatividade específica à dor."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-304847","number":"304847","sourceNumber":"304847","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma paciente de 45 anos, previamente hígida foi admitida por fraqueza de instalação\naguda nos membros inferiores e dor ao longo da\nface interna de ambas as coxas e retenção\nurinária há 8 dias. Ao exame, observou-se paraparesia crural, hiperreflexia patelar e aquilina -\ndemais reflexos estavam normoativos, reflexo plantar em extensão bilateralmente, hipoestesia tátil\ne hipopalestesia com nível em T10. Qual a hipótese diagnóstica para este caso?","options":{"A":"Mielopatia longitudinalmente extensa.","B":"Mielorradiculopatia esquistossomótica.","C":"Mielopatia espondilótica.","D":"Síndrome de Guillain-Barrè."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-314033","number":"314033","sourceNumber":"314033","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A síndrome de Guillain-Barré (SGB) corresponde a uma neuropatia periférica\ninflamatória adquirida de início agudo. Em relação a essa síndrome, assinalar a alternativa\nCORRETA:","options":{"A":"Cursa com níveis elevados de proteína no líquido cefalorraquiano, com baixas contagens de\ncélulas (dissociação albumino-citológica).","B":"A neuropatia axonal motora aguda, um tipo de síndrome de Guillain-Barré, responsabiliza-se\npela maioria dos casos de SGB.","C":"Apesar de frequentemente causar uma \"\"paralisia ascendente\"\", os reflexos profundos\ncostumam estar normais/preservados.","D":"O botulismo, um dos diagnósticos diferenciais possíveis, produz paralisia espástica rapidamente\nprogressiva, com sintomas sensitivos.","E":"O uso de corticoides intravenosos utilizados isoladamente no tratamento da SGB tem-se\nmostrado igualmente eficaz quando comparado à imunoglobulina intravenosa isolada."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-314034","number":"314034","sourceNumber":"314034","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A Doença de Alzheimer (DA) é uma doença neurodegenerativa crônica, com um início\ninsidioso e progressivo, mas um declínio lento. A DA é o tipo de demência mais comum. Em\nrelação a essa patologia, assinalar a alternativa CORRETA:","options":{"A":"Causas reversíveis de transtornos cognitivos devem ser excluídas com exames laboratoriais\niniciais e exames de imagem cerebral, como\ndeficiência de vitamina B12.","B":"RNM cerebrais normalmente revelam atrofia estrutural nos lobos frontais e/ou temporais,\ncaracterísticos da DA.","C":"A maioria dos casos de DA é decorrente de doença/alteração genética.","D":"Antagonistas do receptor NMDA, como a memantina, não parecem retardar a progressão do\ndeclínio funcional em pacientes com DA.","E":"Ausência de doenças cardiovasculares é necessário para o diagnóstico de DA."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-306718","number":"306718","sourceNumber":"306718","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Sobre a apresentação clínica de uma criança portadora de transtorno de espectro\nautista na infância, qual característica é\nprovável de se encontrar?","options":{"A":"Movimentos corporais estereotipados","B":"Capacidade para fazer amizade com seus pares","C":"Habilidade para sustentar uma conversação","D":"Interesse em histórias sobre acontecimentos imaginários"},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283883","number":"283883","sourceNumber":"283883","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na avaliação de indivíduos geriátricos, é fundamental a avaliação e classificação de\nsuas atividades (básicas ou instrumentais)\ndiárias. Das atividades abaixo, é classificada como\natividade instrumental de vida diária a capacidade de:","options":{"A":"Se vestir.","B":"Tomar banho.","C":"Cozinhar.","D":"Realizar sua própria toalete.","E":"Deslocar-se da cama para a cadeira."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-257341","number":"257341","sourceNumber":"257341","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 65 anos apresenta queda da própria altura e é levado ao pronto\natendimento. É portador de hipertensão\narterial sistêmica e fibrilação atrial. Faz uso irregular de\nhidroclorotiazida, enalapril, anlodipino, clonidina e rivaroxabana. Ao exame físico, PA: 226 X 122\nmmHg, FC: 102 bpm, FR: 22 ipm. Apresenta-se sonolento, abre os olhos, verbaliza ao chamado e\nobedece aos comandos. Apresenta redução da força no dimidio esquerdo. Sem outras\nanormalidades. Considerando o caso descrito, assinale a alternativa que apresenta uma conduta\nINADEQUADA para esse paciente.","options":{"A":"Administrar concentrado de complexo protrombínico.","B":"Administrar glicocorticoide IV.","C":"Elevar a cabeceira a 30 ?.","D":"Reduzir a PA sistólica para 140 a 160 mmHg com drogas parenterais."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283927","number":"283927","sourceNumber":"283927","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de 7 anos, após episódio de gastroenterite e febrícula, iniciou com quadro de\ncansaço e diminuição de força nas pernas\ncom manifestações ascendentes, contínuas, simétricas e\nprogressivas. Tem apresentado perda do controle esfincteriano, hiporreflexia tendinosa profunda e\nhipertensão arterial. A mais provável hipótese diagnóstica é:","options":{"A":"Polirradiculoneuropatia.","B":"Poliomielite.","C":"Miastenia gravis.","D":"Mielite transversa aguda.","E":"Polimiosite aguda."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-283934","number":"283934","sourceNumber":"283934","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem, 67 anos, procura atendimento após segundo episódio de perda de força em\nmembro superior e inferior direito com recuperação total. Nega alteração em expressão de face,\nfala e sensibilidade. No exame físico, apresenta-se hipertenso, sem detecção de hipotensão\npostural, ritmo cardíaco irregular, força preservada em membros superiores e inferiores. Qual\nhipótese diagnóstica mais provável a ser considerada nesse caso?","options":{"A":"Ataque isquêmico transitório.","B":"Acidente vascular isquêmico.","C":"Transtorno conversivo.","D":"Síndrome de Von Recklinghausen.","E":"Hipoglicemia."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-287907","number":"287907","sourceNumber":"287907","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação aos Transtornos Mentais na Infância e na Adolescência, analisar os itens\nabaixo: I. Testes de inteligência ou medidas neuropsicológicas, bem como exames\ncomplementares, como eletroencefalograma ou neuroimagem, precisam ser realizados\nrotineiramente na avaliação diagnóstica do Transtorno de Déficit de Atenção e Hiperatividade. II.\nDevido à associação dos antidepressivos inibidores seletivos de recaptação de serotonina com\neventos adversos anticolinérgicos, somados às alterações eletrocardiográficas e dos relatos de\nmorte súbita, faz com que os mesmos não sejam utilizados no tratamento dos quadros depressivos\nna população infantil. III. A bulimia nervosa possui como características essenciais as compulsões\nperiódicas e os métodos compensatórios inadequados para evitar o ganho de peso. IV. O\nTranstorno de Espectro Autista é mais frequente em meninos. Está(ão) CORRETO(S):","options":{"A":"Somente o item II.","B":"Somente os itens I e II.","C":"Somente os itens II e III.","D":"Somente os itens III e IV.","E":"Somente os itens II, III e IV."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-255618","number":"255618","sourceNumber":"255618","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mãe chega à consulta médica com a seguinte queixa em relação à sua filha: ?Ela\nme mostrou este desenho e eu sabia que significava triste, que é como eu me senti quando\nencontrei o cachorro morto. Então ela me mostrou este desenho e eu sabia que significava feliz,\nque é como eu fico quando estou lendo sobre as missões espaciais Apollo. Então ela desenhou\noutras caras, mas eu não consegui saber o que elas significavam.? Sobre o Transtorno do Espectro\nAutístico (TEA) MARQUE A CORRETA:","options":{"A":"A idade usual para seu diagnóstico é em torno de 3 anos de idade, embora seja sugerido que\nesse diagnóstico já possa ser bem estabelecido ao\nredor dos 18 meses de idade.","B":"O déficit na comunicação social não é um critério diagnóstico necessário para a caracterização\ndo TEA.","C":"Quanto à sua epidemiologia, sua prevalência pode ser estimada em menor que 1 para cada\n\n10.000 crianças.","D":"A associação de quadros autísticos não está normalmente associada a infecções pré-natais\ncomo rubéola congênita, sífilis congênita,\ntoxoplasmose e citomegalovirose."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-227246","number":"227246","sourceNumber":"227246","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 24 anos deu entrada no Pronto Socorro com abalos tônico-clônicos com\nduração de cerca de 30 minutos,\nmantendo-se inconsciente. Apresenta febre de 39,2ºC, sem sinais\nde trauma. O diagnóstico deste paciente é:","options":{"A":"Estado de mal convulsivo.","B":"Intoxicação exógena.","C":"Convulsão febril.","D":"Epilepsia."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234410","number":"234410","sourceNumber":"234410","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Uma mulher de 26 anos se queixa de crises de cefaleia unilateral, pulsátil, muito\nintensa, que dura um dia inteiro e\nacompanha-se de náuseas. Não apresenta melhora com o uso\nde dipirona, paracetamol e ibuprofeno. As crises ocorrem 2 vezes por semana e comprometem a\nfuncionalidade da paciente. Não possui doenças atuais ou histórico de doenças prévias e não faz\nuso diário de medicamentos. Ao exame físico, apresenta-se alerta e orientada. Os dados vitais são\nPA: 150 X 88mmHg, FC: 86bpm, FR: 16ipm e SpO? 98%. O restante do exame físico não\napresenta anormalidades. Considerando o quadro clínico descrito, assinale alternativa que\napresenta a conduta MAIS ADEQUADA para o tratamento das crises e para a prevenção das\ncefaleias, respectivamente:","options":{"A":"Di-hidroergotamina; hidroclorotiazida.","B":"Naratriptano; metoprolol.","C":"Prednisona; topiramato.","D":"Tramadol; venlafaxina."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-227080","number":"227080","sourceNumber":"227080","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mulher de 76 anos é levada ao consultório por causa de dificuldade de marcha, com\npiora progressiva nos últimos 6 meses. É\nportadora de Diabetes Mellitus, gastroparesia diabética e\nlabirintopatia, e faz uso de metformina, glimepirida, domperidona e flunarizina regularmente há 1\nano. Ao exame físico, está alerta, orientada com as mucosas coradas, hidratadas e anictéricas. Há\nbradicinesia, tremor de repouso e cinético nas mãos e rigidez simétrica, nos membros superiores e\ninferiores. Sem outras anormalidades ao exame físico. Considerando o caso descrito, assinale a\nalternativa que apresenta a conduta imediata MAIS ADEQUADA a ser adotada para essa paciente:","options":{"A":"Prescrever a amantadina.","B":"Prescrever a levodopa/benserazida.","C":"\"Suspender a domperidona e prescrever a\nmetoclopramida.\"","D":"Suspender a flunarizina."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-227255","number":"227255","sourceNumber":"227255","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Homem de 72 anos, hipertenso, tabagista, apresentou quadro de mal súbito,\npermanecendo inconsciente por cerca de 10 minutos.\nFoi levado ao pronto-socorro onde, após 6\nhoras do início do quadro, permanece consciente, afásico, com desvio de comissura labial para\nesquerda e hemiparesia à direita, pressão arterial de 145/100 mmHg. O diagnóstico e tratamento\npara este paciente são, respectivamente:","options":{"A":"AVC isquêmico de artéria cerebral média direita, tratamento trombolítico.","B":"AVC isquêmico de artéria cerebral média direita, tratamento conservador.","C":"AVC isquêmico de artéria cerebral média esquerda, tratamento conservador.","D":"AVC hemorrágico subaracnoide direita, tratamento conservador."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-246732","number":"246732","sourceNumber":"246732","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O uso de vários medicamentos pode levar a quadro Parkinsonismo. NÃO causa(m) o\nParkinsonismo a(s) seguinte(s) droga(s):","options":{"A":"Neurolépticos atípicos;","B":"Ácido Valpróico;","C":"Fluoxetina;","D":"Primidona;","E":"Carbonato de Lítio."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-234430","number":"234430","sourceNumber":"234430","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Criança de 3 anos, vem para consulta devido a atraso do desenvolvimento\ncaracterizado por déficit de interação social,\natraso na fala e alteração de comportamento com\nestereotipias e hábitos repetitivos. Mãe relata que desde os 18 meses percebia estas alterações.\nDiante do caso descrito, assinale a PRIORIDADE a ser adotada.","options":{"A":"Reabilitação multiprofissional com fonoaudiologia, terapia ocupacional e psicoterapia.","B":"Solicitar tomografia computadorizada de crânio e estudo genético.","C":"Iniciar metilfenidato.","D":"Observar, porque cada criança tem um ritmo de desenvolvimento."},"answer":"A","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-232133","number":"232133","sourceNumber":"232133","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Mãe de um lactente de quatro meses está preocupada, pois seu filho não sustenta a\ncabeça. História perinatal: parto vaginal, banhado em mecônio espesso, necessitando de\nreanimação na sala de parto, Apgar 1/4/7, peso: 2.800 g, comprimento: 49 cm. Exame físico: eleva\nmomentaneamente a cabeça em posição de prono e sorri, faz semiflexão dos cotovelos e pronação\ndo antebraço e flexão de punhos e dedos, reflexo tônico cervical assimétrico, reflexo de Moro\nexacerbado. Nessa situação, deve-se informar à mãe que seu filho apresenta","options":{"A":"distúrbio neuropsicomotor pela asfixia perinatal e que terá um atraso definitivo físico e\nmental.","B":"distúrbio neuropsicomotor temporário pela asfixia perinatal e que irá se desenvolver\nnormalmente.","C":"distúrbio neuropsicomotor pela asfixia perinatal e necessita de acompanhamento\nmultiprofissional.","D":"limites normais do desenvolvimento neuropsicomotor e necessita de estimulação em casa.","E":"limite normal do desenvolvimento neuropsicomotor, devendo manter acompanhamento habitual."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-227120","number":"227120","sourceNumber":"227120","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"O crescimento da população de idosos do Brasil tem sido sistemático e consistente. A\natenção ao idoso requer a avaliação de múltiplos domínios. O médico da equipe B realiza uma\nvisita domiciliar para uma avaliação multidimensional de um idoso de sua equipe. Analise os\naspectos importantes de serem abordados a seguir: I- Estado mental e avaliação do humor. II-\nRiscos de acidentes domiciliares e função dos membros inferiores. III- Atividades diárias IV-\nContinência urinária. V- Suporte social. Está(ão) CORRETO(S) o(s) aspecto(s) previsto(s) em:","options":{"A":"III apenas.","B":"I, II, III, IV e V.","C":"IV apenas.","D":"I, II e IV apenas."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-243032","number":"243032","sourceNumber":"243032","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Na Síndrome de Compressão Medular relacionada à malignidade, podemos encontrar,\nEXCETO:","options":{"A":"dor na área afetada.","B":"fraqueza muscular.","C":"disfunção esfincteriana.","D":"hiper-reflexia abaixo do nível da compressão.","E":"vômitos matutinos."},"answer":"E","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-227319","number":"227319","sourceNumber":"227319","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A respeito da convulsão febril é correto afirmar que:","options":{"A":"Caracteriza-se por duração maior de 30 minutos.","B":"Necessita da realização de punção lombar em todos os casos.","C":"Constitui um evento mais frequente acima dos cinco anos de idade.","D":"Associa-se a febre, não recorrendo, na maioria dos casos, na mesma doença febril."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-246797","number":"246797","sourceNumber":"246797","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Dentre os aspectos clínicos abaixo, qual é característico da crise convulsiva febril\nsimples?","options":{"A":"A crise geralmente é focal e de curta duração.","B":"A incidência é mais elevada entre 6 meses e 60 meses de vida.","C":"Tem grande relação com alterações cognitivas no futuro.","D":"Geralmente recorre em 24 horas.","E":"Em geral duram mais de 15 minutos."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-199635","number":"199635","sourceNumber":"199635","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Paciente de 58 anos de idade foi admitido no pronto-socorro por cefaleia supraorbitária\ndireita, de fortíssima intensidade,\nintermitente (2 a 4 eventos ao dia), com duração aproximada de 1\nhora, há 4 dias. Nos últimos 5 anos, o paciente apresentou cerca de 8 crises com características\nsemelhantes às da atual, com duração aproximada de 1 mês. Ao exame foram constatadas as\nseguintes alterações: edema palpebral, hiperemia conjuntival, miose e lacrimejamento restritos ao\nolho direito. Qual das condutas emergenciais abaixo é a mais apropriada para o caso?","options":{"A":"Abortamento da crise com dexametasona endovenosa (dose única) e alta para investigação\nambulatorial.","B":"Abortamento da crise com inalação de oxigênio e alta para investigação ambulatorial.","C":"Abortamento da crise com anti-inflamatório endovenoso, tomografia e angiotomografia do crânio\ne internação para investigação.","D":"Dipirona endovenosa, tomografia do crânio com e sem contraste e punção lombar se tomografia\nnormal."},"answer":"B","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-212904","number":"212904","sourceNumber":"212904","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Em relação ao estado epilético podemos afirmar que:","options":{"A":"Estado de mal epiléptico se caracteriza pela presença de crise convulsiva que dure no mínimo\n10 minutos.","B":"A primeira medida a ser tomada numa crise convulsiva é a infusão de diazepam 10 mg IV.","C":"No estado de mal epiléptico, após a crise ser abortada, está indicado o uso de fenitoína 20\nmg/kg de peso.","D":"Antidepressivos tricíclicos podem estar associados a crise epilépticas, ao passo que os\nantidepressivos serotoninérgicos não.","E":"A maior parte dos pacientes com crise única na emergência apresentará recorrência das crises\nem até 6 meses, se não receber drogas antiepilépticas para uso crônico."},"answer":"C","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-212912","number":"212912","sourceNumber":"212912","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"A Síndrome da Fragilidade (SF) vem sendo amplamente estudada nas últimas décadas,\ne seus conceitos vêm sofrendo modificações.\nAssociada inicialmente com incapacidade funcional e\ncomorbidade, hoje se sabe que ela é uma entidade à parte, na qual nem todo indivíduo frágil é\nincapaz ou apresenta comorbidades e vice-versa. Sobre isso, assinale a alternativa CORRETA.","options":{"A":"Síndrome da Fragilidade como uma síndrome de declínio de energia que ocorre em espiral,\nembasado em um tripé de alterações relacionadas ao envelhecimento, composto, principalmente,\npor mialgias, desregulação neuroendócrina e disfunção imunológica.","B":"Fried e colaboradores propuseram um teste rápido para rastreamento de indivíduos frágeis. Eles\navaliaram cinco itens - força do braço, velocidade de marcha, perda de peso, exaustão física e\natividade física.","C":"Segundo o modelo proposto por Fried et col., os indivíduos são classificados como frágeis se\napresentarem alterações em dois ou mais itens, dentre os cinco propostos para rastreio da SF.","D":"Perda de peso não intencional (? 4,5 kg ou 5% do peso corporal no ano anterior); é um\nmarcador físico do Fenótipo de Fragilidade.","E":"Estudos identificaram que, enquanto a fraqueza muscular se manifesta no final e é reversível, a\nexaustão e a perda de peso são marcadores evidenciados no início do ciclo de fragilidade e\nindicam idosos com tendência a uma progressão rápida desse ciclo."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-neurologia-neu-unico-215150","number":"215150","sourceNumber":"215150","collectionBlock":"medcurso:medcurso-neurologia-neu-unico","collectionLabel":"Medcurso · NEU UNICO","documentBlock":"","area":"Neurologia","specialty":"Neurologia","topic":"NEU UNICO","subtopic":"","stem":"Durante consulta clínica na Unidade Básica de Saúde, uma mulher com 86 anos de\nidade está sendo acompanhada por sua filha,\nque externa preocupação com o risco da ocorrência\nde acidentes domésticos que envolvam a sua genitora. A filha informa que sua mãe vem\napresentando declínio progressivo de várias de suas funções cognitivas, tendo recebido o\ndiagnóstico, há cerca de um ano, de doença de Alzheimer. Ultimamente, relata a filha, a mãe vem\nesquecendo o fogão aceso, deixando o gás do banheiro ligado e cometendo outros esquecimentos.\nMenciona ainda o problema de quedas frequentes, tendo sido a paciente classificada como ?idosa\nfrágil?, portadora de significativa sarcopenia. A filha acrescenta que a família está preocupada,\nbuscando auxílio no sentido de obter orientações quanto às medidas que devem ser tomadas para\na prevenção de acidentes domésticos e de proteção à paciente. Entre as intervenções voltadas ao\ncontrole de fatores extrínsecos relacionados à ocorrência de quedas dessa paciente idosa, a\nrecomendação mais efetiva é:","options":{"A":"Utilizar calçados abertos com solado de couro, pois diminuem o atrito ao caminhar e a chance de\ntropeços.","B":"Limitar práticas corporais e atividades físicas rotineiras, posto que a fadiga induzida\npredispõe ao\nrisco de quedas.","C":"Evitar luzes acesas durante a madrugada, o que torna o sono mais instável, facilitando o\ndespertar nesse período.","D":"Evitar a colocação de tapetes soltos, especialmente os de tecido, pois não permitem firmeza do\nidoso ao caminhar.","E":"Adquira sofás e cadeiras bem baixos, porque o grau de dificuldade exigido para se levantar é\nmenor, sendo que estes devem ser confortáveis e com braços."},"answer":"D","source":"Neurologia/NEU UNICO.txt","sourceLabel":"Medcurso · NEU UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Neurologia","NEU UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
